-- ##########################################################################################
-- RELEASE SECTION 01/28: APPLY-0173.sql
-- In plain words: Free-trial lockdown: 2 own rows per main list, no new catalog items, no studio-settings / export changes; paid studios unchanged.
-- ##########################################################################################
-- APPLY-0173.sql - paste into the Supabase SQL editor (staging first, then production).
-- Free-trial lockdown. Affects FREE TRIAL studios only (studio_subscriptions.status = 'trial'); paid studios unchanged.
-- Additive + idempotent: new triggers / helper functions; 11 RPCs wrapped (originals kept as *__pre0173). No table, column or row is changed or removed. Safe to run twice.
-- Rollback note: see the ROLLBACK paragraph at the top of the migration below (manual, function/trigger level only; no data involved).
begin;
-- 0173_trial_lockdown.sql - CANONICAL forward-only. REQUIRES 0166 (_is_trial_org), 0097 (is_demo), 0164 (_is_system_change).
--
-- In plain words (FREE TRIAL studios only; a paid studio never reaches any new check):
--   1  Creation cap: a trial studio may add at most 2 of its OWN rows (is_demo = false) per main
--      list: leads (clients), events / quotes, inventory items, vendors, staff, venues. Sample rows
--      (is_demo) do not count. The 3rd is refused: "Free trial limit reached (2). Upgrade to add more."
--   2  Menu & catalog: a trial studio can edit prices of existing dishes / packages / chair and plate
--      types, but cannot ADD new ones (dish_catalog, menu_templates, chair_types, plate_types).
--   3  Studio settings: a trial studio cannot change its studio / branding / billing details
--      (direct organizations UPDATE from the app), the studio account, the client link name,
--      client-link auto-expire, notification rules, photo-render settings.
--   4  Downloads / import / photo renders: the studio data archive + data export, Excel/CSV
--      smart import and photo renders (photo_render_begin) are refused for a trial studio.
--   5  my_trial_limits(): {trial, cap, used{...}} so the app can say so before the server refuses.
--   Every guard first asks _is_trial_org(); false -> unchanged behaviour. The sample master studio
--   and system work (clone, seed, migrations: no API claims) are exempt.
--   Wrapped RPCs: the original is kept as <name>__pre0173 (no grants) and a same-signature wrapper
--   (original grants copied) checks the trial, then calls it. Nothing is deleted. Safe to run twice.
--   A re-run only re-creates the wrappers (create or replace keeps their grants); nothing is dropped.
--   ROLLBACK (manual, only if ever needed): for each wrapped f: drop function public.f(args);
--   alter function public.f__pre0173(args) rename to f; re-grant execute as before; drop the
--   zzzz_tl173_* triggers. No data is touched either way.

-- ---- helpers --------------------------------------------------------------------------------------
create or replace function public._tl173_trial_locked(p_org uuid)
returns boolean language sql stable security definer set search_path = '' as $$
  -- trial-lockdown-0173: a trial studio (not the sample master) acting through the app
  select p_org is not null and public._is_trial_org(p_org)
     and not coalesce((select o.is_sample_master from public.organizations o where o.id = p_org), false);
$$;

create or replace function public._tl173_guard()
returns void language plpgsql stable security definer set search_path = '' as $$
-- trial-lockdown-0173: refuse a studio setting / download / import / render in the free trial
begin
  if public._tl173_trial_locked(public.current_org_id()) then
    raise exception 'Not available in the free trial. Upgrade to use this.' using errcode = '42501', hint = 'trial_locked';
  end if;
end $$;

-- ---- 1) creation cap (2 own rows per main list) ------------------------------------------------
create or replace function public._tl173_tg_create_cap()
returns trigger language plpgsql security definer set search_path = '' as $$
-- trial-lockdown-0173
declare v_n integer;
begin
  if new.org_id is null or coalesce(new.is_demo, false) then return new; end if;
  if public._is_system_change() then return new; end if;
  if not public._tl173_trial_locked(new.org_id) then return new; end if;
  perform pg_advisory_xact_lock(hashtextextended('helm:cap:' || tg_table_name || ':' || new.org_id::text, 0));
  execute format('select count(*) from public.%I x where x.org_id = $1 and not x.is_demo', tg_table_name) into v_n using new.org_id;
  if v_n >= 2 then
    raise exception 'Free trial limit reached (2). Upgrade to add more.' using errcode = '42501', hint = 'trial_cap';
  end if;
  return new;
end $$;

do $$ declare t text; begin
  foreach t in array array['leads', 'quotes', 'inventory_items', 'vendors', 'crew_members', 'venues'] loop
    if to_regclass('public.' || t) is not null
       and not exists (select 1 from pg_trigger where tgrelid = format('public.%I', t)::regclass and tgname = 'zzzz_tl173_cap') then
      execute format('create trigger zzzz_tl173_cap before insert on public.%I for each row execute function public._tl173_tg_create_cap()', t);
    end if;
  end loop;
end $$;

-- ---- 2) menu & catalog: prices editable, no new rows -------------------------------------------
create or replace function public._tl173_tg_no_add()
returns trigger language plpgsql set search_path = '' as $$
-- trial-lockdown-0173: SECURITY INVOKER on purpose (current_user = the app role). Only direct app
-- inserts are refused; Helm's own functions (trial start seed, clone) still add the starter catalog.
begin
  if current_user not in ('anon', 'authenticated') then return new; end if;
  if new.org_id is null or coalesce((to_jsonb(new) ->> 'is_demo')::boolean, false) then return new; end if;
  if public._tl173_trial_locked(new.org_id) then
    raise exception 'In the free trial you can change prices, but not add new menu or catalog items. Upgrade to add more.'
      using errcode = '42501', hint = 'trial_locked';
  end if;
  return new;
end $$;

do $$ declare t text; begin
  foreach t in array array['dish_catalog', 'menu_templates', 'chair_types', 'plate_types'] loop
    if to_regclass('public.' || t) is not null
       and not exists (select 1 from pg_trigger where tgrelid = format('public.%I', t)::regclass and tgname = 'zzzz_tl173_no_add') then
      execute format('create trigger zzzz_tl173_no_add before insert on public.%I for each row execute function public._tl173_tg_no_add()', t);
    end if;
  end loop;
end $$;

-- ---- 3a) studio / branding / billing details: no direct app edits in the trial ---------------------
create or replace function public._tl173_tg_org_lock()
returns trigger language plpgsql set search_path = '' as $$
-- trial-lockdown-0173: SECURITY INVOKER on purpose (current_user = the app role). Only direct app
-- edits are refused; Helm's own functions (welcome set-up, clone) still work.
begin
  if current_user not in ('anon', 'authenticated') then return new; end if;
  if to_jsonb(new) = to_jsonb(old) then return new; end if;
  if public._tl173_trial_locked(old.id) then
    raise exception 'Studio settings are fixed in the free trial. Upgrade to change them.' using errcode = '42501', hint = 'trial_locked';
  end if;
  return new;
end $$;

do $$ begin
  if not exists (select 1 from pg_trigger where tgrelid = 'public.organizations'::regclass and tgname = 'zzzz_tl173_org_lock') then
    create trigger zzzz_tl173_org_lock before update on public.organizations for each row execute function public._tl173_tg_org_lock();
  end if;
end $$;

-- ---- 3b / 4) wrapped RPCs ---------------------------------------------------------------------------
do $$
declare
  f text; v_new boolean; v_old regprocedure; v_pre regprocedure; v_name text; v_args text; v_idargs text; v_ret text; v_call text; n int; g record;
begin
  foreach f in array array[
    'public.export_tenant_organization_package()', 'public.export_org_data()',
    'public.smart_import_batch(text,jsonb,jsonb)',
    'public.my_studio_account_update(jsonb)', 'public.set_studio_link_name(text)',
    'public.admin_set_link_autoexpire(boolean,integer)', 'public.admin_set_link_expiry_shelf(text)',
    'public.admin_set_notification_pref(text,text,text,boolean,uuid)', 'public.admin_reset_notification_prefs()',
    'public.photo_render_settings_set(boolean,integer,integer)',
    'public.photo_render_begin(uuid,integer,text,text,text,numeric)'] loop
    v_old := to_regprocedure(f);
    if v_old is null then continue; end if;
    select p.proname, pg_get_function_arguments(p.oid), oidvectortypes(p.proargtypes), pg_get_function_result(p.oid), p.pronargs
      into v_name, v_args, v_idargs, v_ret, n from pg_proc p where p.oid = v_old;
    v_pre := to_regprocedure(format('public.%I(%s)', v_name || '__pre0173', v_idargs));
    v_new := false;
    if v_pre is null then
      -- first run: keep the original under __pre0173 (its grants move with it), then build the wrapper
      execute format('alter function public.%I(%s) rename to %I', v_name, v_idargs, v_name || '__pre0173');
      v_new := true;
    end if;
    select string_agg('$' || i, ', ' order by i) into v_call from generate_series(1, greatest(n, 1)) i where i <= n;
    execute format($w$create or replace function public.%I(%s) returns %s language plpgsql volatile security definer set search_path = '' as $b$
-- trial-lockdown-0173: free trial check, then the original
begin
  perform public._tl173_guard();
  return public.%I(%s);
end $b$
$w$, v_name, v_args, v_ret, v_name || '__pre0173', coalesce(v_call, ''));
    -- grants (only when the wrapper is new; a re-run keeps what is there): wrapper = the original's
    -- grants; the kept original = definer / service role only
    continue when not v_new;
    execute format('revoke all on function public.%I(%s) from public', v_name, v_idargs);
    if exists (select 1 from pg_roles where rolname = 'anon') then execute format('revoke all on function public.%I(%s) from anon', v_name, v_idargs); end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then execute format('revoke all on function public.%I(%s) from authenticated', v_name, v_idargs); end if;
    for g in select distinct r.rolname from pg_proc p, lateral aclexplode(p.proacl) a join pg_roles r on r.oid = a.grantee
              where p.oid = to_regprocedure(format('public.%I(%s)', v_name || '__pre0173', v_idargs)) and a.privilege_type = 'EXECUTE'
                and r.rolname in ('anon', 'authenticated', 'service_role') loop
      execute format('grant execute on function public.%I(%s) to %I', v_name, v_idargs, g.rolname);
    end loop;
    execute format('revoke all on function public.%I(%s) from public', v_name || '__pre0173', v_idargs);
    if exists (select 1 from pg_roles where rolname = 'anon') then execute format('revoke all on function public.%I(%s) from anon', v_name || '__pre0173', v_idargs); end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then execute format('revoke all on function public.%I(%s) from authenticated', v_name || '__pre0173', v_idargs); end if;
  end loop;
end $$;

-- ---- 5) what the app may show before the server refuses ----------------------------------------------
create or replace function public.my_trial_limits()
returns jsonb language plpgsql stable security definer set search_path = '' as $$
-- trial-lockdown-0173
declare v_org uuid := public.current_org_id(); v_used jsonb := '{}'::jsonb; t text; n integer;
begin
  if auth.uid() is null or v_org is null then raise exception 'not authorized' using errcode = '42501'; end if;
  if not public._tl173_trial_locked(v_org) then return jsonb_build_object('trial', false); end if;
  foreach t in array array['leads', 'quotes', 'inventory_items', 'vendors', 'crew_members', 'venues'] loop
    execute format('select count(*) from public.%I x where x.org_id = $1 and not x.is_demo', t) into n using v_org;
    v_used := v_used || jsonb_build_object(t, n);
  end loop;
  return jsonb_build_object('trial', true, 'cap', 2, 'used', v_used);
end $$;

-- ---- privileges --------------------------------------------------------------------------------------
do $$
declare f text;
begin
  foreach f in array array['public._tl173_trial_locked(uuid)', 'public._tl173_guard()', 'public._tl173_tg_create_cap()',
                           'public._tl173_tg_no_add()', 'public._tl173_tg_org_lock()', 'public.my_trial_limits()'] loop
    execute format('revoke all on function %s from public', f);
    if exists (select 1 from pg_roles where rolname = 'anon') then execute format('revoke all on function %s from anon', f); end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then execute format('revoke all on function %s from authenticated', f); end if;
  end loop;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    grant execute on function public.my_trial_limits() to authenticated;
    grant execute on function public._tl173_trial_locked(uuid) to authenticated;   -- the invoker org trigger asks it
  end if;
  if exists (select 1 from pg_roles where rolname = 'anon') then
    grant execute on function public._tl173_trial_locked(uuid) to anon;
  end if;
end $$;
commit;

-- VERIFY (every row should say ok = true)
select item, ok from (values
  ('01 cap trigger on 6 tables', (select count(*) from pg_trigger where tgname = 'zzzz_tl173_cap') = 6),
  ('02 no-add trigger on 4 catalog tables', (select count(*) from pg_trigger where tgname = 'zzzz_tl173_no_add') = 4),
  ('03 studio-settings trigger on organizations', exists (select 1 from pg_trigger where tgrelid = 'public.organizations'::regclass and tgname = 'zzzz_tl173_org_lock')),
  ('04 11 RPCs wrapped (original kept)', (select count(*) from pg_proc where pronamespace = 'public'::regnamespace and proname like '%\_\_pre0173') = 11),
  ('05 wrappers carry the trial check', (select count(*) from pg_proc p where p.pronamespace = 'public'::regnamespace and position('trial-lockdown-0173' in p.prosrc) > 0
       and to_regprocedure('public.' || p.proname || '__pre0173(' || oidvectortypes(p.proargtypes) || ')') is not null) = 11),
  ('06 kept originals not callable by the app', not exists (select 1 from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname like '%\_\_pre0173'
       and (has_function_privilege('anon', p.oid, 'execute') or has_function_privilege('authenticated', p.oid, 'execute')))),
  ('07 export_org_data still callable by signed-in users', has_function_privilege('authenticated', 'public.export_org_data()', 'execute')),
  ('08 my_trial_limits callable by signed-in users', has_function_privilege('authenticated', 'public.my_trial_limits()', 'execute')),
  ('09 trigger functions not callable by the app', not has_function_privilege('authenticated', 'public._tl173_tg_create_cap()', 'execute')
       and not has_function_privilege('authenticated', 'public._tl173_tg_no_add()', 'execute') and not has_function_privilege('authenticated', 'public._tl173_tg_org_lock()', 'execute')),
  ('11 trial studios affected: ' || (select count(*) from public.studio_subscriptions where status = 'trial')::text, true)
) v(item, ok) order by item;

-- ##########################################################################################
-- RELEASE SECTION 02/28: APPLY-0174.sql
-- In plain words: Every trial seed ("Load demo data", sign-up) uses the CURRENT published sample, never the old built-in demo.
-- ##########################################################################################
-- APPLY-0174.sql - paste into the Supabase SQL editor (STAGING first; production when the owner says go).
-- Run AFTER APPLY-0171 (and 0172). Free-trial seed fix: with helm_sample_template.active = true every
-- trial seed (signup, "Load demo data", "Reset demo data", AE studios) uses the CURRENT sample manifest;
-- a trial is never silently given the old built-in "Demo - Banjara Lawns / Sitara" seed; an old-seed
-- trial is not cloned on top of its old rows (use Clear sample data, then Load demo data).
-- Functions only: no table, column or row change, nothing deleted. Safe to run twice. ASCII only.
begin;
-- ============================================================================
-- 0174_trial_seed_current_manifest.sql - CANONICAL forward-only. Every trial seed uses the
-- CURRENT published sample manifest once the switch is on.
-- REQUIRES 0102 (_demo_seed_for) + 0166 + 0167 (sample master, manifest, _sample_clone_into).
--
-- In plain words (why prod trials still showed "Demo - Banjara Lawns / Sitara Convention Hall"):
--   1  _demo_seed (0167) fell back SILENTLY to the old built-in 0100 seed whenever the clone did
--      not run for any reason other than "already cloned" (e.g. 'no_template', 'template_empty').
--      With the switch ON a trial studio now never gets the old seed: it gets the manifest, or
--      nothing plus a clear reason ('sample_not_cloned') that is written to the audit log.
--   2  _demo_seed_for (0102: "Load demo data" / "Reset demo data") sent a studio whose country is
--      AE straight to the old Dubai seed, bypassing the manifest. A TRIAL studio now always goes
--      through _demo_seed (the manifest) while the switch is on. Paid studios: unchanged.
--   3  A trial seeded by the OLD seed (sample_cloned_at is null, old "Demo -" rows still there)
--      is never cloned on top of those rows (no mixed old + new data): the seed answers
--      'old_sample_present' and the studio uses "Clear sample data" first, then "Load demo data",
--      which clones the current manifest (old venues are switched off by the clear, never deleted).
--   4  With the switch OFF everything behaves exactly as before (0100 / 0102 seeds).
-- Zero data loss: functions only (CREATE OR REPLACE), no table / column / row change, nothing
-- deleted. Trial studios only. Idempotent.
-- ============================================================================
do $$ begin
  if to_regprocedure('public._sample_clone_into(uuid)') is null or to_regprocedure('public._demo_seed__pre0166(uuid)') is null
     or to_regprocedure('public._demo_seed_for(uuid)') is null or to_regprocedure('public._sample_template_ready()') is null then
    raise exception '0174: apply 0102 + 0166 + 0167 first'; end if;
end $$;

create or replace function public._demo_seed(p_org uuid)
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
-- trial-seed-0174 (trial-sample-0167 / trial-sandbox-0166): a trial studio gets its own copy of the
-- CURRENT published sample while the switch is on (never the old built-in seed); else the 0100 seed
declare r jsonb;
begin
  if p_org is not null and public._sample_template_ready()
     and public._is_trial_org(p_org)
     and exists (select 1 from public.organizations o where o.id = p_org and not coalesce(o.is_sample_master, false)) then
    -- a studio holding OLD built-in sample rows (never cloned) is not cloned on top of them
    if exists (select 1 from public.organizations o where o.id = p_org and o.sample_cloned_at is null)
       and (exists (select 1 from public.quotes x where x.org_id = p_org and x.is_demo)
            or exists (select 1 from public.leads x where x.org_id = p_org and x.is_demo)
            or exists (select 1 from public.inventory_items x where x.org_id = p_org and x.is_demo and x.active)) then
      return jsonb_build_object('cloned', false, 'seeded', false, 'reason', 'old_sample_present');
    end if;
    -- "Reset demo data": a cloned trial whose sample rows are all gone may clone again (current manifest)
    if exists (select 1 from public.organizations o where o.id = p_org and o.sample_cloned_at is not null)
       and not exists (select 1 from public.quotes x where x.org_id = p_org and x.is_demo)
       and not exists (select 1 from public.leads x where x.org_id = p_org and x.is_demo)
       and not exists (select 1 from public.inventory_items x where x.org_id = p_org and x.is_demo and x.active) then
      update public.organizations set sample_cloned_at = null where id = p_org;
    end if;
    r := public._sample_clone_into(p_org);
    if coalesce((r ->> 'cloned')::boolean, false) then
      update public.organizations set trial_mode = 'demo' where id = p_org and trial_mode is distinct from 'demo';
      return r;
    end if;
    if r ->> 'reason' = 'already_cloned' then return r || jsonb_build_object('seeded', false); end if;
    -- switch on but the clone did not run: say so; never the old seed
    insert into public.audit_log(actor, actor_email, action, entity, entity_id, changed, org_id, at)
      values (auth.uid(), null, 'trial.sample_not_cloned', 'organizations', p_org::text, coalesce(r, '{}'::jsonb), p_org, now());
    return coalesce(r, '{}'::jsonb) || jsonb_build_object('cloned', false, 'seeded', false, 'reason2', 'sample_not_cloned');
  end if;
  return public._demo_seed__pre0166(p_org);
end $$;

create or replace function public._demo_seed_for(p_org uuid)
returns jsonb language plpgsql security definer set search_path = '' as $$
-- trial-seed-0174 (demo-seed-0102): a TRIAL studio uses the sample manifest while it is on; AE -> Dubai seed otherwise
declare v_cc text;
begin
  if p_org is not null and public._sample_template_ready()
     and public._is_trial_org(p_org)
     and exists (select 1 from public.organizations o where o.id = p_org and not coalesce(o.is_sample_master, false)) then
    return public._demo_seed(p_org);
  end if;
  select upper(btrim(coalesce(o.country, ''))) into v_cc from public.organizations o where o.id = p_org;
  if v_cc = 'AE' then return public._demo_seed_ae(p_org); end if;
  return public._demo_seed(p_org);
end $$;

do $$
declare f text;
begin
  foreach f in array array['public._demo_seed(uuid)', 'public._demo_seed_for(uuid)'] loop
    execute format('revoke all on function %s from public', f);
    if exists (select 1 from pg_roles where rolname = 'anon') then execute format('revoke all on function %s from anon', f); end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then execute format('revoke all on function %s from authenticated', f); end if;
    if exists (select 1 from pg_roles where rolname = 'service_role') then execute format('grant execute on function %s to service_role', f); end if;
  end loop;
end $$;
commit;

-- VERIFY (every row should say ok = true)
select item, ok from (values
  ('01 _demo_seed is the 0174 version', position('trial-seed-0174' in (select prosrc from pg_proc where oid = 'public._demo_seed(uuid)'::regprocedure)) > 0),
  ('02 _demo_seed_for is the 0174 version', position('trial-seed-0174' in (select prosrc from pg_proc where oid = 'public._demo_seed_for(uuid)'::regprocedure)) > 0),
  ('03 app roles cannot call the seeders', not has_function_privilege('authenticated', 'public._demo_seed(uuid)', 'execute')
       and not has_function_privilege('authenticated', 'public._demo_seed_for(uuid)', 'execute')),
  ('05 trial check uses _is_trial_org, not trial_ends_at', position('_is_trial_org' in (select prosrc from pg_proc where oid = 'public._demo_seed(uuid)'::regprocedure)) > 0
       and position('trial_ends_at' in (select prosrc from pg_proc where oid = 'public._demo_seed(uuid)'::regprocedure)) = 0
       and position('_is_trial_org' in (select prosrc from pg_proc where oid = 'public._demo_seed_for(uuid)'::regprocedure)) > 0
       and position('trial_ends_at' in (select prosrc from pg_proc where oid = 'public._demo_seed_for(uuid)'::regprocedure)) = 0),
  ('04 switch on + manifest current (false = sample switch still off)', public._sample_template_ready())
) v(item, ok) order by item;

-- ##########################################################################################
-- RELEASE SECTION 03/28: APPLY-0175.sql
-- In plain words: Trial sample gets the owner's 3 layout templates (one theatre sample archived, never deleted).
-- ##########################################################################################
-- APPLY-0175.sql - paste into the Supabase SQL editor (STAGING first; production only when the owner says go).
-- Run AFTER APPLY-0171.sql. Trial studios: the owner's 3 layout templates (adds the sofa-lounge reception, archives the theatre sample; never deletes). Safe to run twice.
begin;
-- 0175_trial_layout_templates.sql - CANONICAL forward-only. REQUIRES 0096 + 0169 (+ 0171 for the manifest).
--
-- In plain words:
--   Free-trial studios should see exactly the owner's 3 layouts as templates:
