","width":6,"height":6,"category":"decor","rotation":0,"properties":{}}],"grid":{"snap":true,"show":true,"unit":"ft","sizeFt":1},"margins":{"left":0,"right":0,"top":0,"bottom":0},"venue":{"capacity":450},"scale":{"pxPerFt":12,"worldFt":{"w":200,"h":140}}}'::jsonb;
  o record;
begin
  for o in select x.id from public.organizations x
            where (x.id = M and x.is_sample_master) or (not coalesce(x.is_sample_master, false) and exists (select 1 from public.studio_subscriptions ss where ss.org_id = x.id and ss.status = 'trial'))
  loop
    update public.studio_layout_templates set archived = true, is_default = false, updated_at = now()
     where org_id = o.id and name = CTH and not archived;
    if not exists (select 1 from public.studio_layout_templates s where s.org_id = o.id and s.name = REC) then
      insert into public.studio_layout_templates(org_id, name, event_type, description, data)
      values (o.id, REC, 'reception', REC_DESC, REC_DATA);
    end if;
  end loop;
end $$;

do $$ begin
  if to_regprocedure('public.publish_sample_manifest(text)') is not null
     and exists (select 1 from public.organizations o where o.id = 'a5a5a5a5-0166-4000-8000-000000000001' and o.is_sample_master)
     and exists (select 1 from public.quotes x where x.org_id = 'a5a5a5a5-0166-4000-8000-000000000001'::uuid)
     and not exists (select 1 from public.helm_trial_seed_manifest m where m.notes = 'v6: owner 3 layout templates') then
    perform public.publish_sample_manifest('v6: owner 3 layout templates');
  end if;
end $$;
commit;

-- VERIFY (every row should say ok = true)
select item, ok from (values
  ('01 master has exactly the 3 owner templates live', (select count(*) from public.studio_layout_templates where org_id = 'a5a5a5a5-0166-4000-8000-000000000001' and not archived and name like E'Demo \u00b7 %') = 3),
  ('02 reception template present once', (select count(*) from public.studio_layout_templates where org_id = 'a5a5a5a5-0166-4000-8000-000000000001' and name = E'Demo \u00b7 Reception \u2014 Lawn reception with sofa lounge (450 guests)') = 1),
  ('03 theatre sample archived, not deleted', exists (select 1 from public.studio_layout_templates where org_id = 'a5a5a5a5-0166-4000-8000-000000000001' and name = E'Demo \u00b7 Corporate \u2014 Theatre/conference' and archived)),
  ('04 manifest v6 (or a later one, e.g. 0182) current', exists (select 1 from public.helm_trial_seed_manifest c where c.is_current
       and c.version >= (select m.version from public.helm_trial_seed_manifest m where m.notes = 'v6: owner 3 layout templates'))),
  ('05 no paid studio got the reception template', not exists (select 1 from public.studio_layout_templates s join public.organizations o on o.id = s.org_id
       where s.name = E'Demo \u00b7 Reception \u2014 Lawn reception with sofa lounge (450 guests)' and not o.is_sample_master and not exists (select 1 from public.studio_subscriptions ss where ss.org_id = o.id and ss.status = 'trial')))
) v(item, ok) order by item;

-- ##########################################################################################
-- RELEASE SECTION 04/28: APPLY-0176.sql
-- In plain words: Trial client portal: "Skip OTP" for the test client, and the trial event shows confirmed after it.
-- ##########################################################################################
-- APPLY-0176.sql - paste into the Supabase SQL editor (staging first, then production).
-- Additive + idempotent: trial-only Skip OTP on the client portal + trial event confirmed after it. Paid studios unchanged. Safe to run twice.
begin;
-- 0176_trial_client_flow.sql - CANONICAL forward-only. REQUIRES 0128 + 0146 (trial_test_approve,
-- _aud1017_is_member), 0166 (trial sandbox, outbound guard).
--
-- In plain words:
--   TRIAL CLIENT FLOW. In a free-trial studio no SMS / WhatsApp / email is ever sent (0166 outbound
--   guard), so a client opening the approval portal could never receive the OTP and the event was
--   stuck. 0146 had limited "Skip OTP" to a signed-in member of the studio, so the portal (opened
--   by the client, not signed in) never showed it.
--     1) _trial_client_skip_ok(org): ACTIVE trial (same _trial_test_mode_ok: trial running, no active
--        subscription, not locked) AND (caller is a member of that studio OR caller is not signed in,
--        i.e. the client on the portal). A signed-in member of another studio is refused.
--     2) trial_test_mode_for_token uses it (the portal shows "Test mode - confirm").
--     3) trial_test_approve uses it, and after the approval moves the event to status 'confirmed'
--        (trial only) so the event group, booklet link and adding members work right away.
--   Paid / converted / ended trials: unchanged - request_otp / verify_and_consent still require the
--   real OTP, and trial_test_approve still refuses ('trial_test_unavailable').
--   Changes: 1 new function, 2 functions replaced (same signatures + grants). No table, column or
--   trigger is changed; the only row write is the trial event's own status after the client
--   approves. Additive + idempotent: safe to run twice. ASCII only.

do $$ begin
  if to_regprocedure('public._trial_test_mode_ok(uuid)') is null or to_regprocedure('public._aud1017_is_member(uuid)') is null then
    raise exception '0176: apply 0128 + 0146 first'; end if;
end $$;

create or replace function public._trial_client_skip_ok(p_org uuid)
returns boolean language sql stable security definer set search_path = '' as $$
  -- helm-0176-trial-client
  select public._trial_test_mode_ok(p_org)
     and (public._aud1017_is_member(p_org) or auth.uid() is null);
$$;
revoke all on function public._trial_client_skip_ok(uuid) from public, anon, authenticated;
grant execute on function public._trial_client_skip_ok(uuid) to service_role;

create or replace function public.trial_test_mode_for_token(p_token uuid)
returns boolean language sql stable security definer set search_path = '' as $$
  -- helm-0128-trial-test (0176: studio member or the client on the portal, active trial only)
  select coalesce((select public._trial_client_skip_ok(q.org_id) from public.quotes q
                    where p_token is not null and q.approval_token = p_token
                      and (q.approval_token_expires_at is null or q.approval_token_expires_at > now())
                    limit 1), false);
$$;
revoke all on function public.trial_test_mode_for_token(uuid) from public;
grant execute on function public.trial_test_mode_for_token(uuid) to anon, authenticated, service_role;

create or replace function public.trial_test_approve(p_token uuid, p_phone text, p_client_name text,
                                                     p_terms_version text, p_consent_text text,
                                                     p_user_agent text)
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
-- helm-0128-trial-test (0176: client portal allowed in trial; event confirmed after the skip)
declare v_q uuid; v_org uuid; v_file text; v_phone text; v_code text; r bigint; v_out jsonb;
begin
  select q.id, q.org_id, coalesce(q.client ->> 'phone', '') into v_q, v_org, v_file
    from public.quotes q
   where p_token is not null and q.approval_token = p_token
     and (q.approval_token_expires_at is null or q.approval_token_expires_at > now());
  if v_q is null then raise exception 'invalid link' using errcode = 'P0001'; end if;
  -- 0146 aud1017: the skip is for the studio owner testing alone - a client (or anyone else
  -- holding the link) must go through the real OTP.
  -- 0176: the studio's own member (testing alone) OR the client on the portal (not signed in).
  -- A signed-in member of ANOTHER studio is still refused. Paid / ended / locked: always refused.
  if not public._trial_client_skip_ok(v_org) then
    return jsonb_build_object('approved', false, 'error', 'trial_test_unavailable',
      'message', 'Skipping the OTP is only available in an active free-trial studio.');
  end if;
  if public.link_age_expired(public.approval_link_age_until(p_token)) or public._a42_quote_shelved(v_q) then
    raise exception 'this link has expired' using errcode = 'P0001';
  end if;
  v_phone := nullif(btrim(coalesce(p_phone, '')), '');
  if v_phone is null or length(regexp_replace(v_phone, '[^0-9]', '', 'g')) < 8 then v_phone := nullif(v_file, ''); end if;
  if v_phone is null or length(regexp_replace(v_phone, '[^0-9]', '', 'g')) < 8 then
    return jsonb_build_object('approved', false, 'error', 'phone_required',
      'message', 'Enter a mobile number (any test number works in trial test mode).');
  end if;
  v_phone := public._otp_canon_phone(p_token, v_phone);
  -- one-time random code, hashed like request_otp; never returned, never sent
  loop
    r := ('x' || encode(extensions.gen_random_bytes(4), 'hex'))::bit(32)::bigint;
    exit when r < 4294000000;
  end loop;
  v_code := lpad((r % 1000000)::text, 6, '0');
  insert into public.quote_otps(quote_id, phone, code_hash, expires_at)
    values (v_q, v_phone, extensions.crypt(v_code, extensions.gen_salt('bf', 8)), now() + interval '10 minutes');
  v_out := public.verify_and_consent(p_token, v_phone, v_code, true, p_terms_version,
                                     p_consent_text, p_client_name, p_user_agent);
  if coalesce((v_out ->> 'approved')::boolean, false) then
    update public.quote_consents c set verified_via_otp = false
     where c.id = (select c2.id from public.quote_consents c2 where c2.quote_id = v_q
                    order by c2.created_at desc, c2.id desc limit 1)
       and c.verified_via_otp;
    insert into public.audit_log(actor, actor_email, action, entity, entity_id, changed, org_id, at)
      values (auth.uid(), null, 'approval.trial_test_skip', 'quotes', v_q::text,
              jsonb_build_object('trial_test', true, 'otp', 'skipped', 'client_name', p_client_name),
              v_org, now());
    -- 0176: trial only - the approved event moves on to Confirmed so the next steps work
    -- (event group, booklet link, members). Never for a paid studio (gate above).
    update public.quotes qq set status = 'confirmed', confirmed_at = coalesce(qq.confirmed_at, now())
     where qq.id = v_q and qq.status is distinct from 'confirmed' and qq.status is distinct from 'cancelled'
       and qq.deleted_at is null and qq.approval_status = 'approved';
    v_out := v_out || jsonb_build_object('trial_test', true, 'confirmed', true);
  end if;
  return v_out;
end $$;
revoke all on function public.trial_test_approve(uuid, text, text, text, text, text) from public;
grant execute on function public.trial_test_approve(uuid, text, text, text, text, text) to anon, authenticated, service_role;
commit;

-- VERIFY (every row should say ok = true)
select item, ok from (values
  ('01 _trial_client_skip_ok exists, not callable by app', to_regprocedure('public._trial_client_skip_ok(uuid)') is not null
      and not has_function_privilege('anon', 'public._trial_client_skip_ok(uuid)', 'execute')
      and not has_function_privilege('authenticated', 'public._trial_client_skip_ok(uuid)', 'execute')),
  ('02 trial_test_mode_for_token uses 0176 gate', position('_trial_client_skip_ok' in pg_get_functiondef('public.trial_test_mode_for_token(uuid)'::regprocedure)) > 0),
  ('03 trial_test_approve uses 0176 gate + confirms', position('_trial_client_skip_ok' in pg_get_functiondef('public.trial_test_approve(uuid,text,text,text,text,text)'::regprocedure)) > 0
      and position('''confirmed'', true' in pg_get_functiondef('public.trial_test_approve(uuid,text,text,text,text,text)'::regprocedure)) > 0),
  ('04 gate still requires an active trial', position('_trial_test_mode_ok' in pg_get_functiondef('public._trial_client_skip_ok(uuid)'::regprocedure)) > 0),
  ('05 portal can call both RPCs', has_function_privilege('anon', 'public.trial_test_approve(uuid,text,text,text,text,text)', 'execute')
      and has_function_privilege('anon', 'public.trial_test_mode_for_token(uuid)', 'execute')),
  ('06 no paid studio has Skip OTP', not exists (select 1 from public.studio_subscriptions s where s.status = 'active' and public._trial_test_mode_ok(s.org_id)))
) v(item, ok) order by item;

-- ##########################################################################################
-- RELEASE SECTION 05/28: APPLY-0177.sql
-- In plain words: Free trial is India only: new trials land on INR / Asia/Kolkata / GST and stay there.
-- ##########################################################################################
-- APPLY-0177.sql - paste into the Supabase SQL editor (staging first, then production).
-- Free trial is India only: new trials land on INR / Asia/Kolkata / IN / GST and stay there while on trial.
-- Additive + idempotent: one nullable column, one check constraint (not valid), one trigger function + trigger.
-- No existing row is changed here (existing trial studios: run FIX-0177-existing-trials.sql). Safe to run twice.
begin;
-- 0177_trial_india_defaults.sql - CANONICAL forward-only.
-- REQUIRES 0089 (organizations.country / tax_region), 0097 (organizations.trial_mode),
--          0119 (start_self_serve_trial), 0159 (my_pending_start_trial), 0058 (studio_subscriptions),
--          0166 (organizations.is_sample_master).
--
-- In plain words:
--   The free trial is for India only: every free-trial studio is INR, Asia/Kolkata, country IN,
--   GST (tax region = the Indian state; Telangana when none is set, the trial city is Hyderabad).
--   Until now start_self_serve_trial() used the visitor's browser time zone (and a currency
--   guessed from it), so a visitor in the US got USD + America/Chicago.
--   * New nullable column organizations.trial_region. It is stamped 'IN' at the one moment a
--     free trial starts (trial_ends_at goes from empty to set together with trial_mode, which
--     only start_self_serve_trial / my_pending_start_trial do). Checkout trials of paid
--     "Create studio" studios (my_start_trial: trial_mode stays empty) are never stamped.
--   * A trigger keeps a stamped studio on INR / Asia/Kolkata / IN while it is still ON its free
--     trial (subscription status 'trial'). After the studio pays, it can change them freely.
--   * Only NEW trials are affected by this file: no existing row is updated here. Existing trial
--     studios are corrected by the separate, owner-run supabase/FIX-0177-existing-trials.sql.
--   Additive + idempotent: add column if not exists, create or replace, drop trigger if exists.
--   No DROP of data, DELETE or TRUNCATE. Safe to run twice.
-- ============================================================================

do $$ begin
  if not exists (select 1 from information_schema.columns where table_schema = 'public'
                 and table_name = 'organizations' and column_name = 'trial_mode') then
    raise exception '0177: organizations.trial_mode (0097) is missing'; end if;
  if not exists (select 1 from information_schema.columns where table_schema = 'public'
                 and table_name = 'organizations' and column_name = 'tax_region') then
    raise exception '0177: organizations.tax_region (0089) is missing'; end if;
  if not exists (select 1 from information_schema.columns where table_schema = 'public'
                 and table_name = 'organizations' and column_name = 'is_sample_master') then
    raise exception '0177: organizations.is_sample_master (0166) is missing'; end if;
  if to_regclass('public.studio_subscriptions') is null then
    raise exception '0177: studio_subscriptions is missing'; end if;
end $$;

alter table public.organizations add column if not exists trial_region text;
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'organizations_trial_region_0177_chk') then
    alter table public.organizations add constraint organizations_trial_region_0177_chk
      check (trial_region is null or trial_region = 'IN') not valid;
  end if;
end $$;

create or replace function public.tg_org_trial_india()
returns trigger language plpgsql security definer set search_path = '' as $$
-- trial-india-0177: a free-trial studio is INR / Asia/Kolkata / IN / GST while on its trial
declare v_status text;
begin
  if coalesce(new.is_sample_master, false) then return new; end if;
  -- the moment a free trial starts: stamp it (checkout trials never set trial_mode here)
  if old.trial_ends_at is null and new.trial_ends_at is not null and new.trial_mode is not null then
    new.trial_region := 'IN';
  end if;
  if new.trial_region is distinct from 'IN' or new.trial_ends_at is null then return new; end if;
  select s.status into v_status from public.studio_subscriptions s where s.org_id = new.id;
  if v_status is not null and v_status <> 'trial' then return new; end if;   -- paid / converted: free to change
  new.currency := 'INR';
  new.timezone := 'Asia/Kolkata';
  new.country := 'IN';
  if nullif(btrim(coalesce(new.tax_region, '')), '') is null then new.tax_region := 'Telangana'; end if;
  return new;
end $$;
revoke all on function public.tg_org_trial_india() from public, anon, authenticated;

drop trigger if exists zzz_org_trial_india_0177 on public.organizations;
create trigger zzz_org_trial_india_0177 before update on public.organizations
  for each row execute function public.tg_org_trial_india();

notify pgrst, 'reload schema';
commit;

-- VERIFY (every row should say ok = true)
select item, ok from (values
  ('01 column organizations.trial_region', exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'organizations' and column_name = 'trial_region')),
  ('02 check constraint present', exists (select 1 from pg_constraint where conname = 'organizations_trial_region_0177_chk')),
  ('03 trigger function is SECURITY DEFINER', coalesce((select prosecdef from pg_proc where oid = to_regprocedure('public.tg_org_trial_india()')), false)),
  ('04 trigger on organizations', exists (select 1 from pg_trigger where tgrelid = 'public.organizations'::regclass and tgname = 'zzz_org_trial_india_0177' and not tgisinternal)),
  ('05 app roles cannot call the trigger function', not has_function_privilege('authenticated', 'public.tg_org_trial_india()', 'execute') and not has_function_privilege('anon', 'public.tg_org_trial_india()', 'execute')),
  ('06 sample master not stamped', not exists (select 1 from public.organizations where is_sample_master and trial_region is not null))
) v(item, ok) order by item;

-- ##########################################################################################
-- RELEASE SECTION 06/28: APPLY-0179.sql
-- In plain words: No real client message from a free-trial studio (approval code, WhatsApp, e-mail); seat limit admin + 2.
-- ##########################################################################################
-- APPLY-0179.sql - paste into the Supabase SQL editor (staging first, then production).
-- No real client message from a free-trial studio: approval code (SMS / WhatsApp / e-mail), staff
-- "Send on WhatsApp" and proposal WhatsApp are refused while studio_subscriptions.status = 'trial'
-- (hint trial_no_send); trial_send_blocked() for the edge functions; outbox retry back to 'pending'
-- is skipped again; seat limit (admin + 2, open invitations included) also on a client -> staff role change.
-- Paid studios unchanged. Additive + idempotent (renames once, create or replace, triggers if missing,
-- one bookkeeping table). No studio row changed. Safe to run twice.
begin;
-- 0179_trial_no_client_messages.sql - CANONICAL forward-only. REQUIRES 0093 (request_otp),
-- 0097 (otp_send_authorize), 0151 (wa_otp_begin / _wa151_token_quote), 0155 (whatsapp_authorize,
-- wa_proposal_prepare), 0166 (_is_trial_org, _sample_outbound_blocked, seat + outbox triggers).
--
-- In plain words:
--   NO REAL CLIENT MESSAGES FROM A FREE-TRIAL STUDIO. 0166 only skipped queued outbox rows; the
--   direct routes (approval OTP by SMS / WhatsApp / e-mail, staff "Send on WhatsApp", proposal
--   WhatsApp) still sent. Now:
--     1) _tb179_no_send(org): true while the studio is in its free trial
--        (studio_subscriptions.status = 'trial', via _is_trial_org) or is the sample master,
--        or (trial bundle) its free trial ENDED unpaid and it is read-only (_trial_locked: 0116,
--        status-based from 0183) - an ended trial does not start sending to clients either.
--        Paid studios: always false - nothing changes for them.
--     2) otp_send_authorize, request_otp, wa_otp_begin, whatsapp_authorize, wa_proposal_prepare
--        are wrapped (old body kept as <name>__pre0179): a trial studio gets
--        42501 / hint 'trial_no_send'. The 0155 "10 a day to opted-in clients" trial exception is
--        therefore gone (trial = 0 real sends). wa_proposal_prepare still answers a SIMULATED
--        prepare (p_simulate = true: nothing is sent, the share screen shows "Simulated").
--     3) trial_send_blocked(org, quote, token): service-role-only check the edge functions
--        (send-otp, client-mailer, send-whatsapp, wa-proposal) call before sending.
--     4) Outbox guard also on UPDATE: a retry that puts a row back to 'pending' is skipped too.
--     5) Seat limit (admin + 2) also counts a role change client -> staff role (admin_set_role,
--        staff_set_login_role) and a pending invitation whose role changes from client; joining
--        or promoting now also counts the studio's other open staff invitations.
--   Changes: 2 new functions, 5 wrapped, 2 trigger functions replaced, 2 + 3 triggers added, one
--   small bookkeeping table (tb179_grants: which app roles could call each wrapped function, so a
--   re-run gives the wrapper exactly the old callers). No existing table or column changed, no
--   studio row written. Additive + idempotent: safe to run twice. ASCII only.

do $$ begin
  if to_regprocedure('public._is_trial_org(uuid)') is null or to_regprocedure('public._sample_outbound_blocked(uuid,text)') is null
     or to_regprocedure('public._trial_locked(uuid)') is null then
    raise exception '0179: apply 0116 + 0166 first'; end if;
  if to_regprocedure('public._wa151_token_quote(uuid)') is null or to_regprocedure('public.wa_otp_begin(uuid,text,text)') is null then
    raise exception '0179: apply 0151 first'; end if;
  if to_regprocedure('public.whatsapp_authorize__pre0155(uuid,text)') is null then raise exception '0179: apply 0155 first'; end if;
end $$;

-- ---- 1) helpers --------------------------------------------------------------------------------
create or replace function public._tb179_no_send(p_org uuid)
returns boolean language sql stable security definer set search_path = '' as $$
  -- tb-msg-0179: free trial (subscription status), an ended unpaid (read-only) trial, or the sample
  -- master never sends to clients
  select p_org is not null
     and (public._is_trial_org(p_org)
          or exists (select 1 from public.organizations o where o.id = p_org and o.is_sample_master)
          or coalesce(public._trial_locked(p_org), false));
$$;
revoke all on function public._tb179_no_send(uuid) from public;
do $$ begin
  if exists (select 1 from pg_roles where rolname = 'anon') then revoke all on function public._tb179_no_send(uuid) from anon; end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then revoke all on function public._tb179_no_send(uuid) from authenticated; end if;
  if exists (select 1 from pg_roles where rolname = 'service_role') then grant execute on function public._tb179_no_send(uuid) to service_role; end if;
end $$;

create or replace function public.trial_send_blocked(p_org uuid default null, p_quote uuid default null, p_token uuid default null)
returns boolean language sql stable security definer set search_path = '' as $$
  -- tb-msg-0179: edge functions (service role) ask before any real send
  select coalesce(public._tb179_no_send(p_org), false)
      or coalesce((select public._tb179_no_send(q.org_id) from public.quotes q where p_quote is not null and q.id = p_quote), false)
      or coalesce((select bool_or(public._tb179_no_send(q.org_id)) from public.quotes q where p_token is not null and q.approval_token = p_token), false)
      or coalesce((select bool_or(public._tb179_no_send(b.org_id)) from public.client_booklets b where p_token is not null and b.token = p_token), false);
$$;
revoke all on function public.trial_send_blocked(uuid, uuid, uuid) from public;
do $$ begin
  if exists (select 1 from pg_roles where rolname = 'anon') then revoke all on function public.trial_send_blocked(uuid, uuid, uuid) from anon; end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then revoke all on function public.trial_send_blocked(uuid, uuid, uuid) from authenticated; end if;
  if exists (select 1 from pg_roles where rolname = 'service_role') then grant execute on function public.trial_send_blocked(uuid, uuid, uuid) to service_role; end if;
end $$;

-- ---- 2) keep each current body as <name>__pre0179 (once); remember who could call it ------------
create table if not exists public.tb179_grants (fn text not null, rolname text not null, primary key (fn, rolname));
alter table public.tb179_grants enable row level security;
revoke all on public.tb179_grants from public;
do $$ begin
  if exists (select 1 from pg_roles where rolname = 'anon') then revoke all on public.tb179_grants from anon; end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then revoke all on public.tb179_grants from authenticated; end if;
end $$;

do $$ declare f text[]; v_old text; v_new text; rl text; begin
  foreach f slice 1 in array array[
    array['otp_send_authorize', 'uuid, text'],
    array['request_otp', 'uuid, text'],
    array['wa_otp_begin', 'uuid, text, text'],
    array['whatsapp_authorize', 'uuid, text'],
    array['wa_proposal_prepare', 'uuid, text, text, boolean, text, boolean']] loop
    v_old := format('public.%s(%s)', f[1], f[2]);
    v_new := format('public.%s(%s)', f[1] || '__pre0179', f[2]);
    if to_regprocedure(v_new) is null and to_regprocedure(v_old) is not null
       and position('tb-msg-0179' in pg_get_functiondef(to_regprocedure(v_old))) = 0 then
      foreach rl in array array['anon', 'authenticated', 'service_role'] loop
        if exists (select 1 from pg_roles where rolname = rl) and has_function_privilege(rl, v_old, 'execute') then
          insert into public.tb179_grants(fn, rolname) values (f[1], rl) on conflict do nothing;
        end if;
      end loop;
      execute format('alter function public.%I(%s) rename to %I', f[1], f[2], f[1] || '__pre0179');
    end if;
  end loop;
end $$;

-- ---- 3) wrappers -------------------------------------------------------------------------------
create or replace function public.otp_send_authorize(p_token uuid, p_phone text)
returns jsonb language plpgsql security definer set search_path = '' as $$
-- tb-msg-0179: no approval code is sent from a free-trial studio
begin
  if exists (select 1 from public.quotes q where p_token is not null and q.approval_token = p_token and public._tb179_no_send(q.org_id)) then
    raise exception 'Free trial: messages to clients are not sent' using errcode = '42501', hint = 'trial_no_send';
  end if;
  return public.otp_send_authorize__pre0179(p_token, p_phone);
end $$;

create or replace function public.request_otp(p_token uuid, p_phone text)
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
-- tb-msg-0179: no approval code from a free-trial studio (the portal uses Test mode - confirm, 0176)
begin
  if exists (select 1 from public.quotes q where p_token is not null and q.approval_token = p_token and public._tb179_no_send(q.org_id)) then
    raise exception 'Free trial: messages to clients are not sent' using errcode = '42501', hint = 'trial_no_send';
  end if;
  return public.request_otp__pre0179(p_token, p_phone);
end $$;

create or replace function public.wa_otp_begin(p_token uuid, p_channel text, p_user_agent text default null)
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
-- tb-msg-0179: no WhatsApp / e-mail approval code from a free-trial studio
begin
  if exists (select 1 from public.quotes q where p_token is not null and q.approval_token = p_token and public._tb179_no_send(q.org_id)) then
    raise exception 'Free trial: messages to clients are not sent' using errcode = '42501', hint = 'trial_no_send';
  end if;
  return public.wa_otp_begin__pre0179(p_token, p_channel, p_user_agent);
end $$;

create or replace function public.whatsapp_authorize(p_quote uuid, p_recipient text)
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
-- tb-msg-0179: a free-trial studio sends 0 real WhatsApp messages (replaces the 0155 opt-in exception)
begin
  if exists (select 1 from public.quotes q where p_quote is not null and q.id = p_quote and public._tb179_no_send(q.org_id)) then
    raise exception 'Free trial: messages to clients are not sent' using errcode = '42501', hint = 'trial_no_send';
  end if;
  return public.whatsapp_authorize__pre0179(p_quote, p_recipient);
end $$;

create or replace function public.wa_proposal_prepare(p_quote uuid, p_kind text, p_phone text,
                                                      p_opt_in boolean, p_consent_text text, p_simulate boolean)
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
-- tb-msg-0179: no real proposal WhatsApp from a free-trial studio (a simulated prepare sends nothing)
begin
  if coalesce(p_simulate, false) is not true
     and exists (select 1 from public.quotes q where p_quote is not null and q.id = p_quote and public._tb179_no_send(q.org_id)) then
    raise exception 'Free trial: messages to clients are not sent' using errcode = '42501', hint = 'trial_no_send';
  end if;
  return public.wa_proposal_prepare__pre0179(p_quote, p_kind, p_phone, p_opt_in, p_consent_text, p_simulate);
end $$;

-- grants: wrapper = what the old body had; the kept body is service-role only
do $$ declare f text[]; v_old text; v_new text; rl text; begin
  foreach f slice 1 in array array[
    array['otp_send_authorize', 'uuid, text'],
    array['request_otp', 'uuid, text'],
    array['wa_otp_begin', 'uuid, text, text'],
    array['whatsapp_authorize', 'uuid, text'],
    array['wa_proposal_prepare', 'uuid, text, text, boolean, text, boolean']] loop
    v_old := format('public.%s(%s)', f[1], f[2]);
    v_new := format('public.%s(%s)', f[1] || '__pre0179', f[2]);
    execute format('revoke all on function %s from public', v_old);
    -- Supabase default privileges hand a NEW function to anon / authenticated: take that back first
    if exists (select 1 from pg_roles where rolname = 'anon') then execute format('revoke all on function %s from anon', v_old); end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then execute format('revoke all on function %s from authenticated', v_old); end if;
    for rl in select g.rolname from public.tb179_grants g where g.fn = f[1] loop
      if exists (select 1 from pg_roles where rolname = rl) then execute format('grant execute on function %s to %I', v_old, rl); end if;
    end loop;
    if to_regprocedure(v_new) is not null then
      execute format('revoke all on function %s from public', v_new);
      if exists (select 1 from pg_roles where rolname = 'anon') then execute format('revoke all on function %s from anon', v_new); end if;
      if exists (select 1 from pg_roles where rolname = 'authenticated') then execute format('revoke all on function %s from authenticated', v_new); end if;
      if exists (select 1 from pg_roles where rolname = 'service_role') then execute format('grant execute on function %s to service_role', v_new); end if;
    end if;
  end loop;
end $$;

-- ---- 4) outbox guard on UPDATE too (retry back to pending) --------------------------------------
do $$ declare t text; begin
  foreach t in array array['comms_outbox', 'pkg_outbox', 'assign_notify_outbox'] loop
    if to_regclass('public.' || t) is not null
       and not exists (select 1 from pg_trigger where tgrelid = format('public.%I', t)::regclass and tgname = 'zzzz_tb179_outbox_skip_upd') then
      execute format('create trigger zzzz_tb179_outbox_skip_upd before update of status on public.%I for each row '
                     'when (new.status = ''pending'' and old.status is distinct from ''pending'') '
                     'execute function public._ts166_tg_outbox_skip()', t);
    end if;
  end loop;
end $$;

-- ---- 5) seat limit also on role changes -----------------------------------------------------------
create or replace function public._ts166_tg_profile_seat()
returns trigger language plpgsql security definer set search_path = '' as $$
-- trial-sandbox-0166: joining a studio (any path) may not pass the seat limit
-- tb-msg-0179: a role change client -> staff role inside the studio counts as a new seat, and the
-- studio's other open staff invitations count too (admin + 2 = members + pending invitations)
declare v_lim integer; v_used integer;
begin
  if new.org_id is null or coalesce(new.role, '') = 'client' then return new; end if;
  if tg_op = 'UPDATE' and old.org_id is not distinct from new.org_id and coalesce(old.role, '') <> 'client' then return new; end if;
  v_lim := public._trial_seat_limit(new.org_id);
  if v_lim is null then return new; end if;
  perform pg_advisory_xact_lock(hashtextextended('helm:seat:' || new.org_id::text, 0));
  -- members + the studio's other open staff invitations (not this person's own invitation)
  select (select count(*) from public.profiles p
           where p.org_id = new.org_id and p.id <> new.id and coalesce(p.role, '') <> 'client')
       + (select count(*) from public.invitations i
           where i.org_id = new.org_id and i.status = 'pending' and coalesce(i.role, '') <> 'client'
             and (i.expires_at is null or i.expires_at > now())
             and lower(i.email) is distinct from lower(coalesce(new.email, ''))
             and not exists (select 1 from public.profiles p
                              where p.org_id = new.org_id and p.id <> new.id and lower(p.email) = lower(i.email)))
    into v_used;
  if v_used >= v_lim then
    raise exception 'Your free trial includes % people (you + % more). Upgrade to add more.', v_lim, v_lim - 1
      using errcode = '42501', hint = 'seat_limit';
  end if;
  return new;
end $$;

create or replace function public._ts166_tg_invite_seat()
returns trigger language plpgsql security definer set search_path = '' as $$
-- trial-sandbox-0166: members + open invitations may not pass the seat limit
-- tb-msg-0179: a pending invitation whose role changes from client counts as a new seat
declare v_lim integer; v_used integer;
begin
  if new.org_id is null or coalesce(new.status, 'pending') <> 'pending' or coalesce(new.role, '') = 'client' then return new; end if;
  if tg_op = 'UPDATE' and old.status = 'pending' and old.org_id is not distinct from new.org_id
     and coalesce(old.role, '') <> 'client' then return new; end if;
  v_lim := public._trial_seat_limit(new.org_id);
  if v_lim is null then return new; end if;
  perform pg_advisory_xact_lock(hashtextextended('helm:seat:' || new.org_id::text, 0));
  select (select count(*) from public.profiles p where p.org_id = new.org_id and coalesce(p.role, '') <> 'client')
       + (select count(*) from public.invitations i
           where i.org_id = new.org_id and i.status = 'pending' and i.id is distinct from new.id
             and coalesce(i.role, '') <> 'client' and (i.expires_at is null or i.expires_at > now())
             and not exists (select 1 from public.profiles p where p.org_id = new.org_id and lower(p.email) = lower(i.email)))
    into v_used;
  if v_used >= v_lim then
    raise exception 'Your free trial includes % people (you + % more). Remove an invitation or upgrade to add more.', v_lim, v_lim - 1
      using errcode = '42501', hint = 'seat_limit';
  end if;
  return new;
end $$;

do $$ begin
  if not exists (select 1 from pg_trigger where tgrelid = 'public.profiles'::regclass and tgname = 'zzzz_tb179_seat_role') then
    create trigger zzzz_tb179_seat_role before update of role on public.profiles
      for each row when (old.org_id is not distinct from new.org_id and coalesce(old.role, '') = 'client' and coalesce(new.role, '') <> 'client')
      execute function public._ts166_tg_profile_seat();
  end if;
  if not exists (select 1 from pg_trigger where tgrelid = 'public.invitations'::regclass and tgname = 'zzzz_tb179_seat_role') then
    create trigger zzzz_tb179_seat_role before update of role on public.invitations
      for each row when (old.org_id is not distinct from new.org_id and old.status is not distinct from new.status
                         and coalesce(old.role, '') = 'client' and coalesce(new.role, '') <> 'client')
      execute function public._ts166_tg_invite_seat();
  end if;
end $$;

-- trigger functions stay internal (create or replace keeps the 0166 grants; said again for a fresh paste)
do $$ declare f text; begin
  foreach f in array array['public._ts166_tg_profile_seat()', 'public._ts166_tg_invite_seat()'] loop
    execute format('revoke all on function %s from public', f);
    if exists (select 1 from pg_roles where rolname = 'anon') then execute format('revoke all on function %s from anon', f); end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then execute format('revoke all on function %s from authenticated', f); end if;
  end loop;
end $$;

notify pgrst, 'reload schema';
commit;

