    'payment_reconciliation', 'vendor_payouts', 'vendor_bills', 'expense_claims', 'event_costs', 'event_closure',
    'event_close_overrides', 'lifecycle_stage_overrides',
    'quotes',
    'quote_versions', 'quotation_versions', 'quote_otps', 'change_requests', 'client_booklet_images', 'client_booklets',
    'client_link_opens', 'design_stages', 'event_attendees', 'event_checklist', 'event_day', 'event_discovery',
    'event_files', 'event_guests', 'event_issues', 'event_media', 'event_menu_items', 'event_plan', 'event_proposal',
    'event_ratings', 'event_reminders', 'event_requirements', 'event_resources', 'event_resource_needs', 'event_sites',
    'event_stock_requests', 'task_evidence_grants', 'task_evidence', 'event_tasks', 'run_sheet_items', 'proposal_risks',
    'work_tokens', 'inventory_reservations', 'inventory_checkouts', 'inv_shortage_alerts', 'photo_renders',
    'photo_render_usage', 'pkg_otps', 'pkg_outbox', 'comms_outbox', 'assign_notify_outbox',
    'chat_reactions', 'chat_messages', 'chat_members', 'chat_conversations',
    'leads', 'lead_archive', 'nurture', 'nurture_automation', 'nurture_templates', 'layouts', 'studio_layout_templates',
    'layout_rules', 'menu_templates', 'dish_catalog', 'inventory_items', 'item_rate_cards', 'vendors', 'crew_members',
    'venues', 'coupons', 'chair_types', 'plate_types', 'checklist_templates', 'task_templates', 'custom_field_defs',
    'import_mappings', 'invitations', 'saved_views', 'user_recent_records', 'a155_wa_recipients', 'notifications'
  ]::text[];
$$;

-- tables with an org_id that the purge never empties: the account, billing, consent, security,
-- settings, opt-out and platform records (and this feature's own ledgers)
create or replace function public._tr184_keep_tables()
returns text[] language sql immutable set search_path = '' as $$
  -- trial-retention-0184
  select array[
    'profiles', 'studio_subscriptions', 'subscription_payments', 'billing_reminders', 'studio_account',
    'studio_consent_log', 'studio_payment_gate', 'audit_log', 'security_alert_events', 'security_alert_outbox',
    'invite_email_outbox', 'welcome_email_outbox', 'trial_reminders', 'trial_sample_runs', 'helm_sample_template',
    'helm_audit_0044_reverted', 'whatsapp_opt_outs', 'member_wa_optin', 'wa_proposal_optins', 'wa_proposal_audit',
    'integration_webhook_events', 'upload_scans', 'a155_admin_created', 'messaging_rate', 'app_config', 'role_access',
    'comms_settings', 'pkg_settings', 'photo_render_settings', 'privacy_pin', 'privacy_pin_attempts',
    'org_link_autoexpire', 'org_link_expiry_shelf', 'org_payment_accounts', 'org_whatsapp_accounts', 'org_slug_history',
    'notification_prefs', 'notification_mutes', 'notification_seen', 'user_dashboard_prefs',
    'trial_retention_schedule', 'trial_retention_notices', 'trial_retention_runs',
    -- trial bundle: ledgers of the sibling trial migrations (ids / fingerprints only, never purged):
    -- 0181 creation log, 0185 clean-start journal, 0186 one-trial grants + one-extension record
    'trial_create_log', 'studio_clean_start_items', 'trial_grants', 'trial_extensions'
  ]::text[];
$$;

-- every public base table that has an org_id column (read at run time)
create or replace function public._tr184_org_tables()
returns text[] language sql stable security definer set search_path = '' as $$
  -- trial-retention-0184
  select coalesce(array_agg(c.table_name::text order by c.table_name), '{}'::text[])
    from information_schema.columns c
    join information_schema.tables t on t.table_schema = c.table_schema and t.table_name = c.table_name
   where c.table_schema = 'public' and c.column_name = 'org_id' and t.table_type = 'BASE TABLE';
$$;

-- the purge must see every row: the function owner needs BYPASSRLS (superuser / Supabase postgres)
create or replace function public._tr184_sees_all()
returns boolean language sql stable security definer set search_path = '' as $$
  -- trial-retention-0184
  select coalesce((select r.rolsuper or r.rolbypassrls from pg_catalog.pg_roles r where r.rolname = current_user), false);
$$;

-- TRUE only inside _trial_retention_purge_org for that one studio (flag + 'purging' schedule row)
create or replace function public._trial_purge_allows(p_org uuid)
returns boolean language sql stable security definer set search_path = '' as $$
  -- trial-retention-0184
  select p_org is not null
     and coalesce(current_setting('helm.trial_purge_org', true), '') = p_org::text
     and coalesce(auth.jwt() ->> 'role', '') not in ('anon', 'authenticated')
     and exists (select 1 from public.trial_retention_schedule t where t.org_id = p_org and t.status = 'purging');
$$;

create or replace function public._tr184_label(p_kind text, p_delete_on date)
returns text language sql immutable set search_path = '' as $$
  -- trial-retention-0184: bell text (DD/MM/YYYY, the studio's own calendar day)
  select case p_kind
    when 'x7'    then 'Your free trial ended 7 days ago - upgrade to continue'
    when 'del30' then 'Trial data will be permanently deleted on ' || to_char(p_delete_on, 'DD/MM/YYYY')
    when 'del7'  then 'Trial data will be permanently deleted on ' || to_char(p_delete_on, 'DD/MM/YYYY')
    when 'del1'  then 'Final notice: trial data will be permanently deleted on ' || to_char(p_delete_on, 'DD/MM/YYYY')
    else 'Free trial update' end;
$$;

create or replace function public._tr184_notice_key(p_org uuid, p_kind text, p_expired timestamptz, p_delete_on date)
returns text language sql immutable set search_path = '' as $$
  -- trial-retention-0184: one per studio per kind per trial end (x7) / per deletion date (warnings)
  select 'trial184:' || p_kind || ':' || p_org::text || ':' ||
         case when p_kind = 'x7' then to_char(p_expired at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI')
              else to_char(p_delete_on, 'YYYY-MM-DD') end;
$$;

-- one notice row + (only when new) one admin-only bell row (the 0058 / 0120 'trial_reminder' kind)
create or replace function public._tr184_notice(p_org uuid, p_kind text, p_expired timestamptz, p_delete_on date)
returns boolean language plpgsql volatile security definer set search_path = '' as $$
-- trial-retention-0184
declare v_id uuid;
begin
  insert into public.trial_retention_notices(org_id, kind, expired_at, delete_on, dedupe_key)
    values (p_org, p_kind, p_expired, p_delete_on, public._tr184_notice_key(p_org, p_kind, p_expired, p_delete_on))
    on conflict (dedupe_key) do nothing
    returning id into v_id;
  if v_id is null then return false; end if;
  begin   -- the bell row must never block the ledger row
    insert into public.notifications(quote_id, channel, kind, status, detail, org_id)
      values (null, 'in_app', 'trial_reminder', 'simulated',
              jsonb_build_object('trial', 'trial_' || p_kind, 'milestone', p_kind, 'label', public._tr184_label(p_kind, p_delete_on),
                                 'expired_at', p_expired, 'delete_on', p_delete_on, 'source', '0184'),
              p_org);
  exception when others then raise warning 'trial-retention-0184: bell row skipped (%)', sqlstate;
  end;
  return true;
end $$;

-- ---- 4) the venue / studio-template no-delete guards: same refusal, one narrow purge exception -----
create or replace function public._a85_tg_venue_no_delete()
returns trigger language plpgsql security definer set search_path = '' as $$
-- venues-0085 trial-retention-0184: venues are never deleted, except by the owner-switched trial purge
begin
  if public._trial_purge_allows(old.org_id) then return old; end if;
  raise exception 'Venues are never deleted - deactivate the venue instead.' using errcode = '42501', hint = 'venue_no_delete';
end $$;

create or replace function public._a96_tg_no_delete()
returns trigger language plpgsql security definer set search_path = '' as $$
-- studio-templates-0096 trial-retention-0184: templates are never deleted, except by the trial purge
begin
  if public._trial_purge_allows(old.org_id) then return old; end if;
  raise exception 'Templates are never deleted - archive the template instead.' using errcode = '42501', hint = 'template_no_delete';
end $$;

-- ---- 5) the tick (pg_cron hourly / service role) -----------------------------------------------------
create or replace function public.trial_retention_tick()
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
-- trial-retention-0184: service role / pg_cron only. Idempotent (UNIQUE dedupe keys, one schedule per studio).
declare
  cfg public.helm_trial_retention := public._tr184_settings();
  o record; sch public.trial_retention_schedule; v_block text; v_tz text; v_exp timestamptz;
  v_today date; v_last date; v_target date; v_left integer; v_kind text;
  n_x7 integer := 0; n_arm integer := 0; n_cancel integer := 0; n_warn integer := 0; n_moved integer := 0;
begin
  for o in
    select x.id, x.timezone from (
      -- ended trials of the last 10 days (the +7 reminder) ...
      select org.id, org.timezone from public.organizations org join public.studio_subscriptions s on s.org_id = org.id
       where org.trial_ends_at is not null and org.trial_ends_at <= now() and org.trial_ends_at > now() - interval '10 days'
         and s.status in ('trial', 'past_due')
      union
      -- ... every ended trial without a schedule, while the deletion switch is on ...
      select org.id, org.timezone from public.organizations org join public.studio_subscriptions s on s.org_id = org.id
       where cfg.delete_enabled and org.trial_ends_at is not null and org.trial_ends_at <= now()
         and s.status in ('trial', 'past_due')
         and not exists (select 1 from public.trial_retention_schedule t where t.org_id = org.id)
      union
      -- ... and every open schedule (to follow / cancel / re-arm it)
      select org.id, org.timezone from public.trial_retention_schedule t join public.organizations org on org.id = t.org_id
       where t.status in ('scheduled', 'cancelled')
    ) x
  loop
    begin
      v_block := public._trial_retention_block(o.id);
      sch := null;
      select * into sch from public.trial_retention_schedule t where t.org_id = o.id for update;
      if v_block is not null then
        -- paid / extended / converted since: the deletion is called off (re-armed later only if it ends again)
        if sch.status = 'scheduled' then
          update public.trial_retention_schedule set status = 'cancelled', updated_at = now(),
                 last_error = left('not eligible: ' || v_block, 400)
           where org_id = o.id and status = 'scheduled';
          n_cancel := n_cancel + 1;
        end if;
        continue;
      end if;
      v_tz := public._tr184_tz(o.timezone);
      v_exp := public._trial_expired_at(o.id);
      v_today := public._tr184_local_date(now(), v_tz);
      v_last := public._tr184_last_day(o.id, v_tz);

      -- (a) item 9: one upgrade reminder 7 days after the trial's last day
      if v_today - v_last = 7 then
        if public._tr184_notice(o.id, 'x7', v_exp, null) then n_x7 := n_x7 + 1; end if;
      end if;

      -- (b) items 2 + 3: deletion date + warnings, only while the owner switch is on
      if not cfg.delete_enabled then continue; end if;
      v_target := greatest(v_last + cfg.retention_days, v_today + 30);
      if sch.org_id is null then
        insert into public.trial_retention_schedule(org_id, status, expired_at, delete_on, timezone)
          values (o.id, 'scheduled', v_exp, v_target, v_tz)
          on conflict (org_id) do nothing;
        n_arm := n_arm + 1;
        select * into sch from public.trial_retention_schedule t where t.org_id = o.id for update;
      elsif sch.status = 'cancelled' then
        update public.trial_retention_schedule set status = 'scheduled', expired_at = v_exp, delete_on = v_target,
               timezone = v_tz, armed_at = now(), failures = 0, last_error = null, updated_at = now()
         where org_id = o.id and status = 'cancelled'
        returning * into sch;
        n_arm := n_arm + 1;
      end if;
      if sch.status is distinct from 'scheduled' then continue; end if;      -- held / failed / deleted
      -- follow a later trial end or a longer retention; never move the date earlier
      if sch.expired_at is distinct from v_exp or sch.delete_on < v_last + cfg.retention_days then
        update public.trial_retention_schedule
           set expired_at = v_exp, delete_on = greatest(sch.delete_on, v_last + cfg.retention_days), updated_at = now()
         where org_id = o.id
        returning * into sch;
      end if;
      v_left := sch.delete_on - v_today;
      -- the final notice was missed (or is older than 14 days, e.g. the switch was off meanwhile): never
      -- delete without a fresh one - the deletion moves to tomorrow and a new final notice goes out
      if v_left <= 0 and not exists (select 1 from public.trial_retention_notices n where n.org_id = o.id
                                        and n.kind = 'del1' and n.delete_on = sch.delete_on
                                        and n.created_at > now() - interval '14 days') then
        update public.trial_retention_schedule set delete_on = v_today + 1, updated_at = now()
         where org_id = o.id
        returning * into sch;
        v_left := 1; n_moved := n_moved + 1;
      end if;
      v_kind := case when v_left <= 1 then 'del1' when v_left <= 7 then 'del7' when v_left <= 30 then 'del30' else null end;
      if v_kind is not null then
        if public._tr184_notice(o.id, v_kind, sch.expired_at, sch.delete_on) then n_warn := n_warn + 1; end if;
      end if;
    exception when others then raise warning 'trial-retention-0184: studio skipped (%)', sqlstate;
    end;
  end loop;
  return jsonb_build_object('x7_new', n_x7, 'armed', n_arm, 'cancelled', n_cancel, 'warnings_new', n_warn,
                            'final_notice_moved', n_moved, 'delete_enabled', cfg.delete_enabled);
end $$;

-- ---- 6) e-mail claim / mark (service role; comms-dispatch, DORMANT until redeployed) -----------------
create or replace function public.trial_retention_mail_settings()
returns jsonb language sql stable security definer set search_path = '' as $$
  -- trial-retention-0184: lets the d5 / d7 / d8 copy say "kept for 60 days" only when deletion is on
  select jsonb_build_object('retention_days', (public._tr184_settings()).retention_days,
                            'delete_enabled', (public._tr184_settings()).delete_enabled);
$$;

create or replace function public.trial_retention_email_claim(p_limit integer default 25)
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
-- trial-retention-0184: studio owner mails (Helm system mail, never a client message)
declare
  cfg public.helm_trial_retention := public._tr184_settings();
  r record; v_out jsonb := '[]'::jsonb; v_to text; v_ok boolean; v_del date;
  v_re constant text := '^[^\s@<>"'',;:\\]{1,64}@[A-Za-z0-9.-]{1,190}\.[A-Za-z]{2,24}$';
begin
  update public.trial_retention_notices set email_status = 'failed', email_sent_at = now()
   where email_sent_at is null and email_attempts >= 5;
  update public.trial_retention_notices set email_status = 'skipped', email_sent_at = now()
   where email_sent_at is null and created_at < now() - interval '2 days';
  for r in
    select n.id, n.org_id, n.kind, n.expired_at, n.delete_on, o.name, o.business_email, o.business_email_confirmed,
           o.created_by, public._tr184_tz(o.timezone) as tz
      from public.trial_retention_notices n join public.organizations o on o.id = n.org_id
     where n.email_sent_at is null and n.email_status = 'pending'
       and (n.email_claimed_at is null or n.email_claimed_at < now() - interval '10 minutes')
     order by n.created_at
     limit greatest(1, least(coalesce(p_limit, 25), 100))
     for update of n skip locked
  loop
    -- re-check at send time: still an expired never-paid trial, and (warnings) the same deletion date
    v_ok := public._trial_retention_block(r.org_id) is null;
    v_del := null;
    select t.delete_on into v_del from public.trial_retention_schedule t
     where t.org_id = r.org_id and t.status = 'scheduled' and cfg.delete_enabled;
    if r.kind = 'x7' then
      v_ok := v_ok and public._trial_expired_at(r.org_id) is not distinct from r.expired_at;
    else
      v_ok := v_ok and cfg.delete_enabled and v_del is not null and v_del = r.delete_on;
    end if;
    -- the studio owner's own login e-mail; the studio business e-mail only when it was confirmed
    v_to := (select u.email from auth.users u where u.id = r.created_by);
    if coalesce(v_to, '') !~ v_re and coalesce(r.business_email_confirmed, false) then v_to := r.business_email; end if;
    if not coalesce(v_ok, false) or coalesce(v_to, '') !~ v_re then
      update public.trial_retention_notices set email_status = 'skipped', email_sent_at = now() where id = r.id;
      continue;
    end if;
    update public.trial_retention_notices set email_claimed_at = now(), email_attempts = email_attempts + 1 where id = r.id;
    v_out := v_out || jsonb_build_array(jsonb_build_object('id', r.id, 'to', v_to, 'kind', r.kind,
      'studio', coalesce(r.name, ''), 'expired_at', r.expired_at,
      'delete_on', case when r.kind = 'x7' then v_del else r.delete_on end,
      'timezone', r.tz, 'retention_days', cfg.retention_days));
  end loop;
  return v_out;
end $$;

create or replace function public.trial_retention_email_mark(p_id uuid, p_status text)
returns text language plpgsql volatile security definer set search_path = '' as $$
-- trial-retention-0184
begin
  if p_status not in ('sent', 'skipped', 'failed', 'retry') then raise exception 'bad status' using errcode = '22023'; end if;
  if p_status = 'retry' then
    update public.trial_retention_notices set email_claimed_at = null where id = p_id and email_sent_at is null;
    return 'pending';
  end if;
  update public.trial_retention_notices set email_status = p_status, email_sent_at = now() where id = p_id and email_sent_at is null;
  return p_status;
end $$;

-- ---- 7) why a scheduled studio is not deleted right now (NULL = it would be, if the switch is on) ------
create or replace function public._tr184_wait_reason(p_org uuid)
returns text language plpgsql stable security definer set search_path = '' as $$
-- trial-retention-0184
declare cfg public.helm_trial_retention := public._tr184_settings(); sch public.trial_retention_schedule; v_block text;
begin
  select * into sch from public.trial_retention_schedule t where t.org_id = p_org;
  if not found then return 'not_scheduled'; end if;
  if sch.status <> 'scheduled' then return 'status_' || sch.status; end if;
  v_block := public._trial_retention_block(p_org);
  if v_block is not null then return 'not_eligible_' || v_block; end if;
  if sch.delete_on > public._tr184_local_date(now(), sch.timezone) then return 'not_due'; end if;
  if not exists (select 1 from public.trial_retention_notices n where n.org_id = p_org and n.kind = 'del1'
                    and n.delete_on = sch.delete_on and n.created_at <= now() - interval '20 hours'
                    and n.created_at > now() - interval '14 days') then
    return 'final_notice_pending'; end if;
  if cfg.require_email_notice and not exists (select 1 from public.trial_retention_notices n where n.org_id = p_org
                    and n.kind in ('del30', 'del7', 'del1') and n.email_status = 'sent') then
    return 'no_warning_email_sent'; end if;
  if not public._tr184_sees_all() then return 'owner_cannot_bypass_rls'; end if;
  return null;
end $$;

-- rows of ANOTHER studio that point (foreign key) at this studio's purge rows: must be {} to purge
create or replace function public._tr184_cross_links(p_org uuid)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
-- trial-retention-0184
declare fk record; v_n bigint; v_out jsonb := '{}'::jsonb; v_org_tabs text[] := public._tr184_org_tables();
begin
  -- a multi-column foreign key into a purge table cannot be checked here: report it (blocks the purge)
  select count(*) into v_n from pg_catalog.pg_constraint c join pg_catalog.pg_class pa on pa.oid = c.confrelid
   where c.contype = 'f' and pa.relnamespace = 'public'::regnamespace
     and pa.relname::text = any(public._tr184_purge_tables()) and array_length(c.conkey, 1) > 1;
  if v_n > 0 then v_out := jsonb_build_object('multi_column_foreign_keys', v_n); end if;
  for fk in
    select ch.relname::text as child, ca.attname::text as ccol, pa.relname::text as parent, pk.attname::text as pcol
      from pg_catalog.pg_constraint c
      join pg_catalog.pg_class ch on ch.oid = c.conrelid
      join pg_catalog.pg_class pa on pa.oid = c.confrelid
      join pg_catalog.pg_attribute ca on ca.attrelid = c.conrelid and ca.attnum = c.conkey[1]
      join pg_catalog.pg_attribute pk on pk.attrelid = c.confrelid and pk.attnum = c.confkey[1]
     where c.contype = 'f' and array_length(c.conkey, 1) = 1
       and ch.relnamespace = 'public'::regnamespace and pa.relnamespace = 'public'::regnamespace
       and pa.relname::text = any(public._tr184_purge_tables())
       and ch.relname::text = any(v_org_tabs) and pa.relname::text = any(v_org_tabs)
  loop
    execute format('select count(*) from public.%I ch join public.%I pa on pa.%I = ch.%I where pa.org_id = $1 and ch.org_id <> $1',
                   fk.child, fk.parent, fk.pcol, fk.ccol) into v_n using p_org;
    if v_n > 0 then v_out := v_out || jsonb_build_object(fk.child || '.' || fk.ccol || '->' || fk.parent, v_n); end if;
  end loop;
  return v_out;
end $$;

-- ---- 8) the purge of ONE studio (only via trial_retention_purge_due; refuses while the switch is off) --
create or replace function public._trial_retention_purge_org(p_org uuid)
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
-- trial-retention-0184: permanent deletion of ONE expired, never-paid trial studio's business rows
declare
  cfg public.helm_trial_retention := public._tr184_settings();
  sch public.trial_retention_schedule; v_wait text; v_cross jsonb;
  v_tabs text[] := public._tr184_purge_tables(); v_org_tabs text[] := public._tr184_org_tables();
  t text; n bigint; v_has boolean; v_before jsonb := '{}'::jsonb; v_counts jsonb := '{}'::jsonb;
  v_left integer := 0; v_blocked text; v_pass integer; v_audit bigint := 0; v_files bigint := 0;
begin
  if p_org is null then raise exception 'no studio' using errcode = '22023'; end if;
  if not cfg.delete_enabled then
    raise exception 'trial data deletion is switched off' using errcode = '42501', hint = 'trial_retention_disabled'; end if;
  perform pg_advisory_xact_lock(hashtextextended('helm:trial_retention:' || p_org::text, 0));
  -- lock the subscription + studio rows: a payment / extension landing now waits, then is re-checked
  perform 1 from public.studio_subscriptions ss where ss.org_id = p_org for update;
  perform 1 from public.organizations oo where oo.id = p_org for update;
  select * into sch from public.trial_retention_schedule trs where trs.org_id = p_org for update;
  v_wait := public._tr184_wait_reason(p_org);
  if v_wait is not null then
    raise exception 'trial purge refused: %', v_wait using errcode = 'P0001', hint = 'trial_retention_not_due'; end if;
  v_cross := public._tr184_cross_links(p_org);
  if v_cross <> '{}'::jsonb then
    raise exception 'trial purge refused: rows of another studio link to this studio (%)', left(v_cross::text, 200)
      using errcode = 'P0001', hint = 'trial_retention_cross_studio'; end if;

  foreach t in array v_org_tabs loop
    execute format('select count(*) from public.%I where org_id = $1', t) into n using p_org;
    v_before := v_before || jsonb_build_object(t, n);
  end loop;

  update public.trial_retention_schedule set status = 'purging', updated_at = now() where org_id = p_org;
  perform set_config('helm.trial_purge_org', p_org::text, true);

  -- delete, retrying in later passes when a row is still referenced (cascades / archive triggers)
  for v_pass in 1..8 loop
    foreach t in array v_tabs loop
      continue when not (t = any(v_org_tabs));
      begin
        execute format('delete from public.%I where org_id = $1', t) using p_org;
      exception when foreign_key_violation or restrict_violation then v_blocked := t;
      end;
    end loop;
    v_left := 0;
    foreach t in array v_tabs loop
      continue when not (t = any(v_org_tabs));
      execute format('select exists (select 1 from public.%I where org_id = $1)', t) into v_has using p_org;
      if v_has then v_left := v_left + 1; v_blocked := t; end if;
    end loop;
    exit when v_left = 0;
  end loop;
  if v_left > 0 then
    raise exception 'trial purge incomplete: % table(s) still hold rows (e.g. %)', v_left, v_blocked
      using errcode = 'P0001', hint = 'trial_retention_incomplete'; end if;

  -- the audit trigger copied every deleted business row into audit_log: remove those copies too
  -- (billing, subscription, studio and member audit rows stay)
  delete from public.audit_log al where al.org_id = p_org and al.entity = any(v_tabs);
  get diagnostics v_audit = row_count;
  perform set_config('helm.trial_purge_org', '', true);

  foreach t in array v_org_tabs loop
    execute format('select count(*) from public.%I where org_id = $1', t) into n using p_org;
    if coalesce((v_before ->> t)::bigint, 0) - n <> 0 then
      v_counts := v_counts || jsonb_build_object(t, coalesce((v_before ->> t)::bigint, 0) - n);
    end if;
  end loop;
  if to_regclass('storage.objects') is not null then
    begin
      execute 'select count(*) from storage.objects where split_part(name, ''/'', 1) = $1' into v_files using p_org::text;
    exception when others then v_files := -1;
    end;
  end if;

  update public.trial_retention_schedule set status = 'deleted', deleted_at = now(), last_error = null, updated_at = now()
   where org_id = p_org;
  insert into public.trial_retention_runs(org_id, action, ok, delete_on, counts)
    values (p_org, 'purge', true, sch.delete_on,
            jsonb_build_object('rows', v_counts, 'audit_log_copies', v_audit, 'storage_objects_left', v_files));
  insert into public.audit_log(actor, actor_email, action, entity, entity_id, changed, org_id, at)
    values (null, 'helm:retention', 'trial.retention_purged', 'organizations', p_org::text,
            jsonb_build_object('delete_on', sch.delete_on, 'expired_at', sch.expired_at, 'retention_days', cfg.retention_days,
                               'rows', v_counts, 'audit_log_copies', v_audit, 'storage_objects_left', v_files),
            p_org, now());
  return jsonb_build_object('org_id', p_org, 'deleted', true, 'rows', v_counts, 'audit_log_copies', v_audit,
                            'storage_objects_left', v_files);
end $$;

-- ---- 9) the daily deletion job (pg_cron / service role). Switch off -> returns at once, touches nothing --
create or replace function public.trial_retention_purge_due(p_limit integer default null)
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
-- trial-retention-0184
declare
  cfg public.helm_trial_retention := public._tr184_settings();
  r record; v_lim integer; n_ok integer := 0; n_fail integer := 0; n_wait integer := 0; v_msg text; v_state text;
begin
  if not cfg.delete_enabled then return jsonb_build_object('delete_enabled', false, 'deleted', 0); end if;
  v_lim := greatest(1, least(coalesce(p_limit, cfg.max_deletes_per_run), cfg.max_deletes_per_run));
  for r in
    select t.org_id, t.delete_on from public.trial_retention_schedule t
     where t.status = 'scheduled' and t.delete_on <= (now() at time zone 'UTC')::date + 1
     order by t.delete_on, t.org_id
  loop
    exit when n_ok + n_fail >= v_lim;
    if public._tr184_wait_reason(r.org_id) is not null then n_wait := n_wait + 1; continue; end if;
    begin
      perform public._trial_retention_purge_org(r.org_id);
      n_ok := n_ok + 1;
    exception when others then
      get stacked diagnostics v_msg = message_text, v_state = returned_sqlstate;
      n_fail := n_fail + 1;
      update public.trial_retention_schedule
         set failures = failures + 1, last_error = left(v_state || ' ' || v_msg, 400), updated_at = now(),
             status = case when failures + 1 >= 3 then 'failed' else status end
       where org_id = r.org_id and status = 'scheduled';
      insert into public.trial_retention_runs(org_id, action, ok, delete_on, error)
        values (r.org_id, 'purge_failed', false, r.delete_on, left(v_state || ' ' || v_msg, 400));
    end;
  end loop;
  return jsonb_build_object('delete_enabled', true, 'deleted', n_ok, 'failed', n_fail, 'waiting', n_wait);
end $$;

-- ---- 10) the dry-run report (read-only) -----------------------------------------------------------------
create or replace function public.trial_retention_dry_run(p_org uuid default null, p_with_counts boolean default false)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
-- trial-retention-0184: who would be deleted when, and why not. Writes nothing.
declare
  cfg public.helm_trial_retention := public._tr184_settings();
  o record; sch public.trial_retention_schedule; v_block text; v_wait text; v_tz text; v_last date; v_today date;
  v_item jsonb; v_out jsonb := '[]'::jsonb; v_purge jsonb; v_keep jsonb; v_other jsonb; v_cnt jsonb; t text; n bigint;
  v_org_tabs text[] := public._tr184_org_tables(); v_files bigint; v_audit bigint;
  n_c integer := 0; n_e integer := 0; n_s integer := 0; n_due integer := 0;
begin
  for o in
    select x.id, x.name, x.timezone from public.organizations x
     where (p_org is not null and x.id = p_org)
        or (p_org is null and (exists (select 1 from public.trial_retention_schedule trs where trs.org_id = x.id)
             or (x.trial_ends_at is not null and x.trial_ends_at <= now()
                 and exists (select 1 from public.studio_subscriptions s where s.org_id = x.id and s.status in ('trial', 'past_due')))))
     order by x.trial_ends_at nulls last, x.id
  loop
    n_c := n_c + 1;
    v_block := public._trial_retention_block(o.id);
    sch := null;
    select * into sch from public.trial_retention_schedule trs where trs.org_id = o.id;
    v_tz := public._tr184_tz(coalesce(sch.timezone, o.timezone));
    v_today := public._tr184_local_date(now(), v_tz);
    v_last := case when public._trial_expired_at(o.id) is not null then public._tr184_last_day(o.id, v_tz) end;
    v_wait := case when sch.org_id is null then 'not_scheduled' else public._tr184_wait_reason(o.id) end;
    if v_block is null then n_e := n_e + 1; end if;
    if sch.status = 'scheduled' then n_s := n_s + 1; end if;
    if v_wait is null then n_due := n_due + 1; end if;
    v_item := jsonb_build_object(
      'org_id', o.id, 'name', o.name, 'eligible', v_block is null, 'block_reason', v_block,
      'expired_at', public._trial_expired_at(o.id), 'last_trial_day', v_last,
      'days_since_trial_end', case when v_last is not null then v_today - v_last end,
      'schedule_status', sch.status, 'delete_on', sch.delete_on, 'armed_at', sch.armed_at, 'failures', sch.failures,
      'last_error', sch.last_error, 'hold_reason', sch.hold_reason,
      'projected_delete_on', case when v_block is null and sch.org_id is null and v_last is not null
                                  then greatest(v_last + cfg.retention_days, v_today + 30) end,
      'wait_reason', v_wait,
      'would_delete_if_enabled', v_wait is null,
      'would_delete_now', cfg.delete_enabled and v_wait is null,
      'notices', coalesce((select jsonb_agg(jsonb_build_object('kind', trn.kind, 'delete_on', trn.delete_on, 'email', trn.email_status,
                                                               'created_at', trn.created_at) order by trn.created_at)
                             from public.trial_retention_notices trn where trn.org_id = o.id), '[]'::jsonb));
    if p_with_counts or p_org is not null then
      v_purge := '{}'::jsonb; v_keep := '{}'::jsonb; v_other := '{}'::jsonb;
      foreach t in array v_org_tabs loop
        execute format('select count(*) from public.%I where org_id = $1', t) into n using o.id;
        continue when n = 0;
        if t = any(public._tr184_purge_tables()) then v_purge := v_purge || jsonb_build_object(t, n);
        elsif t = any(public._tr184_keep_tables()) then v_keep := v_keep || jsonb_build_object(t, n);
        else v_other := v_other || jsonb_build_object(t, n); end if;
      end loop;
      select count(*) into v_audit from public.audit_log al where al.org_id = o.id and al.entity = any(public._tr184_purge_tables());
      v_files := null;
      if to_regclass('storage.objects') is not null then
        begin
          execute 'select count(*) from storage.objects where split_part(name, ''/'', 1) = $1' into v_files using o.id::text;
        exception when others then v_files := null;
        end;
      end if;
      v_item := v_item || jsonb_build_object('would_delete_rows', v_purge, 'audit_log_copies', v_audit,
        'kept_rows', v_keep, 'unclassified_rows_kept', v_other, 'storage_objects_not_deleted', v_files,
        'cross_studio_links', public._tr184_cross_links(o.id));
    end if;
    v_out := v_out || jsonb_build_array(v_item);
  end loop;
  return jsonb_build_object(
    'settings', jsonb_build_object('delete_enabled', cfg.delete_enabled, 'retention_days', cfg.retention_days,
                                   'require_email_notice', cfg.require_email_notice, 'max_deletes_per_run', cfg.max_deletes_per_run),
    'owner_can_bypass_rls', public._tr184_sees_all(),
    'unclassified_tables', coalesce((select jsonb_agg(u.tab order by u.tab) from unnest(v_org_tabs) as u(tab)
                                      where not (u.tab = any(public._tr184_purge_tables())) and not (u.tab = any(public._tr184_keep_tables()))), '[]'::jsonb),
    'summary', jsonb_build_object('studios', n_c, 'eligible', n_e, 'scheduled', n_s, 'due_now_if_enabled', n_due),
    'studios', v_out);
end $$;

-- ---- 11) keep one studio out of deletion (or release it: it is re-scheduled with >= 30 days notice) -------
create or replace function public.trial_retention_set_hold(p_org uuid, p_hold boolean, p_reason text default null)
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
-- trial-retention-0184
declare v_tz text; v_n integer;
begin
  if p_org is null or not exists (select 1 from public.organizations o where o.id = p_org) then
    raise exception 'unknown studio' using errcode = '22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended('helm:trial_retention:' || p_org::text, 0));
  if coalesce(p_hold, false) then
    select public._tr184_tz(o.timezone) into v_tz from public.organizations o where o.id = p_org;
    insert into public.trial_retention_schedule(org_id, status, expired_at, delete_on, timezone, hold_reason)
      values (p_org, 'held', public._trial_expired_at(p_org), null, v_tz, left(nullif(btrim(coalesce(p_reason, '')), ''), 500))
      on conflict (org_id) do update set status = 'held', hold_reason = excluded.hold_reason, updated_at = now()
      where public.trial_retention_schedule.status not in ('deleted', 'purging');
  else
    update public.trial_retention_schedule set status = 'cancelled', hold_reason = null, failures = 0, last_error = null,
           updated_at = now()
     where org_id = p_org and status in ('held', 'failed');
  end if;
  get diagnostics v_n = row_count;
  insert into public.trial_retention_runs(org_id, action, ok, counts)
    values (p_org, case when coalesce(p_hold, false) then 'hold' else 'release' end, v_n > 0,
            jsonb_build_object('reason', left(coalesce(p_reason, ''), 200)));
  return jsonb_build_object('org_id', p_org, 'held', coalesce(p_hold, false), 'changed', v_n > 0,
    'status', (select t.status from public.trial_retention_schedule t where t.org_id = p_org));
end $$;

-- ---- 12) privileges: platform only (service role / pg_cron / SQL editor) ---------------------------------
do $$ declare f text; begin
  foreach f in array array[
    'public._tr184_settings_audit()', 'public._tr184_settings()', 'public._tr184_tz(text)', 'public._tr184_local_date(timestamptz, text)',
    'public._trial_expired_at(uuid)', 'public._tr184_last_day(uuid, text)', 'public._trial_retention_block(uuid)',
    'public._tr184_purge_tables()', 'public._tr184_keep_tables()', 'public._tr184_org_tables()', 'public._tr184_sees_all()',
    'public._trial_purge_allows(uuid)', 'public._tr184_label(text, date)', 'public._tr184_notice_key(uuid, text, timestamptz, date)',
    'public._tr184_notice(uuid, text, timestamptz, date)', 'public._a85_tg_venue_no_delete()', 'public._a96_tg_no_delete()',
    'public.trial_retention_tick()', 'public.trial_retention_mail_settings()', 'public.trial_retention_email_claim(integer)',
    'public.trial_retention_email_mark(uuid, text)', 'public._tr184_wait_reason(uuid)', 'public._tr184_cross_links(uuid)',
    'public._trial_retention_purge_org(uuid)', 'public.trial_retention_purge_due(integer)',
    'public.trial_retention_dry_run(uuid, boolean)', 'public.trial_retention_set_hold(uuid, boolean, text)'] loop
    execute format('revoke all on function %s from public', f);
    if exists (select 1 from pg_roles where rolname = 'anon') then execute format('revoke all on function %s from anon', f); end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then execute format('revoke all on function %s from authenticated', f); end if;
    -- internals too: the service role only gets the seven entry points below
    if exists (select 1 from pg_roles where rolname = 'service_role') then execute format('revoke all on function %s from service_role', f); end if;
  end loop;
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    execute 'grant execute on function public.trial_retention_tick() to service_role';
    execute 'grant execute on function public.trial_retention_mail_settings() to service_role';
    execute 'grant execute on function public.trial_retention_email_claim(integer) to service_role';
    execute 'grant execute on function public.trial_retention_email_mark(uuid, text) to service_role';
    execute 'grant execute on function public.trial_retention_purge_due(integer) to service_role';
    execute 'grant execute on function public.trial_retention_dry_run(uuid, boolean) to service_role';
    execute 'grant execute on function public.trial_retention_set_hold(uuid, boolean, text) to service_role';
  end if;
end $$;

-- ---- 13) pg_cron, ONLY if it is already installed (never created here) -----------------------------------
do $$ begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    begin
      if not exists (select 1 from cron.job where jobname = 'helm_trial_retention') then
        perform cron.schedule('helm_trial_retention', '27 * * * *', 'select public.trial_retention_tick()');
      end if;
      -- does nothing until helm_trial_retention.delete_enabled is switched on by the owner
      if not exists (select 1 from cron.job where jobname = 'helm_trial_retention_purge') then
        perform cron.schedule('helm_trial_retention_purge', '13 22 * * *', 'select public.trial_retention_purge_due()');
      end if;
    exception when others then
      raise notice 'pg_cron present but the trial retention jobs could not be scheduled (%); schedule them by hand', sqlerrm;
    end;
  else
    raise notice '0184: pg_cron not installed - run select public.trial_retention_tick() hourly and select public.trial_retention_purge_due() daily from a service caller';
  end if;
end $$;

notify pgrst, 'reload schema';
commit;

-- VERIFY (every row should say ok = true; row 03 turns false once you switch deletion on - that is expected)
select item, ok from (values
  ('01 four new tables', to_regclass('public.helm_trial_retention') is not null and to_regclass('public.trial_retention_schedule') is not null
     and to_regclass('public.trial_retention_notices') is not null and to_regclass('public.trial_retention_runs') is not null),
  ('02 owner switch row present (60 days)', exists (select 1 from public.helm_trial_retention where id and retention_days >= 30)),
  ('03 deletion is switched OFF', not coalesce((select delete_enabled from public.helm_trial_retention where id), true)),
  ('04 row level security on the new tables', (select bool_and(relrowsecurity) from pg_class where oid in ('public.helm_trial_retention'::regclass,
     'public.trial_retention_schedule'::regclass, 'public.trial_retention_notices'::regclass, 'public.trial_retention_runs'::regclass))),
  ('05 app roles cannot read the new tables', not has_table_privilege('authenticated', 'public.helm_trial_retention', 'select')
     and not has_table_privilege('authenticated', 'public.trial_retention_schedule', 'select')
     and not has_table_privilege('authenticated', 'public.trial_retention_notices', 'select')
     and not has_table_privilege('anon', 'public.trial_retention_runs', 'select')),
  ('06 entry points are SECURITY DEFINER', (select bool_and(prosecdef) from pg_proc where oid in (
     'public.trial_retention_tick()'::regprocedure, 'public.trial_retention_email_claim(integer)'::regprocedure,
     'public.trial_retention_purge_due(integer)'::regprocedure, 'public._trial_retention_purge_org(uuid)'::regprocedure,
     'public.trial_retention_dry_run(uuid, boolean)'::regprocedure, 'public.trial_retention_set_hold(uuid, boolean, text)'::regprocedure))),
  ('07 app roles cannot run them', not has_function_privilege('authenticated', 'public.trial_retention_tick()', 'execute')
     and not has_function_privilege('authenticated', 'public.trial_retention_purge_due(integer)', 'execute')
     and not has_function_privilege('authenticated', 'public._trial_retention_purge_org(uuid)', 'execute')
     and not has_function_privilege('authenticated', 'public.trial_retention_dry_run(uuid, boolean)', 'execute')
     and not has_function_privilege('anon', 'public.trial_retention_email_claim(integer)', 'execute')
     and not has_function_privilege('anon', 'public.trial_retention_set_hold(uuid, boolean, text)', 'execute')),
  ('08 service role runs the jobs + comms-dispatch claim', has_function_privilege('service_role', 'public.trial_retention_tick()', 'execute')
     and has_function_privilege('service_role', 'public.trial_retention_email_claim(integer)', 'execute')
     and has_function_privilege('service_role', 'public.trial_retention_email_mark(uuid, text)', 'execute')
     and has_function_privilege('service_role', 'public.trial_retention_mail_settings()', 'execute')
     and has_function_privilege('service_role', 'public.trial_retention_purge_due(integer)', 'execute')),
  ('09 the single-studio purge is internal only; the switch is flipped in the SQL editor only',
     not has_function_privilege('service_role', 'public._trial_retention_purge_org(uuid)', 'execute')
     and not has_table_privilege('service_role', 'public.helm_trial_retention', 'update')),
  ('10 venue + template guards re-issued with the purge-only exception',
     position('trial-retention-0184' in (select prosrc from pg_proc where oid = 'public._a85_tg_venue_no_delete()'::regprocedure)) > 0
     and position('trial-retention-0184' in (select prosrc from pg_proc where oid = 'public._a96_tg_no_delete()'::regprocedure)) > 0),
  ('11 dry-run report works (read-only)', public.trial_retention_dry_run(null, false) ? 'summary'),
  ('12 every studio table is classified delete / keep', public.trial_retention_dry_run(null, false) -> 'unclassified_tables' = '[]'::jsonb),
  ('13 the deletion job owner can see every row (BYPASSRLS)', (public.trial_retention_dry_run(null, false) ->> 'owner_can_bypass_rls')::boolean),
  ('14 day 5 / 7 / 8 reminders unchanged', to_regprocedure('public.trial_reminder_email_claim(integer)') is not null
     and to_regprocedure('public.trial_reminders_tick()') is not null),
  ('15 nothing scheduled for deletion while the switch is off', coalesce((select delete_enabled from public.helm_trial_retention where id), false)
     or not exists (select 1 from public.trial_retention_schedule where status in ('scheduled', 'purging')))
) v(item, ok) order by item;

-- ##########################################################################################
-- RELEASE SECTION 12/28: APPLY-0185.sql
-- In plain words: Upgrade data choice: keep / remove sample data, or start clean (archive, never delete).
-- ##########################################################################################
-- APPLY-0185.sql - paste into the Supabase SQL editor (staging first, then production).
-- Additive + idempotent: the upgrade data choice (keep sample data [default] / remove sample data / start
-- completely clean = archive, never delete), "Delete all sample data" (is_demo rows only) and restore.
-- Changes no row when it runs. Paid studios that never were a trial are unaffected. Safe to run twice.
begin;
-- ============================================================================
-- 0185_trial_upgrade_choice.sql - CANONICAL forward-only. REQUIRES 0040 (quote Archive shelf),
-- 0097 (is_demo, _demo_clear), 0127 (demo_choice), 0166 (_is_trial_org, sample master),
-- 0167 + 0169 (_demo_clear wrappers).
--
-- In plain words (owner post-trial policy items 4 + 5, docs/trial/POST-TRIAL-POLICY.md):
--   WHEN A FREE-TRIAL STUDIO UPGRADES, the studio admin chooses what happens to the data:
--     keep           (default) keep the sample data. Every sample row stays is_demo = true, so it
--                    keeps its "Sample" badge for good and "Delete all sample data" can still find it.
--     remove_sample  remove ONLY the sample rows (is_demo, the same _demo_clear the trial already
--                    uses); every record the studio added itself stays.
--     clean          start completely clean: the sample rows go as in remove_sample, and EVERY record
--                    of the studio's own is ARCHIVED - never deleted:
--                      events / quotes      -> the existing Archive shelf (quotes.archived_at, 0040;
--                                              Restore button in Quotes > Archive)
--                      inventory, vendors, staff (not linked to a login), venues, menu packages,
--                      dishes                -> switched off (active = false, the app's own "remove")
--                      leads, follow-ups (nurture), saved floor layouts
--                                           -> new nullable clean_archived_at; a RESTRICTIVE RLS policy
--                                              hides those rows from the app (no permissive policy is
--                                              widened, nothing becomes visible that was not)
--                    Every archived row is written to studio_clean_start_items (studio, batch, table,
--                    row id) so restore_clean_start() puts all of it back in one step. Settings, team
--                    members, plan + billing, templates and the price list are not touched.
--                    The server needs the typed phrase START CLEAN (the app also asks twice).
--   The choice is made once, only by an admin of the studio's OWN org (current_org_id()), only when
--   the studio started as a trial (its subscription / studio carries trial history) and is NO LONGER
--   in trial (public._is_trial_org() false - studio_subscriptions.status, never trial_ends_at) and is
--   on a paid / active plan. Paid studios that never were a trial are refused and unaffected.
--   Safety for sample events the studio really used after upgrading: a sample event with the
--   studio's own payments, a real OTP approval, refunds or uploaded files is ADOPTED (is_demo ->
--   false) before any clear in a non-trial studio, so it is kept with those records.
--   Control Center: delete_all_sample_data() - admin, own studio, is_demo rows only (_demo_clear).
--   my_upgrade_status() - read-only state for the dashboard / Control Center / checkout cards.
--
--   Changes: 3 nullable columns on organizations (+ a check + an API guard trigger), 1 nullable
--   column + 1 partial index + 1 restrictive policy on leads / nurture / layouts, 1 new table
--   (RLS on, no tenant policy, definer RPCs only, 0045 read-only guard), 10 new functions. One existing function body
--   replaced: the 0173 trial wrapper of my_studio_account_update (section 10, checkout billing in the trial). Otherwise none replaced,
--   no row changed by this migration. No DROP TABLE / DROP COLUMN / TRUNCATE; the only row
--   removals anywhere are the existing _demo_clear of is_demo (sample) rows, on an admin's choice.
--   Additive + idempotent: safe to run twice. ASCII only.
-- ============================================================================

do $$ begin
  if to_regprocedure('public._demo_clear(uuid)') is null or to_regprocedure('public._is_trial_org(uuid)') is null
     or to_regprocedure('public.trial_demo_choice(text)') is null or to_regprocedure('public._trial_locked(uuid)') is null
     or to_regprocedure('public._trial_paid(uuid)') is null or to_regprocedure('public._studio_writable(uuid)') is null
     or to_regprocedure('public.tg_studio_read_only()') is null then
    raise exception '0185: apply 0040, 0097, 0116, 0127, 0166, 0167 and 0169 first'; end if;
end $$;

-- ---- 1) the choice on the studio (3 nullable columns) ------------------------------------------
alter table public.organizations add column if not exists upgrade_choice text;
alter table public.organizations add column if not exists upgrade_choice_at timestamptz;
alter table public.organizations add column if not exists upgrade_choice_by uuid;
do $$ begin
  if not exists (select 1 from pg_constraint where conrelid = 'public.organizations'::regclass
                  and conname = 'organizations_upgrade_choice_chk185') then
    alter table public.organizations add constraint organizations_upgrade_choice_chk185
      check (upgrade_choice is null or upgrade_choice in ('keep', 'remove_sample', 'clean'));
  end if;
end $$;

-- the app roles can read these columns but never write them (only the functions below may)
create or replace function public._tu185_tg_choice_guard()
returns trigger language plpgsql set search_path = '' as $$
-- trial-upgrade-0185
begin
  if current_user in ('anon', 'authenticated')
     and (new.upgrade_choice, new.upgrade_choice_at, new.upgrade_choice_by)
         is distinct from (old.upgrade_choice, old.upgrade_choice_at, old.upgrade_choice_by) then
    raise exception 'the upgrade data choice is made through the upgrade screen only' using errcode = '42501';
  end if;
  return new;
end $$;
do $$ begin
  if not exists (select 1 from pg_trigger where tgrelid = 'public.organizations'::regclass and tgname = 'zz_tu185_choice_guard') then
    create trigger zz_tu185_choice_guard before update of upgrade_choice, upgrade_choice_at, upgrade_choice_by
      on public.organizations for each row execute function public._tu185_tg_choice_guard();
  end if;
end $$;

-- ---- 2) soft archive flag where a list has no flag of its own ----------------------------------
alter table public.leads   add column if not exists clean_archived_at timestamptz;
alter table public.nurture add column if not exists clean_archived_at timestamptz;
alter table public.layouts add column if not exists clean_archived_at timestamptz;
create index if not exists leads_clean_archived_idx185   on public.leads (org_id)   where clean_archived_at is not null;
create index if not exists nurture_clean_archived_idx185 on public.nurture (org_id) where clean_archived_at is not null;
create index if not exists layouts_clean_archived_idx185 on public.layouts (org_id) where clean_archived_at is not null;

-- RESTRICTIVE: an archived row is invisible and read-only for every app role; nobody can set the
-- flag through the API (with check). It only ever narrows what the existing policies allow.
do $$ declare t text; begin
  foreach t in array array['leads', 'nurture', 'layouts'] loop
    if not exists (select 1 from pg_policies where schemaname = 'public' and tablename = t and policyname = 'helm_clean_archive_185') then
      execute format('create policy helm_clean_archive_185 on public.%I as restrictive for all to public '
                     'using (clean_archived_at is null) with check (clean_archived_at is null)', t);
    end if;
  end loop;
end $$;

-- ---- 3) the archive journal: one row per archived record (definer RPCs only) --------------------
create table if not exists public.studio_clean_start_items (
  id          bigint generated always as identity primary key,
  org_id      uuid not null references public.organizations(id),
  batch_id    uuid not null,
  tbl         text not null,
  row_id      uuid not null,
  archived_at timestamptz not null default now(),
  archived_by uuid,
  restored_at timestamptz,
  restored_by uuid,
  constraint studio_clean_start_items_tbl_chk185 check (tbl in ('quotes', 'leads', 'nurture', 'layouts', 'inventory_items',
    'vendors', 'crew_members', 'venues', 'menu_templates', 'dish_catalog')),
  constraint studio_clean_start_items_uq185 unique (batch_id, tbl, row_id)
);
create index if not exists studio_clean_start_items_org_idx185 on public.studio_clean_start_items (org_id, restored_at);
alter table public.studio_clean_start_items enable row level security;
-- like every studio table: no write while the studio is suspended / read-only (0045 guard)
do $$ begin
  if not exists (select 1 from pg_trigger where tgrelid = 'public.studio_clean_start_items'::regclass and tgname = 'zzz_studio_read_only') then
    create trigger zzz_studio_read_only before insert or update or delete on public.studio_clean_start_items
      for each row execute function public.tg_studio_read_only('org_id');
  end if;
end $$;
revoke all on public.studio_clean_start_items from public;
do $$ begin
  if exists (select 1 from pg_roles where rolname = 'anon') then revoke all on public.studio_clean_start_items from anon; end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then revoke all on public.studio_clean_start_items from authenticated; end if;
  if exists (select 1 from pg_roles where rolname = 'service_role') then grant select on public.studio_clean_start_items to service_role; end if;
end $$;

-- ---- 4) helpers -----------------------------------------------------------------------------------
-- the studio is past its trial and on a working plan (active, or a paid period that is overdue)
create or replace function public._tu185_converted(p_org uuid)
returns boolean language sql stable security definer set search_path = '' as $$
  -- trial-upgrade-0185: "in trial" comes from the subscription (_is_trial_org), never trial_ends_at
  select p_org is not null
     and not public._is_trial_org(p_org)
     and not public._trial_locked(p_org)
     and public._studio_writable(p_org)
     and (exists (select 1 from public.studio_subscriptions s where s.org_id = p_org
                   and (s.status = 'active' or (s.status = 'past_due' and s.current_period_end is not null)))
          or public._trial_paid(p_org));
$$;

-- the studio STARTED as a free trial (history only - not "is it in trial now", see _tu185_converted)
create or replace function public._tu185_was_trial(p_org uuid)
returns boolean language sql stable security definer set search_path = '' as $$
  -- trial-upgrade-0185
  select p_org is not null
     and not exists (select 1 from public.organizations o where o.id = p_org and o.is_sample_master)
     and (exists (select 1 from public.studio_subscriptions s where s.org_id = p_org
                   and (s.trial_ends_at is not null or s.trial_source is not null))
          or exists (select 1 from public.organizations o where o.id = p_org and o.trial_mode is not null));
$$;

-- a SAMPLE event the studio really used is adopted (kept as its own) before any clear
create or replace function public._tu185_adopt_used_samples(p_org uuid)
returns integer language plpgsql volatile security definer set search_path = '' as $$
-- trial-upgrade-0185: own payments / a real OTP approval / refunds / uploads keep the event
declare n integer := 0;
begin
  if p_org is null then return 0; end if;
  update public.quotes q set is_demo = false
   where q.org_id = p_org and q.is_demo
     and (exists (select 1 from public.quote_payments p where p.quote_id = q.id and p.org_id = p_org
                   and not p.is_demo and p.status in ('paid', 'refunded'))
       or exists (select 1 from public.payment_milestones m where m.quote_id = q.id and m.org_id = p_org
                   and not m.is_demo and m.status = 'paid')
       or exists (select 1 from public.quote_consents c where c.quote_id = q.id and c.verified_via_otp)
       or exists (select 1 from public.event_refunds r where r.quote_id = q.id)
       or exists (select 1 from public.event_files f where f.quote_id = q.id)
       or exists (select 1 from public.event_media md where md.quote_id = q.id));
  get diagnostics n = row_count;
  return n;
end $$;

-- "start completely clean": archive (never delete) every own record of ONE studio, journaled
create or replace function public._tu185_archive_own(p_org uuid, p_actor uuid)
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
-- trial-upgrade-0185: soft only - Archive shelf / active = false / clean_archived_at
declare v_batch uuid := gen_random_uuid(); v_out jsonb := '{}'::jsonb; n integer;
begin
  if p_org is null then raise exception 'no studio' using errcode = '42501'; end if;
  if exists (select 1 from public.organizations o where o.id = p_org and o.is_sample_master) then
    raise exception 'the sample master is never archived' using errcode = '42501'; end if;
  perform pg_advisory_xact_lock(hashtextextended('helm:clean_start:' || p_org::text, 0));

  -- events / quotes -> the 0040 Archive shelf (Restore in Quotes > Archive)
  insert into public.studio_clean_start_items(org_id, batch_id, tbl, row_id, archived_by)
    select p_org, v_batch, 'quotes', q.id, p_actor from public.quotes q
     where q.org_id = p_org and not q.is_demo and q.archived_at is null and q.deleted_at is null;
  update public.quotes q set archived_at = now(), archived_by = p_actor, archived_reason = 'manual'
   where q.org_id = p_org and q.archived_at is null and q.deleted_at is null
     and q.id in (select i.row_id from public.studio_clean_start_items i
                   where i.org_id = p_org and i.batch_id = v_batch and i.tbl = 'quotes');
  get diagnostics n = row_count; v_out := v_out || jsonb_build_object('events', n);

  -- leads / follow-ups / saved floor layouts -> clean_archived_at (hidden by helm_clean_archive_185)
  insert into public.studio_clean_start_items(org_id, batch_id, tbl, row_id, archived_by)
    select p_org, v_batch, 'leads', x.id, p_actor from public.leads x
     where x.org_id = p_org and not x.is_demo and x.clean_archived_at is null;
  update public.leads x set clean_archived_at = now()
   where x.org_id = p_org and x.clean_archived_at is null
     and x.id in (select i.row_id from public.studio_clean_start_items i where i.org_id = p_org and i.batch_id = v_batch and i.tbl = 'leads');
  get diagnostics n = row_count; v_out := v_out || jsonb_build_object('leads', n);

  insert into public.studio_clean_start_items(org_id, batch_id, tbl, row_id, archived_by)
    select p_org, v_batch, 'nurture', x.id, p_actor from public.nurture x
     where x.org_id = p_org and not x.is_demo and x.clean_archived_at is null;
  update public.nurture x set clean_archived_at = now()
   where x.org_id = p_org and x.clean_archived_at is null
     and x.id in (select i.row_id from public.studio_clean_start_items i where i.org_id = p_org and i.batch_id = v_batch and i.tbl = 'nurture');
  get diagnostics n = row_count; v_out := v_out || jsonb_build_object('nurture', n);

  insert into public.studio_clean_start_items(org_id, batch_id, tbl, row_id, archived_by)
    select p_org, v_batch, 'layouts', x.id, p_actor from public.layouts x
     where x.org_id = p_org and not x.is_demo and x.clean_archived_at is null;
  update public.layouts x set clean_archived_at = now()
   where x.org_id = p_org and x.clean_archived_at is null
     and x.id in (select i.row_id from public.studio_clean_start_items i where i.org_id = p_org and i.batch_id = v_batch and i.tbl = 'layouts');
  get diagnostics n = row_count; v_out := v_out || jsonb_build_object('layouts', n);

  -- master lists -> switched off (the app's own "remove"; a staff row linked to a login stays)
  insert into public.studio_clean_start_items(org_id, batch_id, tbl, row_id, archived_by)
    select p_org, v_batch, 'inventory_items', x.id, p_actor from public.inventory_items x
     where x.org_id = p_org and not x.is_demo and x.active;
  update public.inventory_items x set active = false
   where x.org_id = p_org and x.active
     and x.id in (select i.row_id from public.studio_clean_start_items i where i.org_id = p_org and i.batch_id = v_batch and i.tbl = 'inventory_items');
  get diagnostics n = row_count; v_out := v_out || jsonb_build_object('inventory', n);

  insert into public.studio_clean_start_items(org_id, batch_id, tbl, row_id, archived_by)
    select p_org, v_batch, 'vendors', x.id, p_actor from public.vendors x
     where x.org_id = p_org and not x.is_demo and x.active;
  update public.vendors x set active = false
   where x.org_id = p_org and x.active
     and x.id in (select i.row_id from public.studio_clean_start_items i where i.org_id = p_org and i.batch_id = v_batch and i.tbl = 'vendors');
  get diagnostics n = row_count; v_out := v_out || jsonb_build_object('vendors', n);

  insert into public.studio_clean_start_items(org_id, batch_id, tbl, row_id, archived_by)
    select p_org, v_batch, 'crew_members', x.id, p_actor from public.crew_members x
     where x.org_id = p_org and not x.is_demo and x.active and x.profile_id is null;
  update public.crew_members x set active = false
   where x.org_id = p_org and x.active and x.profile_id is null
     and x.id in (select i.row_id from public.studio_clean_start_items i where i.org_id = p_org and i.batch_id = v_batch and i.tbl = 'crew_members');
  get diagnostics n = row_count; v_out := v_out || jsonb_build_object('staff', n);

  insert into public.studio_clean_start_items(org_id, batch_id, tbl, row_id, archived_by)
    select p_org, v_batch, 'venues', x.id, p_actor from public.venues x
     where x.org_id = p_org and not x.is_demo and x.active;
  update public.venues x set active = false
   where x.org_id = p_org and x.active
     and x.id in (select i.row_id from public.studio_clean_start_items i where i.org_id = p_org and i.batch_id = v_batch and i.tbl = 'venues');
  get diagnostics n = row_count; v_out := v_out || jsonb_build_object('venues', n);

  insert into public.studio_clean_start_items(org_id, batch_id, tbl, row_id, archived_by)
    select p_org, v_batch, 'menu_templates', x.id, p_actor from public.menu_templates x
     where x.org_id = p_org and not x.is_demo and x.active;
  update public.menu_templates x set active = false
   where x.org_id = p_org and x.active
     and x.id in (select i.row_id from public.studio_clean_start_items i where i.org_id = p_org and i.batch_id = v_batch and i.tbl = 'menu_templates');
  get diagnostics n = row_count; v_out := v_out || jsonb_build_object('packages', n);

  insert into public.studio_clean_start_items(org_id, batch_id, tbl, row_id, archived_by)
    select p_org, v_batch, 'dish_catalog', x.id, p_actor from public.dish_catalog x
     where x.org_id = p_org and not x.is_demo and x.active;
  update public.dish_catalog x set active = false
   where x.org_id = p_org and x.active
     and x.id in (select i.row_id from public.studio_clean_start_items i where i.org_id = p_org and i.batch_id = v_batch and i.tbl = 'dish_catalog');
  get diagnostics n = row_count; v_out := v_out || jsonb_build_object('dishes', n);

  return v_out || jsonb_build_object('batch_id', v_batch,
    'total', (select count(*) from public.studio_clean_start_items i where i.org_id = p_org and i.batch_id = v_batch));
end $$;

-- put every archived record of ONE studio back (rows the studio already changed stay as they are)
create or replace function public._tu185_restore_own(p_org uuid, p_actor uuid)
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
-- trial-upgrade-0185: undo of _tu185_archive_own; a row that would clash with a newer one is skipped
declare it record; n_ok integer := 0; n_skip integer := 0; n integer;
begin
  if p_org is null then raise exception 'no studio' using errcode = '42501'; end if;
  perform pg_advisory_xact_lock(hashtextextended('helm:clean_start:' || p_org::text, 0));
  for it in select i.id, i.tbl, i.row_id from public.studio_clean_start_items i
             where i.org_id = p_org and i.restored_at is null order by i.id loop
    begin
      n := 0;
      if it.tbl = 'quotes' then
        update public.quotes q set archived_at = null, archived_by = null, archived_reason = null, shelf_restored_at = now()
         where q.id = it.row_id and q.org_id = p_org and q.archived_at is not null and q.deleted_at is null;
      elsif it.tbl = 'leads' then
        update public.leads x set clean_archived_at = null where x.id = it.row_id and x.org_id = p_org and x.clean_archived_at is not null;
      elsif it.tbl = 'nurture' then
        update public.nurture x set clean_archived_at = null where x.id = it.row_id and x.org_id = p_org and x.clean_archived_at is not null;
      elsif it.tbl = 'layouts' then
        update public.layouts x set clean_archived_at = null where x.id = it.row_id and x.org_id = p_org and x.clean_archived_at is not null;
      elsif it.tbl = 'inventory_items' then
        update public.inventory_items x set active = true where x.id = it.row_id and x.org_id = p_org and not x.active;
      elsif it.tbl = 'vendors' then
        update public.vendors x set active = true where x.id = it.row_id and x.org_id = p_org and not x.active;
      elsif it.tbl = 'crew_members' then
        update public.crew_members x set active = true where x.id = it.row_id and x.org_id = p_org and not x.active;
      elsif it.tbl = 'venues' then
        update public.venues x set active = true where x.id = it.row_id and x.org_id = p_org and not x.active;
      elsif it.tbl = 'menu_templates' then
        update public.menu_templates x set active = true where x.id = it.row_id and x.org_id = p_org and not x.active;
      elsif it.tbl = 'dish_catalog' then
        update public.dish_catalog x set active = true where x.id = it.row_id and x.org_id = p_org and not x.active;
      end if;
      get diagnostics n = row_count;
      update public.studio_clean_start_items i set restored_at = now(), restored_by = p_actor where i.id = it.id;
      n_ok := n_ok + n;
    exception when unique_violation or check_violation then
      n_skip := n_skip + 1;          -- e.g. a newer active row with the same name: left archived
    end;
  end loop;
  return jsonb_build_object('restored', n_ok, 'skipped', n_skip);
end $$;

-- ---- 5) the studio's state for the app (read-only) ------------------------------------------------
create or replace function public.my_upgrade_status()
returns jsonb language plpgsql stable security definer set search_path = '' as $$
-- trial-upgrade-0185: own studio only; any member except a client may read it, only admins act
declare v_org uuid := public.current_org_id(); o public.organizations; v_admin boolean;
  v_sample jsonb; v_own jsonb; v_st integer; v_ot integer; v_arch integer; v_conv boolean; v_was boolean; v_trial boolean;
begin
  if auth.uid() is null or v_org is null or coalesce(public.user_role(), '') in ('', 'client') then
    raise exception 'not authorized' using errcode = '42501'; end if;
  select * into o from public.organizations x where x.id = v_org;
  v_admin := coalesce(public.is_admin(), false);
  v_trial := public._is_trial_org(v_org);
  v_conv := public._tu185_converted(v_org);
  v_was := public._tu185_was_trial(v_org);
  v_sample := jsonb_build_object(
    'events',    (select count(*) from public.quotes where org_id = v_org and is_demo),
    'leads',     (select count(*) from public.leads where org_id = v_org and is_demo),
    'staff',     (select count(*) from public.crew_members where org_id = v_org and is_demo and active),
    'vendors',   (select count(*) from public.vendors where org_id = v_org and is_demo and active),
    'inventory', (select count(*) from public.inventory_items where org_id = v_org and is_demo and active),
    'venues',    (select count(*) from public.venues where org_id = v_org and is_demo and active),
    'packages',  (select count(*) from public.menu_templates where org_id = v_org and is_demo and active),
    'dishes',    (select count(*) from public.dish_catalog where org_id = v_org and is_demo and active),
    'layouts',   (select count(*) from public.layouts where org_id = v_org and is_demo),
    'nurture',   (select count(*) from public.nurture where org_id = v_org and is_demo));
  v_own := jsonb_build_object(
    'events',    (select count(*) from public.quotes where org_id = v_org and not is_demo and archived_at is null and deleted_at is null),
    'leads',     (select count(*) from public.leads where org_id = v_org and not is_demo and clean_archived_at is null),
    'staff',     (select count(*) from public.crew_members where org_id = v_org and not is_demo and active and profile_id is null),
    'vendors',   (select count(*) from public.vendors where org_id = v_org and not is_demo and active),
    'inventory', (select count(*) from public.inventory_items where org_id = v_org and not is_demo and active),
    'venues',    (select count(*) from public.venues where org_id = v_org and not is_demo and active),
    'packages',  (select count(*) from public.menu_templates where org_id = v_org and not is_demo and active),
    'dishes',    (select count(*) from public.dish_catalog where org_id = v_org and not is_demo and active),
    'layouts',   (select count(*) from public.layouts where org_id = v_org and not is_demo and clean_archived_at is null),
    'nurture',   (select count(*) from public.nurture where org_id = v_org and not is_demo and clean_archived_at is null));
  select coalesce(sum(e.value::integer), 0) into v_st from jsonb_each_text(v_sample) e;
  select coalesce(sum(e.value::integer), 0) into v_ot from jsonb_each_text(v_own) e;
  select count(*) into v_arch from public.studio_clean_start_items i where i.org_id = v_org and i.restored_at is null;
  return jsonb_build_object(
    'is_admin', v_admin, 'in_trial', v_trial, 'converted', v_conv, 'was_trial', v_was,
    'choice', o.upgrade_choice, 'choice_at', o.upgrade_choice_at, 'legacy_choice', o.demo_choice,
    'pending', v_admin and v_conv and v_was and not coalesce(o.is_sample_master, false)
               and o.upgrade_choice is null and o.demo_choice is null and (v_st + v_ot) > 0,
    'has_sample', v_st > 0, 'sample', v_sample, 'sample_total', v_st,
    'own', v_own, 'own_total', v_ot,
    'archived', v_arch, 'can_restore', v_admin and v_arch > 0 and v_conv,
    'confirm_phrase', 'START CLEAN');
end $$;

-- ---- 6) the choice (admin, own studio, once, after upgrading) -----------------------------------
create or replace function public.upgrade_data_choice(p_choice text, p_confirm text default null)
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
-- trial-upgrade-0185: keep | remove_sample (is_demo rows only) | clean (sample removed, own records ARCHIVED)
declare v_org uuid := public.current_org_id(); v_uid uuid := auth.uid();
  v_choice text := lower(btrim(coalesce(p_choice, ''))); o public.organizations;
  v_adopt integer := 0; r_clear jsonb := null; r_arch jsonb := null;
begin
  if v_uid is null or v_org is null or not coalesce(public.is_admin(), false) then
    raise exception 'not authorized' using errcode = '42501'; end if;
  if v_choice not in ('keep', 'remove_sample', 'clean') then
    raise exception 'Choose keep, remove_sample or clean.' using errcode = '22023', hint = 'upgrade_choice'; end if;
  perform pg_advisory_xact_lock(hashtextextended('helm:upgrade_choice:' || v_org::text, 0));
  select * into o from public.organizations x where x.id = v_org for update;
  if o.id is null or o.is_sample_master then raise exception 'not authorized' using errcode = '42501'; end if;
  if not public._tu185_was_trial(v_org) then
    raise exception 'Only a studio that started as a free trial makes this choice.' using errcode = '22023', hint = 'upgrade_not_trial'; end if;
  if not public._tu185_converted(v_org) then
    raise exception 'Choose a plan first - you decide about the sample data once the plan is active.'
      using errcode = '22023', hint = 'upgrade_not_converted'; end if;
  if o.upgrade_choice is not null then          -- once: a second click / tab changes nothing
    return jsonb_build_object('result', 'already', 'choice', o.upgrade_choice, 'at', o.upgrade_choice_at); end if;
  if v_choice = 'clean' and upper(btrim(coalesce(p_confirm, ''))) <> 'START CLEAN' then
    raise exception 'Type START CLEAN to confirm starting completely clean.' using errcode = '22023', hint = 'upgrade_confirm'; end if;

  if v_choice in ('remove_sample', 'clean') then
    v_adopt := public._tu185_adopt_used_samples(v_org);   -- a sample event you really used is kept as yours
    r_clear := public._demo_clear(v_org);                  -- ONLY this studio's is_demo rows
  end if;
  if v_choice = 'clean' then
    r_arch := public._tu185_archive_own(v_org, v_uid);     -- own records: archived, never deleted
  end if;

  update public.organizations x set upgrade_choice = v_choice, upgrade_choice_at = now(), upgrade_choice_by = v_uid,
         demo_choice = coalesce(x.demo_choice, case when v_choice = 'keep' then 'keep' else 'fresh' end),
         demo_choice_at = coalesce(x.demo_choice_at, now()),
         trial_mode = case when v_choice = 'keep' then x.trial_mode else 'own' end
   where x.id = v_org;
  insert into public.audit_log(actor, actor_email, action, entity, entity_id, changed, org_id, at)
    select v_uid, (select u.email from auth.users u where u.id = v_uid), 'trial.upgrade_choice',
           'organizations', v_org::text,
           jsonb_build_object('choice', v_choice, 'adopted', v_adopt, 'cleared', r_clear, 'archived', r_arch - 'batch_id'),
           v_org, now();
  return jsonb_build_object('result', 'ok', 'choice', v_choice, 'kept_in_use', v_adopt,
                            'cleared', r_clear, 'archived', r_arch);
end $$;

-- ---- 7) Control Center: "Delete all sample data" (is_demo rows only) -----------------------------
create or replace function public.delete_all_sample_data()
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
-- trial-upgrade-0185: admin, own studio, ONLY is_demo rows (_demo_clear); own records never touched
declare v_org uuid := public.current_org_id(); v_uid uuid := auth.uid(); o public.organizations;
  v_adopt integer := 0; r jsonb;
begin
  if v_uid is null or v_org is null or not coalesce(public.is_admin(), false) then
    raise exception 'not authorized' using errcode = '42501'; end if;
  select * into o from public.organizations x where x.id = v_org for update;
  if o.id is null or o.is_sample_master then raise exception 'not authorized' using errcode = '42501'; end if;
  -- after upgrading, a sample event with your own payments / approval / files is kept as yours
  if not public._is_trial_org(v_org) then v_adopt := public._tu185_adopt_used_samples(v_org); end if;
  r := public._demo_clear(v_org);
  update public.organizations x set trial_mode = 'own' where x.id = v_org and x.trial_mode = 'demo';
  insert into public.audit_log(actor, actor_email, action, entity, entity_id, changed, org_id, at)
    select v_uid, (select u.email from auth.users u where u.id = v_uid), 'sample.deleted_all',
           'organizations', v_org::text, jsonb_build_object('cleared', r, 'adopted', v_adopt), v_org, now();
  return jsonb_build_object('result', 'ok', 'cleared', r, 'kept_in_use', v_adopt);
end $$;

-- ---- 8) restore everything "start completely clean" archived (admin, own studio) -----------------
create or replace function public.restore_clean_start()
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
-- trial-upgrade-0185
declare v_org uuid := public.current_org_id(); v_uid uuid := auth.uid(); r jsonb;
begin
  if v_uid is null or v_org is null or not coalesce(public.is_admin(), false) then
    raise exception 'not authorized' using errcode = '42501'; end if;
  if exists (select 1 from public.organizations o where o.id = v_org and o.is_sample_master) then
    raise exception 'not authorized' using errcode = '42501'; end if;
  if not exists (select 1 from public.studio_clean_start_items i where i.org_id = v_org and i.restored_at is null) then
    return jsonb_build_object('result', 'nothing', 'restored', 0, 'skipped', 0); end if;
  r := public._tu185_restore_own(v_org, v_uid);
  insert into public.audit_log(actor, actor_email, action, entity, entity_id, changed, org_id, at)
    select v_uid, (select u.email from auth.users u where u.id = v_uid), 'trial.clean_start_restored',
           'organizations', v_org::text, r, v_org, now();
  return jsonb_build_object('result', 'ok') || r;
end $$;

-- ---- 9) privileges ---------------------------------------------------------------------------------
do $$
declare f text;
begin
  foreach f in array array['public._tu185_tg_choice_guard()', 'public._tu185_converted(uuid)', 'public._tu185_was_trial(uuid)',
                           'public._tu185_adopt_used_samples(uuid)', 'public._tu185_archive_own(uuid, uuid)',
                           'public._tu185_restore_own(uuid, uuid)',
                           'public.my_upgrade_status()', 'public.upgrade_data_choice(text, text)',
                           'public.delete_all_sample_data()', 'public.restore_clean_start()'] loop
    execute format('revoke all on function %s from public', f);
    if exists (select 1 from pg_roles where rolname = 'anon') then execute format('revoke all on function %s from anon', f); end if;
  end loop;
  foreach f in array array['public._tu185_tg_choice_guard()', 'public._tu185_converted(uuid)', 'public._tu185_was_trial(uuid)',
                           'public._tu185_adopt_used_samples(uuid)', 'public._tu185_archive_own(uuid, uuid)',
                           'public._tu185_restore_own(uuid, uuid)'] loop
    if exists (select 1 from pg_roles where rolname = 'authenticated') then execute format('revoke all on function %s from authenticated', f); end if;
  end loop;
  foreach f in array array['public.my_upgrade_status()', 'public.upgrade_data_choice(text, text)',
                           'public.delete_all_sample_data()', 'public.restore_clean_start()'] loop
    if exists (select 1 from pg_roles where rolname = 'authenticated') then execute format('grant execute on function %s to authenticated', f); end if;
    if exists (select 1 from pg_roles where rolname = 'service_role') then execute format('grant execute on function %s to service_role', f); end if;
  end loop;
end $$;

-- ---- 10) checkout during the free trial: billing details + Terms stay open -------------------------
-- 0173 put the free-trial guard on my_studio_account_update, so a trial admin could not save the
-- billing details / accept the Terms that checkout saves BEFORE payment - an upgrade was refused
-- while the subscription still said 'trial' (the whole trial, and up to a day after it ended).
-- The 0173 wrapper keeps its name, signature and grants; it now calls the original directly
-- (admin / users-edit check, field validation, audit row unchanged). It writes only the studio's
-- studio_account row + consent log, as before. Every other 0173 guard stays. Paid studios: unchanged
-- (the guard never applied to them). Runs only when 0173 is installed; a re-run of 0173 puts the
-- guard back, so this file (or the bundle) must be pasted after it.
do $$ begin
  if to_regprocedure('public.my_studio_account_update__pre0173(jsonb)') is not null
     and to_regprocedure('public.my_studio_account_update(jsonb)') is not null then
    create or replace function public.my_studio_account_update(p_account jsonb)
    returns jsonb language plpgsql volatile security definer set search_path = '' as $f$
    -- trial-lockdown-0173 + trial-upgrade-0185: no free-trial guard (checkout needs billing details + Terms to upgrade)
    begin
      return public.my_studio_account_update__pre0173(p_account);
    end $f$;
  end if;
end $$;
commit;

-- VERIFY (every row should say ok = true)
select item, ok from (values
  ('01 columns added (choice on studio, archive flag on leads / nurture / layouts)',
      (select count(*) from information_schema.columns where table_schema = 'public' and table_name = 'organizations'
        and column_name in ('upgrade_choice', 'upgrade_choice_at', 'upgrade_choice_by')) = 3
      and (select count(*) from information_schema.columns where table_schema = 'public' and column_name = 'clean_archived_at'
        and table_name in ('leads', 'nurture', 'layouts')) = 3),
  ('02 choice check + API guard trigger',
      exists (select 1 from pg_constraint where conrelid = 'public.organizations'::regclass and conname = 'organizations_upgrade_choice_chk185')
      and exists (select 1 from pg_trigger where tgrelid = 'public.organizations'::regclass and tgname = 'zz_tu185_choice_guard' and tgenabled <> 'D')),
  ('03 restrictive archive policy on the 3 tables',
      (select count(*) from pg_policies where schemaname = 'public' and policyname = 'helm_clean_archive_185'
        and permissive = 'RESTRICTIVE' and tablename in ('leads', 'nurture', 'layouts')) = 3),
  ('04 journal table: RLS on, no app access, read-only guard',
      (select relrowsecurity from pg_class where oid = 'public.studio_clean_start_items'::regclass)
      and exists (select 1 from pg_trigger where tgrelid = 'public.studio_clean_start_items'::regclass and tgname = 'zzz_studio_read_only')
      and not has_table_privilege('anon', 'public.studio_clean_start_items', 'select')
      and not has_table_privilege('authenticated', 'public.studio_clean_start_items', 'select')),
  ('05 app RPCs: signed-in only',
      has_function_privilege('authenticated', 'public.my_upgrade_status()', 'execute')
      and has_function_privilege('authenticated', 'public.upgrade_data_choice(text, text)', 'execute')
      and has_function_privilege('authenticated', 'public.delete_all_sample_data()', 'execute')
      and has_function_privilege('authenticated', 'public.restore_clean_start()', 'execute')
      and not has_function_privilege('anon', 'public.upgrade_data_choice(text, text)', 'execute')
      and not has_function_privilege('anon', 'public.delete_all_sample_data()', 'execute')
      and not has_function_privilege('anon', 'public.restore_clean_start()', 'execute')
      and not has_function_privilege('anon', 'public.my_upgrade_status()', 'execute')),
  ('06 internal helpers: not callable by the app',
      not has_function_privilege('authenticated', 'public._tu185_archive_own(uuid, uuid)', 'execute')
      and not has_function_privilege('authenticated', 'public._tu185_restore_own(uuid, uuid)', 'execute')
      and not has_function_privilege('authenticated', 'public._tu185_adopt_used_samples(uuid)', 'execute')
      and not has_function_privilege('anon', 'public._tu185_archive_own(uuid, uuid)', 'execute')),
  ('07 no studio still in its trial counts as upgraded',
      not exists (select 1 from public.studio_subscriptions s where s.status = 'trial' and public._tu185_converted(s.org_id))),
  ('08 every hidden (archived) row is in the restore journal',
      not exists (select 1 from public.leads x where x.clean_archived_at is not null and not exists (select 1 from public.studio_clean_start_items i
                   where i.tbl = 'leads' and i.row_id = x.id and i.restored_at is null))
      and not exists (select 1 from public.nurture x where x.clean_archived_at is not null and not exists (select 1 from public.studio_clean_start_items i
                   where i.tbl = 'nurture' and i.row_id = x.id and i.restored_at is null))
      and not exists (select 1 from public.layouts x where x.clean_archived_at is not null and not exists (select 1 from public.studio_clean_start_items i
                   where i.tbl = 'layouts' and i.row_id = x.id and i.restored_at is null))),
  ('09 the clear used is the is_demo-only _demo_clear', position('_demo_clear' in pg_get_functiondef('public.delete_all_sample_data()'::regprocedure)) > 0
      and position('_demo_clear' in pg_get_functiondef('public.upgrade_data_choice(text, text)'::regprocedure)) > 0),
  ('10 checkout: billing details + Terms can be saved in the free trial (0173 wrapper without the trial guard)',
      to_regprocedure('public.my_studio_account_update__pre0173(jsonb)') is null
      or (position('trial-upgrade-0185' in pg_get_functiondef('public.my_studio_account_update(jsonb)'::regprocedure)) > 0
          and position('_tl173_guard' in pg_get_functiondef('public.my_studio_account_update(jsonb)'::regprocedure)) = 0
          and has_function_privilege('authenticated', 'public.my_studio_account_update(jsonb)', 'execute')
          and not has_function_privilege('anon', 'public.my_studio_account_update(jsonb)', 'execute')
          and not has_function_privilege('authenticated', 'public.my_studio_account_update__pre0173(jsonb)', 'execute')))
) v(item, ok) order by item;

-- ##########################################################################################
-- RELEASE SECTION 13/28: APPLY-0186.sql
-- In plain words: One free trial per studio / e-mail; one trial extension that only Helm HQ can grant.
-- ##########################################################################################
-- APPLY-0186.sql - paste into the Supabase SQL editor (staging first, then production).
-- Owner post-trial policy 7 + 8: ONE free trial per studio / e-mail, and ONE trial extension
-- (1 to 7 days, reason required) that only Helm HQ can grant from the HQ studio page.
-- Run it AFTER every other pending trial file (0173-0185): it wraps start_self_serve_trial,
-- my_pending_start_trial and my_start_trial, so it must be the last one to touch them.
-- What it touches: 2 NEW private tables (trial_grants, trial_extensions; RLS on, no access for the app),
-- 1 trigger on studio_subscriptions, new functions, 3 functions wrapped (old bodies kept as *__pre0186).
-- The only rows written: the new trial_grants ledger is filled once from studios that already had a
-- trial (insert only). No existing row is updated or deleted. No DROP / DELETE / TRUNCATE.
-- Safe to run twice. No edge function needs a redeploy.
begin;
-- 0186_trial_one_per_email_extension.sql - CANONICAL forward-only.
-- REQUIRES 0029 + 0037 + 0047 (Helm HQ: is_platform_admin, _hq_gate, _hq_wgate), 0045 (studio_subscriptions,
--          subscription_payments), 0056 (my_start_trial, trial_source), 0058 (_trial_paid),
--          0116 + 0119 (start_self_serve_trial, _trial_locked), 0159 (my_pending_start_trial),
--          0166 (_is_trial_org, organizations.is_sample_master).
--
-- In plain words (owner post-trial policy items 7 + 8, docs/trial/POST-TRIAL-POLICY.md):
--   7. ONE free trial per studio and per e-mail.
--      * New private ledger public.trial_grants: one row per studio that ever started a trial
--        (studio id, the studio creator's user id, a one-way SHA-256 fingerprint of the creator's
--        e-mail - never the e-mail itself). A trigger writes the row whenever a studio's
--        subscription becomes 'trial'; the studios that already had a trial are filled in once here.
--        The ledger is not linked to the studio row on purpose: it stays if a studio or an account
--        is removed later, so the same e-mail cannot start over.
--      * The fingerprint ignores upper/lower case, spaces, a "+tag" (name+x@...) and, for Gmail,
--        dots in the name.
--      * start_self_serve_trial(), my_pending_start_trial() and my_start_trial() refuse a NEW free
--        trial when this user or this e-mail already had one (friendly message, SQLSTATE 22023,
--        hint 'trial_used'). Someone already in a studio is handed it back unchanged as before.
--        Studios that already have a subscription (paid or trial) go straight to the old code.
--   8. ONE trial extension per studio: 1 to 7 days, only a Helm HQ operator (platform admin; a
--      two-step session whenever HQ requires it) can grant it, a reason is required.
--      * New private table public.trial_extensions (primary key = studio: at most one, ever).
--      * hq_extend_trial(studio, days, reason): the studio must be on its free trial, or its free
--        trial ended unpaid (lapsed to past due / cancelled with no paid period, never paid, no
--        online checkout). The new end is
--        max(old end, now) + days, written to organizations.trial_ends_at (when set) and the
--        subscription; the status goes back to 'trial', so the read-only lock lifts. Audit rows:
--        'hq.trial.extend' (HQ log, with the reason) and 'subscription.trial_extended' (studio log).
--      * hq_trial_info(studio): what the HQ studio page shows (trial state, extension, can extend).
-- ZERO DATA LOSS / paid studios unaffected: additive + idempotent. Two new private tables (RLS on,
-- no grants, no policies), one trigger, new functions; three functions are wrapped with the same
-- signature and grants (the previous bodies are kept as *__pre0186, not callable by app roles).
-- The one-time fill only INSERTS into the new ledger (on conflict do nothing); no existing row is
-- updated or deleted. No DROP of data, DELETE or TRUNCATE. Safe to run twice.
-- ============================================================================

do $$ begin
  if to_regprocedure('public.start_self_serve_trial(text,text,text,text)') is null then
    raise exception '0186: start_self_serve_trial (0119) is missing'; end if;
  if to_regprocedure('public.my_pending_start_trial()') is null then
    raise exception '0186: my_pending_start_trial (0159) is missing'; end if;
  if to_regprocedure('public.my_start_trial(text,text)') is null then
    raise exception '0186: my_start_trial (0056 / 0119) is missing'; end if;
  if to_regprocedure('public._hq_wgate(text,text,text,jsonb)') is null or to_regprocedure('public._hq_gate(text,text)') is null then
    raise exception '0186: Helm HQ (0029 / 0045 / 0047) is missing'; end if;
  if to_regprocedure('public._is_trial_org(uuid)') is null or to_regprocedure('public._trial_locked(uuid)') is null then
    raise exception '0186: apply 0116 + 0166 (trial helpers) first'; end if;
  if not exists (select 1 from information_schema.columns where table_schema = 'public'
                   and table_name = 'studio_subscriptions' and column_name = 'trial_source') then
    raise exception '0186: studio_subscriptions.trial_source (0056) is missing'; end if;
  if not exists (select 1 from information_schema.columns where table_schema = 'public'
                   and table_name = 'organizations' and column_name = 'is_sample_master') then
    raise exception '0186: organizations.is_sample_master (0166) is missing'; end if;
end $$;

-- ---- 1) private tables ---------------------------------------------------------------------
create table if not exists public.trial_grants (
  id           uuid primary key default gen_random_uuid(),
  org_id       uuid not null,
  user_id      uuid,
  email_hash   text check (email_hash is null or email_hash ~ '^[0-9a-f]{64}$'),
  source       text check (source is null or char_length(source) <= 40),
  started_at   timestamptz not null default now(),
  recorded_how text not null default 'trigger' check (recorded_how in ('trigger', 'backfill'))
);
create unique index if not exists trial_grants_org_uq on public.trial_grants(org_id);
create index if not exists trial_grants_user_idx on public.trial_grants(user_id) where user_id is not null;
create index if not exists trial_grants_email_idx on public.trial_grants(email_hash) where email_hash is not null;
alter table public.trial_grants enable row level security;
revoke all on table public.trial_grants from public, anon, authenticated;

create table if not exists public.trial_extensions (
  org_id           uuid primary key,
  days             integer not null check (days between 1 and 7),
  reason           text not null check (char_length(btrim(reason)) between 5 and 500),
  previous_status  text,
  previous_ends_at timestamptz,
  new_ends_at      timestamptz not null,
  granted_by       uuid,
  granted_by_email text,
  granted_at       timestamptz not null default now()
);
alter table public.trial_extensions enable row level security;
revoke all on table public.trial_extensions from public, anon, authenticated;
-- (no policies on purpose: only the SECURITY DEFINER functions below read or write these tables)

-- ---- 2) helpers ----------------------------------------------------------------------------
-- one-way e-mail fingerprint: lower case, trimmed, "+tag" dropped, Gmail dots dropped
create or replace function public._trial_email_fingerprint(p_email text)
returns text language plpgsql immutable set search_path = '' as $$
-- one-trial-0186
declare e text := lower(btrim(coalesce(p_email, ''))); v_local text; v_domain text;
begin
  if e !~ '^[^@[:space:]]+@[^@[:space:]]+$' then return null; end if;
  v_local := split_part(e, '@', 1); v_domain := split_part(e, '@', 2);
  if position('+' in v_local) > 1 then v_local := split_part(v_local, '+', 1); end if;
  if v_domain in ('gmail.com', 'googlemail.com') then
    v_local := replace(v_local, '.', ''); v_domain := 'gmail.com';
  end if;
  if v_local = '' then return null; end if;
  return encode(sha256(convert_to(v_local || '@' || v_domain, 'UTF8')), 'hex');
end $$;
revoke all on function public._trial_email_fingerprint(text) from public, anon, authenticated;

-- has this user / this e-mail had a free trial (in a studio other than p_except_org)?
create or replace function public._trial_used(p_uid uuid, p_email text, p_except_org uuid default null)
returns boolean language sql stable security definer set search_path = '' as $$
  -- one-trial-0186
  select exists (select 1 from public.trial_grants g
                  where (p_except_org is null or g.org_id <> p_except_org)
                    and ((p_uid is not null and g.user_id = p_uid)
                      or (g.email_hash is not null and g.email_hash = public._trial_email_fingerprint(p_email))));
$$;
revoke all on function public._trial_used(uuid, text, uuid) from public, anon, authenticated;

-- ledger row the moment a studio's subscription becomes 'trial' (every path: self-serve trial,
-- payment-pending trial, checkout, HQ). Never blocks the subscription change.
create or replace function public.tg_trial_grant_0186()
returns trigger language plpgsql security definer set search_path = '' as $$
-- one-trial-0186
declare v_uid uuid; v_email text; v_master boolean;
begin
  if new.status is distinct from 'trial' then return null; end if;
  if tg_op = 'UPDATE' and old.status is not distinct from 'trial' then return null; end if;
  begin
    select o.created_by, coalesce(o.is_sample_master, false) into v_uid, v_master
      from public.organizations o where o.id = new.org_id;
    if not found or v_master then return null; end if;
    if v_uid is not null then select u.email into v_email from auth.users u where u.id = v_uid; end if;
    insert into public.trial_grants(org_id, user_id, email_hash, source, started_at, recorded_how)
      values (new.org_id, v_uid, public._trial_email_fingerprint(v_email),
              left(coalesce(new.trial_source, 'trial'), 40), now(), 'trigger')
    on conflict (org_id) do nothing;
  exception when others then null;
  end;
  return null;
end $$;
revoke all on function public.tg_trial_grant_0186() from public, anon, authenticated;
drop trigger if exists zz_trial_grant_0186 on public.studio_subscriptions;
create trigger zz_trial_grant_0186 after insert or update of status on public.studio_subscriptions
  for each row execute function public.tg_trial_grant_0186();

-- ---- 3) one-time fill: studios that already had a trial (insert only, new table) -------------
insert into public.trial_grants(org_id, user_id, email_hash, source, started_at, recorded_how)
select o.id, coalesce(o.created_by, a.actor), public._trial_email_fingerprint(u.email),
       left(coalesce(s.trial_source, case when o.trial_mode is not null then 'self_serve' else 'trial' end), 40),
       coalesce(a.at, o.created_at, now()), 'backfill'
  from public.organizations o
  left join public.studio_subscriptions s on s.org_id = o.id
  left join lateral (select x.actor, x.at from public.audit_log x
                      where x.org_id = o.id and x.action = 'subscription.trial_started'
                      order by x.at limit 1) a on true
  left join auth.users u on u.id = coalesce(o.created_by, a.actor)
 where not coalesce(o.is_sample_master, false)
   and (s.status = 'trial' or s.trial_source is not null
        or (o.trial_mode is not null and o.trial_ends_at is not null)
        or a.at is not null)
on conflict (org_id) do nothing;

-- ---- 4) one free trial per e-mail: the three entry points --------------------------------------
do $$ begin
  if to_regprocedure('public.start_self_serve_trial__pre0186(text,text,text,text)') is null then
    alter function public.start_self_serve_trial(text, text, text, text) rename to start_self_serve_trial__pre0186;
  end if;
  if to_regprocedure('public.my_pending_start_trial__pre0186()') is null then
    alter function public.my_pending_start_trial() rename to my_pending_start_trial__pre0186;
  end if;
  if to_regprocedure('public.my_start_trial__pre0186(text,text)') is null then
    alter function public.my_start_trial(text, text) rename to my_start_trial__pre0186;
  end if;
end $$;
revoke all on function public.start_self_serve_trial__pre0186(text, text, text, text) from public, anon, authenticated;
revoke all on function public.my_pending_start_trial__pre0186() from public, anon, authenticated;
revoke all on function public.my_start_trial__pre0186(text, text) from public, anon, authenticated;

create or replace function public.start_self_serve_trial(p_name text, p_timezone text, p_currency text, p_mode text)
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
-- one-trial-0186: a person who already had a free trial (this user or this e-mail) gets no second one
declare v_uid uuid := auth.uid(); v_email text; v_key text;
begin
  if v_uid is not null
     and not exists (select 1 from public.profiles p where p.id = v_uid and p.org_id is not null)
     and not coalesce(public.is_platform_admin(), false) then
    select u.email into v_email from auth.users u where u.id = v_uid;
    v_key := coalesce(public._trial_email_fingerprint(v_email), v_uid::text);
    perform pg_advisory_xact_lock(hashtextextended('helm:one_trial:' || v_key, 0));
    if public._trial_used(v_uid, v_email) then
      raise exception 'You have already used your free Helm trial with this email. Create your studio with a plan to continue, or contact Helm support if you need more time.'
        using errcode = '22023', hint = 'trial_used';
    end if;
  end if;
  return public.start_self_serve_trial__pre0186(p_name, p_timezone, p_currency, p_mode);
end $$;
revoke all on function public.start_self_serve_trial(text, text, text, text) from public, anon;
grant execute on function public.start_self_serve_trial(text, text, text, text) to authenticated, service_role;

-- the caller and the studio's creator: has either had a free trial in another studio?
create or replace function public._trial_used_for_org(p_org uuid)
returns boolean language plpgsql stable security definer set search_path = '' as $$
-- one-trial-0186
declare v_uid uuid := auth.uid(); v_creator uuid;
begin
  if p_org is null then return false; end if;
  select o.created_by into v_creator from public.organizations o where o.id = p_org;
  return (v_uid is not null and public._trial_used(v_uid, (select u.email from auth.users u where u.id = v_uid), p_org))
      or (v_creator is not null and public._trial_used(v_creator, (select u.email from auth.users u where u.id = v_creator), p_org));
end $$;
revoke all on function public._trial_used_for_org(uuid) from public, anon, authenticated;

create or replace function public.my_pending_start_trial()
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
-- one-trial-0186: no free trial for a studio whose owner already had one elsewhere
declare v_org uuid := public.current_org_id();
begin
  if auth.uid() is not null and v_org is not null and coalesce(public.is_admin(), false)
     and not exists (select 1 from public.studio_subscriptions s where s.org_id = v_org)
     and public._trial_used_for_org(v_org) then
    raise exception 'You have already used your free Helm trial. Choose a plan and complete payment to continue, or contact Helm support.'
      using errcode = '22023', hint = 'trial_used';
  end if;
  return public.my_pending_start_trial__pre0186();
end $$;
revoke all on function public.my_pending_start_trial() from public, anon;
grant execute on function public.my_pending_start_trial() to authenticated;

create or replace function public.my_start_trial(p_source text default 'bypass', p_plan text default null)
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
-- one-trial-0186: no free trial for a studio whose owner already had one elsewhere
declare v_org uuid := public.current_org_id();
begin
  if auth.uid() is not null and v_org is not null and coalesce(public.is_admin(), false)
     and not exists (select 1 from public.studio_subscriptions s where s.org_id = v_org)
     and public._trial_used_for_org(v_org) then
    raise exception 'You have already used your free Helm trial. Choose a plan and complete payment to continue, or contact Helm support.'
      using errcode = '22023', hint = 'trial_used';
  end if;
  return public.my_start_trial__pre0186(p_source, p_plan);
end $$;
revoke all on function public.my_start_trial(text, text) from public, anon;
grant execute on function public.my_start_trial(text, text) to authenticated;

-- ---- 5) trial extension (HQ only) ------------------------------------------------------------
-- null = this studio can get its one extension; otherwise the reason it cannot (for people)
create or replace function public._trial_extend_block(p_org uuid)
returns text language plpgsql stable security definer set search_path = '' as $$
-- one-trial-0186
declare o public.organizations; s public.studio_subscriptions;
begin
  select * into o from public.organizations x where x.id = p_org;
  if o.id is null then return 'Unknown studio.'; end if;
  if coalesce(o.is_sample_master, false) then return 'The sample studio has no trial.'; end if;
  if exists (select 1 from public.trial_extensions e where e.org_id = p_org) then
    return 'This studio already had its one trial extension.'; end if;
  select * into s from public.studio_subscriptions x where x.org_id = p_org;
  if s.org_id is null then return 'This studio is not on a free trial.'; end if;
  if s.status = 'suspended' then return 'This studio is suspended. Reactivate it first.'; end if;
  if coalesce(s.trial_source, '') = 'checkout' or s.provider_subscription_id is not null then
    return 'This studio pays through online checkout. Its trial cannot be extended here.'; end if;
  if public._is_trial_org(p_org) then return null; end if;
  if s.status in ('past_due', 'cancelled') and s.current_period_end is null and s.trial_ends_at is not null
     and not exists (select 1 from public.subscription_payments sp where sp.org_id = p_org and sp.voided_at is null) then
    return null;                                                    -- free trial ended (lapsed), never paid
  end if;
  return 'Only a studio on its free trial (or whose free trial ended unpaid) can be extended.';
end $$;
revoke all on function public._trial_extend_block(uuid) from public, anon, authenticated;

create or replace function public.hq_extend_trial(p_org uuid, p_days integer, p_reason text)
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
-- one-trial-0186: one extension per studio, 1 to 7 days, reason required, Helm HQ only
declare
  v_reason text := btrim(regexp_replace(coalesce(p_reason, ''), '[[:space:]]+', ' ', 'g'));
  o public.organizations; s public.studio_subscriptions; v_block text; v_n integer;
  v_old timestamptz; v_new timestamptz; v_new_date date;
begin
  perform public._hq_wgate('hq.trial.extend', 'organizations', p_org::text,
    jsonb_build_object('days', p_days, 'reason', left(v_reason, 500)));
  if p_org is null then raise exception 'Unknown studio.' using errcode = '22023'; end if;
  if p_days is null or p_days < 1 or p_days > 7 then
    raise exception 'An extension is 1 to 7 days.' using errcode = '22023'; end if;
  if char_length(v_reason) < 5 then
    raise exception 'Write the reason for the extension (at least 5 characters).' using errcode = '22023'; end if;
  if char_length(v_reason) > 500 then
    raise exception 'The reason can be up to 500 characters.' using errcode = '22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended('helm:trial_extend:' || p_org::text, 0));
  select * into s from public.studio_subscriptions x where x.org_id = p_org for update;
  v_block := public._trial_extend_block(p_org);
  if v_block is not null then raise exception '%', v_block using errcode = '22023', hint = 'trial_extend_refused'; end if;
  select * into o from public.organizations x where x.id = p_org for update;

  if o.trial_ends_at is not null then
    v_old := o.trial_ends_at;
    v_new := greatest(o.trial_ends_at, now()) + make_interval(days => p_days);
    v_new_date := (v_new at time zone 'UTC')::date;
  else
    v_old := (s.trial_ends_at::timestamp at time zone 'UTC');
    v_new_date := greatest(s.trial_ends_at, current_date) + p_days;
    v_new := (v_new_date::timestamp at time zone 'UTC');
  end if;

  insert into public.trial_extensions(org_id, days, reason, previous_status, previous_ends_at, new_ends_at,
                                      granted_by, granted_by_email, granted_at)
    select p_org, p_days, v_reason, s.status, v_old, v_new, auth.uid(), u.email, now()
      from (select 1) one left join auth.users u on u.id = auth.uid()
  on conflict (org_id) do nothing;
  get diagnostics v_n = row_count;
  if v_n = 0 then
    raise exception 'This studio already had its one trial extension.' using errcode = '22023', hint = 'trial_extend_refused'; end if;

  update public.studio_subscriptions
     set status = 'trial', trial_ends_at = v_new_date, updated_at = now(), updated_by = auth.uid()
   where org_id = p_org;
  if o.trial_ends_at is not null then
    update public.organizations set trial_ends_at = v_new where id = p_org;
  end if;

  insert into public.audit_log(actor, actor_email, action, entity, entity_id, changed, org_id, at)
    values (null, 'Helm', 'subscription.trial_extended', 'organizations', p_org::text,
            jsonb_build_object('days', p_days, 'previous_ends_at', v_old, 'new_ends_at', v_new,
                               'previous_status', s.status, 'by', 'Helm'), p_org, now());
  return jsonb_build_object('org_id', p_org, 'days', p_days, 'status', 'trial',
                            'previous_ends_at', v_old, 'new_ends_at', v_new, 'trial_ends_on', v_new_date);
end $$;
revoke all on function public.hq_extend_trial(uuid, integer, text) from public, anon;
grant execute on function public.hq_extend_trial(uuid, integer, text) to authenticated;

create or replace function public.hq_trial_info(p_org uuid)
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
-- one-trial-0186: trial state + the one extension, for the HQ studio page
declare o public.organizations; s public.studio_subscriptions; e public.trial_extensions; v_block text;
begin
  perform public._hq_gate('hq_trial_info', p_org::text);
  select * into o from public.organizations x where x.id = p_org;
  if o.id is null then raise exception 'Unknown studio.' using errcode = '22023'; end if;
  select * into s from public.studio_subscriptions x where x.org_id = p_org;
  select * into e from public.trial_extensions x where x.org_id = p_org;
  v_block := public._trial_extend_block(p_org);
  return jsonb_build_object(
    'org_id', p_org, 'status', s.status, 'trial_source', s.trial_source,
    'is_trial', public._is_trial_org(p_org), 'trial_mode', o.trial_mode,
    'trial_ends_at', coalesce(o.trial_ends_at, (s.trial_ends_at::timestamp at time zone 'UTC')),
    'locked', public._trial_locked(p_org),
    'had_trial', exists (select 1 from public.trial_grants g where g.org_id = p_org),
    'can_extend', v_block is null, 'why_not', v_block, 'max_days', 7,
    'extension', case when e.org_id is null then null else jsonb_build_object(
      'days', e.days, 'reason', e.reason, 'previous_status', e.previous_status,
      'previous_ends_at', e.previous_ends_at, 'new_ends_at', e.new_ends_at,
      'granted_at', e.granted_at, 'granted_by_email', e.granted_by_email) end);
end $$;
revoke all on function public.hq_trial_info(uuid) from public, anon;
grant execute on function public.hq_trial_info(uuid) to authenticated;

notify pgrst, 'reload schema';
commit;

