-- ##########################################################################################
-- RELEASE SECTION 14/28: APPLY-0187.sql
-- In plain words: Ended trials queue no payment reminders; no real Razorpay link from a trial studio.
-- ##########################################################################################
-- APPLY-0187.sql - paste into the Supabase SQL editor (staging first, then production).
-- Trial bundle final review: an ended, unpaid free trial (read-only) no longer queues automatic payment
-- reminders / client follow-ups (they are stored as 'skipped'), and no studio on its free trial (or an
-- ended unpaid one) can get a real Razorpay payment link for a client (Razorpay would text + e-mail it).
-- Run it AFTER APPLY-0179 and APPLY-0183 (the trial bundle runs it in order).
-- What it touches: _sample_outbound_blocked re-issued (same signature + grants), payment_link_begin
-- wrapped (old body kept as payment_link_begin__pre0187, service role only). No table or column is
-- created, changed or dropped; nothing is deleted. The only rows written: client messages an ended,
-- never-paid trial already has waiting (comms_outbox / pkg_outbox 'pending') are set to 'skipped' once.
-- Paid studios unchanged. Safe to run twice.
-- Edge function create-payment-link should be redeployed too (it then shows a clear message); the
-- database refuses the link either way.
begin;
-- 0187_trial_outbound_gaps.sql - CANONICAL forward-only. REQUIRES 0027 + 0097 (payment_link_begin),
-- 0166 (_sample_outbound_blocked, outbox skip triggers), 0179 (_tb179_no_send), 0183 (_trial_locked,
-- status-based).
--
-- In plain words (trial bundle final review): two ways a free-trial studio could still reach a REAL client.
--   1) QUEUED MESSAGES AFTER THE TRIAL ENDED. The 0166 outbox guard (comms_outbox / pkg_outbox /
--      assign_notify_outbox rows stored as 'skipped') asked only "is the subscription 'trial'?". The
--      billing tick moves an ended, unpaid trial to 'past_due', so from then on the automatic payment
--      reminders and client follow-ups that comms_tick (pg_cron) queues for that studio's own events were
--      stored as 'pending' and comms-dispatch would send them. _sample_outbound_blocked now also says
--      "blocked" for an ended, never-paid trial that is read-only (_trial_locked, 0183: status-based,
--      never trial_ends_at alone) - the same rule 0179 already uses for the direct send routes. This
--      part does not depend on the helm_sample_template.block_trial_outbound switch. Client messages
--      such a studio ALREADY has waiting ('pending', never sent) in comms_outbox / pkg_outbox are set to
--      'skipped' once (the same thing the guard does to a new row; the row itself is kept).
--   2) RAZORPAY PAYMENT LINKS. create-payment-link (live pay) asks payment_link_begin, and Razorpay then
--      texts / e-mails the client the link (notify sms + email) and takes real money. 0097 only refused
--      demo events, so a trial studio's own event could get a real link. payment_link_begin is wrapped
--      (current body kept as payment_link_begin__pre0187): a quote of a studio for which 0179 says
--      "no client messages" (free trial, ended unpaid trial, sample master) is refused 42501 / hint
--      'trial_no_send'. The simulated checkout (create_payment, off production) is unchanged.
--   Paid studios: never matched by either rule - nothing changes for them.
-- Changes: 1 function body re-issued (same signature, same grants), 1 function wrapped (same signature,
-- service role only as before). No table or column is created, changed or dropped; nothing is deleted.
-- The only rows written: waiting client messages of ended, never-paid trials -> status 'skipped' (never
-- a paid studio: _trial_locked is false for any studio that ever paid). Additive + idempotent: safe to
-- run twice (a second run finds nothing to skip). ASCII only.
-- ROLLBACK (manual, only if ever needed): re-run 0166 section 6 (_sample_outbound_blocked); drop function
-- public.payment_link_begin(uuid, integer); alter function public.payment_link_begin__pre0187(uuid, integer)
-- rename to payment_link_begin; grant execute on it to service_role. No data is touched either way.

do $$ begin
  if to_regprocedure('public._sample_outbound_blocked(uuid,text)') is null or to_regprocedure('public._ts166_tg_outbox_skip()') is null then
    raise exception '0187: apply 0166 first'; end if;
  if to_regprocedure('public._tb179_no_send(uuid)') is null then raise exception '0187: apply 0179 first'; end if;
  if to_regprocedure('public._trial_effective_end(uuid)') is null then raise exception '0187: apply 0183 first'; end if;
  if to_regprocedure('public.payment_link_begin(uuid,integer)') is null then raise exception '0187: apply 0027 + 0097 first'; end if;
end $$;

-- ---- 1) outbox guard: an ended, unpaid (read-only) trial queues nothing either --------------------------
create or replace function public._sample_outbound_blocked(p_org uuid, p_recipient text)
returns boolean language sql stable security definer set search_path = '' as $$
  -- trial-sandbox-0166 trial-outbound-0187
  -- (p_recipient kept for the next phase: per-recipient rules; sample contacts are already
  --  undeliverable @example.com / +91 00000 and demo events are skipped by 0097)
  select (p_org is not null and exists (select 1 from public.organizations o where o.id = p_org and o.is_sample_master))
      or (p_org is not null and coalesce((select t.block_trial_outbound from public.helm_sample_template t where t.id), true)
          and public._is_trial_org(p_org))
      -- 0187: an ended, never-paid free trial (read-only, status-based) never messages its clients
      or (p_org is not null and coalesce(public._trial_locked(p_org), false));
$$;
revoke all on function public._sample_outbound_blocked(uuid, text) from public;
do $$ begin
  if exists (select 1 from pg_roles where rolname = 'anon') then revoke all on function public._sample_outbound_blocked(uuid, text) from anon; end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then revoke all on function public._sample_outbound_blocked(uuid, text) from authenticated; end if;
end $$;

-- messages an ended, unpaid trial already has waiting: skipped once (kept, never sent)
do $$ declare t text; begin
  foreach t in array array['comms_outbox', 'pkg_outbox'] loop
    if to_regclass('public.' || t) is not null then
      execute format('update public.%I x set status = ''skipped'' where x.status = ''pending'' and x.sent_at is null '
                     'and x.org_id is not null and public._trial_locked(x.org_id)', t);
    end if;
  end loop;
end $$;

-- ---- 2) no real Razorpay payment link for a quote of a studio that sends no client messages ------------
do $$ begin
  if to_regprocedure('public.payment_link_begin__pre0187(uuid,integer)') is null
     and position('trial-outbound-0187' in pg_get_functiondef(to_regprocedure('public.payment_link_begin(uuid,integer)'))) = 0 then
    alter function public.payment_link_begin(uuid, integer) rename to payment_link_begin__pre0187;
  end if;
end $$;

create or replace function public.payment_link_begin(p_token uuid, p_ttl_minutes integer default 4320)
returns jsonb language plpgsql security definer set search_path = '' as $$
-- trial-outbound-0187: free trial / ended unpaid trial / sample master -> no real payment link (Razorpay
-- would text and e-mail the client and take real money)
begin
  if exists (select 1 from public.quotes q where p_token is not null and q.approval_token = p_token and public._tb179_no_send(q.org_id)) then
    raise exception 'Free trial: online payment links are not sent to clients' using errcode = '42501', hint = 'trial_no_send';
  end if;
  return public.payment_link_begin__pre0187(p_token, p_ttl_minutes);
end $$;

-- grants: both service role only (as payment_link_begin always was)
do $$ declare f text; begin
  foreach f in array array['public.payment_link_begin(uuid, integer)', 'public.payment_link_begin__pre0187(uuid, integer)'] loop
    execute format('revoke all on function %s from public', f);
    if exists (select 1 from pg_roles where rolname = 'anon') then execute format('revoke all on function %s from anon', f); end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then execute format('revoke all on function %s from authenticated', f); end if;
    if exists (select 1 from pg_roles where rolname = 'service_role') then execute format('grant execute on function %s to service_role', f); end if;
  end loop;
end $$;

notify pgrst, 'reload schema';
commit;

-- VERIFY (every row should say ok = true)
select item, ok from (values
  ('01 outbox guard also blocks an ended unpaid (read-only) trial',
     position('trial-outbound-0187' in coalesce((select prosrc from pg_proc where oid = to_regprocedure('public._sample_outbound_blocked(uuid,text)')), '')) > 0
     and position('_trial_locked' in coalesce((select prosrc from pg_proc where oid = to_regprocedure('public._sample_outbound_blocked(uuid,text)')), '')) > 0),
  ('02 outbox guard: internal only (not callable by the app)',
     not has_function_privilege('authenticated', 'public._sample_outbound_blocked(uuid,text)', 'execute')
     and not has_function_privilege('anon', 'public._sample_outbound_blocked(uuid,text)', 'execute')),
  ('03 outbox skip triggers in place (insert + retry to pending)',
     exists (select 1 from pg_trigger where tgrelid = 'public.comms_outbox'::regclass and tgname = 'zzzz_ts166_outbox_skip')
     and exists (select 1 from pg_trigger where tgrelid = 'public.comms_outbox'::regclass and tgname = 'zzzz_tb179_outbox_skip_upd')
     and exists (select 1 from pg_trigger where tgrelid = 'public.pkg_outbox'::regclass and tgname = 'zzzz_ts166_outbox_skip')),
  ('04 payment_link_begin wrapped (trial check, old body kept)',
     position('trial-outbound-0187' in coalesce((select prosrc from pg_proc where oid = to_regprocedure('public.payment_link_begin(uuid,integer)')), '')) > 0
     and to_regprocedure('public.payment_link_begin__pre0187(uuid,integer)') is not null),
  ('05 payment_link_begin + kept body: service role only',
     has_function_privilege('service_role', 'public.payment_link_begin(uuid,integer)', 'execute')
     and not has_function_privilege('authenticated', 'public.payment_link_begin(uuid,integer)', 'execute')
     and not has_function_privilege('anon', 'public.payment_link_begin(uuid,integer)', 'execute')
     and not has_function_privilege('authenticated', 'public.payment_link_begin__pre0187(uuid,integer)', 'execute')
     and not has_function_privilege('anon', 'public.payment_link_begin__pre0187(uuid,integer)', 'execute')),
  ('06 no queued client message pending for an ended unpaid trial',
     not exists (select 1 from public.comms_outbox c where c.status = 'pending' and c.sent_at is null and public._trial_locked(c.org_id))
     and not exists (select 1 from public.pkg_outbox c where c.status = 'pending' and c.sent_at is null and public._trial_locked(c.org_id))),
  ('07 paid studios: never blocked',
     not exists (select 1 from public.studio_subscriptions s where s.status = 'active' and public._sample_outbound_blocked(s.org_id, null)))
) v(item, ok) order by item;

-- ##########################################################################################
-- RELEASE SECTION 15/28: FIX-0177-existing-trials.sql
-- In plain words: Existing free-trial studios corrected to the India defaults (5 columns of trial studios only).
-- ##########################################################################################
-- FIX-0177-existing-trials.sql - OWNER-RUN, after APPLY-0177.sql. Staging first, then production.
-- Corrects EXISTING free-trial studios to India defaults: currency INR, timezone Asia/Kolkata,
-- country IN, GST state (Telangana when none / not Indian) and stamps trial_region = 'IN' so 0177 keeps them there.
-- Touches ONLY organizations rows that are self-serve free trials still on their trial:
--   trial_ends_at set + trial_mode set + not the sample master + subscription status 'trial' (or no row)
--   + an audit row showing the trial was started by start_self_serve_trial / start_trial / my_pending_start_trial.
-- Only these 5 columns of those rows change. No other table, row or column (brand, quotes, events) is touched.
-- Quotes keep the currency they were priced with. Idempotent: a second run updates 0 rows.

-- 1) PREVIEW (run first, read the list)
select o.id, o.name, o.created_at, o.currency, o.timezone, o.country, o.tax_region, o.trial_mode, o.trial_region
  from public.organizations o
 where o.trial_ends_at is not null and o.trial_mode is not null and not coalesce(o.is_sample_master, false)
   and coalesce((select s.status from public.studio_subscriptions s where s.org_id = o.id), 'trial') = 'trial'
   and exists (select 1 from public.audit_log a where a.org_id = o.id and a.action = 'subscription.trial_started'
                 and a.changed ->> 'source' in ('start_self_serve_trial', 'start_trial', 'my_pending_start_trial'))
 order by o.created_at;

-- 2) FIX
begin;
update public.organizations o
   set currency = 'INR', timezone = 'Asia/Kolkata', country = 'IN', trial_region = 'IN',
       tax_region = case when o.country = 'IN' and nullif(btrim(coalesce(o.tax_region, '')), '') is not null then o.tax_region else 'Telangana' end
 where o.trial_ends_at is not null and o.trial_mode is not null and not coalesce(o.is_sample_master, false)
   and coalesce((select s.status from public.studio_subscriptions s where s.org_id = o.id), 'trial') = 'trial'
   and exists (select 1 from public.audit_log a where a.org_id = o.id and a.action = 'subscription.trial_started'
                 and a.changed ->> 'source' in ('start_self_serve_trial', 'start_trial', 'my_pending_start_trial'))
   and (o.currency is distinct from 'INR' or o.timezone is distinct from 'Asia/Kolkata' or o.country is distinct from 'IN'
        or o.trial_region is distinct from 'IN' or nullif(btrim(coalesce(o.tax_region, '')), '') is null);
commit;

-- 3) VERIFY (should return 0 rows)
select o.id, o.name, o.currency, o.timezone, o.country, o.tax_region
  from public.organizations o
 where o.trial_ends_at is not null and o.trial_mode is not null and not coalesce(o.is_sample_master, false)
   and coalesce((select s.status from public.studio_subscriptions s where s.org_id = o.id), 'trial') = 'trial'
   and exists (select 1 from public.audit_log a where a.org_id = o.id and a.action = 'subscription.trial_started'
                 and a.changed ->> 'source' in ('start_self_serve_trial', 'start_trial', 'my_pending_start_trial'))
   and (o.currency <> 'INR' or o.timezone <> 'Asia/Kolkata' or o.country is distinct from 'IN' or o.trial_region is distinct from 'IN');

-- ##########################################################################################
-- RELEASE SECTION 16/28: APPLY-0189.sql
-- In plain words: One quote status label everywhere ("sent - awaiting client approval" until the client approves).
-- ##########################################################################################
-- APPLY-0189.sql - paste into the Supabase SQL editor (staging first, then production).
-- One quote status label: the client page says "confirmed" only once the client approved; a locked quote
-- with the link out reads "sent - awaiting client approval". Same rule as the Quotes list / Event Workspace.
-- Additive + idempotent: 1 new read-only function + re-issues client_timeline (0160 body + the label).
-- No table, column, trigger or row is created, changed or deleted. Safe to run twice.
begin;
-- 0189_quote_status_label.sql - CANONICAL forward-only. ONE status label for a quote.
--
-- In plain words:
--   A quote has three state columns: status ('confirmed' = the studio priced and LOCKED it),
--   approval_status (none / sent / approved / paid) and lifecycle_stage. The client 360 page
--   ("Status now: ..." timeline row + the client status pill) said "confirmed" for a quote the
--   studio had only locked and sent, before the client approved it. The app (Quotes list, Event
--   Workspace, dashboard) now folds the three into one label (BPStore.quoteStatus); this does the
--   same on the server so the client page agrees:
--     * a quote at stage lead..quote reads "confirmed" only once the client approved (or paid);
--       locked + link sent -> "sent - awaiting client approval"; locked, link not sent yet ->
--       "locked - not sent yet"; cancelled -> "cancelled"; otherwise its stage (as before).
--     * a stage after "quote" (confirmed, planning, ... closed) still reads that stage (as before).
--   1) new helper public.helm_quote_status_label(status, stage, approval) - immutable, no table read.
--   2) client_timeline re-issued with the helper in its two status expressions. Everything else in
--      it (access checks, Due = confirmed events only incl. approved change orders, totals, grants)
--      is the 0160 body unchanged.
--
-- Additive + idempotent: 1 new function + create or replace of ONE read-only function (same
-- signature, security definer, empty search_path, grants). NO table, column, trigger or row is
-- created, changed or deleted. Needs 0160. Safe to run twice. ASCII only.
-- ROLLBACK (only if ever needed): re-run supabase/migrations/0160_client_due_confirmed_only.sql.
-- ============================================================================

do $$ begin
  if to_regprocedure('public.client_timeline(uuid,integer)') is null then raise exception '0189: apply 0062/0068/0094/0160 first (client_timeline missing)'; end if;
  if to_regclass('public.change_requests') is null then raise exception '0189: change_requests table missing (phase12)'; end if;
  if not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'quotes' and column_name = 'approval_status') then
    raise exception '0189: quotes.approval_status missing';
  end if;
  if not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'quotes' and column_name = 'currency') then
    raise exception '0189: apply 0089 + 0091 first (quotes.currency missing)';
  end if;
end $$;

-- 1) one label from status + stage + client approval (mirrors BPStore.quoteStatus in store-api.js)
create or replace function public.helm_quote_status_label(p_status text, p_stage text, p_approval text)
returns text language sql immutable set search_path = '' as $$
  -- helm-0189-quote-status-label
  select case
    when coalesce(nullif(p_stage, ''), 'quote') not in ('lead', 'discovery', 'proposal', 'quote')
      then coalesce(nullif(p_stage, ''), coalesce(nullif(p_status, ''), 'quote'))
    when p_status = 'cancelled' then 'cancelled'
    when coalesce(p_approval, 'none') in ('approved', 'paid') then 'confirmed'
    when coalesce(p_approval, 'none') = 'sent' then 'sent - awaiting client approval'
    when p_status = 'confirmed' then 'locked - not sent yet'
    else coalesce(nullif(p_stage, ''), 'quote')
  end
$$;
revoke all on function public.helm_quote_status_label(text, text, text) from public;
do $$ begin
  if exists (select 1 from pg_roles where rolname = 'anon') then execute 'revoke all on function public.helm_quote_status_label(text, text, text) from anon'; end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then execute 'grant execute on function public.helm_quote_status_label(text, text, text) to authenticated'; end if;
  if exists (select 1 from pg_roles where rolname = 'service_role') then execute 'grant execute on function public.helm_quote_status_label(text, text, text) to service_role'; end if;
end $$;

-- 2) client_timeline (0160 body; only the two status expressions use the helper)
create or replace function public.client_timeline(p_ref uuid, p_limit integer default 300)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
-- helm-0189-quote-status-label (0160 body + one status label)
declare
  v_me uuid := auth.uid(); v_org uuid := public.current_org_id(); v_role text;
  v_leads boolean; v_quotes boolean; v_fin boolean; v_media boolean; v_staff boolean;
  v_name text; v_phone text; v_email text; v_digits text; v_lname text;
  v_lead_ids uuid[] := '{}'; v_quote_ids uuid[] := '{}'; v_lim int;
  v_items jsonb := '[]'::jsonb; v_rows jsonb; v_status text; v_found boolean := false;
  v_quoted numeric; v_paid numeric; v_totals jsonb := null; v_sections text[] := '{}';
  v_bycur jsonb; v_due numeric := 0;
begin
  if v_me is null or v_org is null then raise exception 'not authorized' using errcode = '42501'; end if;
  select p.role into v_role from public.profiles p where p.id = v_me and p.org_id = v_org;
  if not found or v_role is null or v_role = 'client' then raise exception 'not authorized' using errcode = '42501'; end if;
  if p_ref is null then raise exception 'not found' using errcode = 'P0002'; end if;

  v_leads := public.has_area('leads', 'view');
  v_quotes := public.has_area('quotes', 'view');
  v_fin := public.has_area('finance', 'view');
  v_media := public.has_area('media', 'view');
  v_staff := public.has_area('staff', 'view');
  v_lim := greatest(1, least(500, coalesce(p_limit, 300)));

  -- 1. the anchor: a lead (leads area) or an event (quotes area) of this studio
  if v_leads then
    select l.name, l.phone, l.email into v_name, v_phone, v_email
      from public.leads l where l.id = p_ref and l.org_id = v_org;
    v_found := found;
  end if;
  if not v_found and v_quotes then
    select q.client ->> 'name', q.client ->> 'phone', q.client ->> 'email' into v_name, v_phone, v_email
      from public.quotes q where q.id = p_ref and q.org_id = v_org and q.deleted_at is null;
    v_found := found;
  end if;
  if not v_found then raise exception 'not found' using errcode = 'P0002'; end if;

  v_name := nullif(btrim(coalesce(v_name, '')), '');
  v_lname := lower(v_name);
  v_digits := nullif(right(regexp_replace(coalesce(v_phone, ''), '\D', '', 'g'), 10), '');
  if char_length(coalesce(v_digits, '')) < 7 then v_digits := null; end if;
  v_email := nullif(lower(btrim(coalesce(v_email, ''))), '');

  -- 2. the same person's leads and events (own studio only)
  select coalesce(array_agg(l.id), '{}') into v_lead_ids from public.leads l
   where l.org_id = v_org and (l.id = p_ref
      or (v_digits is not null and right(regexp_replace(coalesce(l.phone, ''), '\D', '', 'g'), 10) = v_digits)
      or (v_email is not null and lower(btrim(coalesce(l.email, ''))) = v_email)
      or (v_lname is not null and lower(btrim(coalesce(l.name, ''))) = v_lname
          and (v_digits is null or char_length(regexp_replace(coalesce(l.phone, ''), '\D', '', 'g')) < 7)));
  select coalesce(array_agg(q.id), '{}') into v_quote_ids from public.quotes q
   where q.org_id = v_org and q.deleted_at is null and (q.id = p_ref
      or q.id in (select l.quote_id from public.leads l where l.org_id = v_org and l.id = any(v_lead_ids))
      or (v_digits is not null and right(regexp_replace(coalesce(q.client ->> 'phone', ''), '\D', '', 'g'), 10) = v_digits)
      or (v_email is not null and lower(btrim(coalesce(q.client ->> 'email', ''))) = v_email)
      or (v_lname is not null and lower(btrim(coalesce(q.client ->> 'name', ''))) = v_lname
          and (v_digits is null or char_length(regexp_replace(coalesce(q.client ->> 'phone', ''), '\D', '', 'g')) < 7)));
  -- events linked from a matched lead pull that lead in too
  select coalesce(array_agg(distinct x), '{}') into v_lead_ids from (
    select unnest(v_lead_ids) x union
    select l.id from public.leads l where l.org_id = v_org and l.quote_id = any(v_quote_ids)) s;

  -- 3. timeline parts, each gated by the access matrix
  if v_leads then
    v_sections := v_sections || 'leads'::text;
    select coalesce(jsonb_agg(j), '[]'::jsonb) into v_rows from (
      select jsonb_build_object('kind', 'leads', 'at', l.created_at, 'id', l.id,
               'title', 'Lead added: ' || coalesce(nullif(l.name, ''), 'lead'),
               'subtitle', concat_ws(' / ', nullif(l.status, ''), nullif(l.event_type, ''), nullif(l.source, ''), to_char(l.event_date, 'YYYY-MM-DD')),
               'link', 'leads.html?hs=' ) as j
        from public.leads l where l.org_id = v_org and l.id = any(v_lead_ids)
      union all
      select jsonb_build_object('kind', 'leads', 'at', l.updated_at, 'id', l.id,
               'title', 'Lead status: ' || l.status, 'subtitle', coalesce(nullif(l.name, ''), ''),
               'link', 'leads.html?hs=')
        from public.leads l where l.org_id = v_org and l.id = any(v_lead_ids)
         and l.updated_at is not null and l.updated_at > l.created_at + interval '1 minute' and nullif(l.status, '') is not null) s;
    v_items := v_items || v_rows;
    select l.status into v_status from public.leads l where l.org_id = v_org and l.id = any(v_lead_ids)
     order by l.updated_at desc nulls last limit 1;
  end if;

  if v_quotes then
    v_sections := v_sections || 'events'::text;
    select coalesce(jsonb_agg(j), '[]'::jsonb) into v_rows from (
      select jsonb_build_object('kind', 'events', 'at', q.created_at, 'id', q.id,
               'title', 'Event created: ' || coalesce(nullif(q.title, ''), q.code),
               'subtitle', concat_ws(' / ', q.code, nullif(q.event_type, ''), to_char(q.event_date, 'YYYY-MM-DD')),
               'link', 'event.html?id=' || q.id::text) as j
        from public.quotes q where q.org_id = v_org and q.id = any(v_quote_ids)
      union all
      select jsonb_build_object('kind', 'events', 'at', q.confirmed_at, 'id', q.id,
               'title', 'Event confirmed: ' || coalesce(nullif(q.title, ''), q.code),
               'subtitle', concat_ws(' / ', q.code, nullif(q.approval_status, '')),
               'link', 'event.html?id=' || q.id::text)
        from public.quotes q where q.org_id = v_org and q.id = any(v_quote_ids) and q.confirmed_at is not null
      union all
      select jsonb_build_object('kind', 'events', 'at', q.updated_at, 'id', q.id,
               'title', 'Status now: ' || public.helm_quote_status_label(q.status, q.lifecycle_stage, q.approval_status),
               'subtitle', concat_ws(' / ', q.code, nullif(q.approval_status, '')),
               'link', 'event.html?id=' || q.id::text)
        from public.quotes q where q.org_id = v_org and q.id = any(v_quote_ids)
         and q.updated_at > q.created_at + interval '1 minute'
      union all
      select jsonb_build_object('kind', 'events', 'at', v.created_at, 'id', v.id,
               'title', 'Quote version ' || v.version_no || coalesce(': ' || nullif(v.label, ''), ''),
               'subtitle', q.code, 'link', 'event.html?id=' || q.id::text)
        from public.quote_versions v join public.quotes q on q.id = v.quote_id and q.org_id = v_org
       where v.org_id = v_org and v.quote_id = any(v_quote_ids)) s;
    v_items := v_items || v_rows;
    if cardinality(v_quote_ids) > 0 then   -- the latest event's stage wins over a lead status
      select public.helm_quote_status_label(q.status, q.lifecycle_stage, q.approval_status) into v_status from public.quotes q
       where q.org_id = v_org and q.id = any(v_quote_ids) order by q.updated_at desc nulls last limit 1;
    end if;
    -- 0068: same fallback as the app (store-api mapQuoteSummary / budget.summary):
    -- pricing.total, then an older top-level total column if this database has one.
    select coalesce(sum(coalesce(
             case when (q.pricing ->> 'total') ~ '^\s*-?[0-9]+(\.[0-9]+)?\s*$' then (q.pricing ->> 'total')::numeric end,
             case when (to_jsonb(q) ->> 'total') ~ '^\s*-?[0-9]+(\.[0-9]+)?\s*$' then (to_jsonb(q) ->> 'total')::numeric end,
             0)), 0) into v_quoted
      from public.quotes q where q.org_id = v_org and q.id = any(v_quote_ids);
    v_totals := jsonb_build_object('quoted', round(v_quoted, 2), 'events', cardinality(v_quote_ids));
  end if;

  if v_fin then
    v_sections := v_sections || 'payments'::text;
    select coalesce(jsonb_agg(j), '[]'::jsonb) into v_rows from (
      select jsonb_build_object('kind', 'payments', 'at', coalesce(pm.paid_at, pm.created_at), 'id', pm.id,
               'title', case when pm.status = 'paid' then 'Payment received' else 'Payment ' || pm.status end
                        || coalesce(' (' || pm.receipt_no || ')', ''),
               'subtitle', concat_ws(' / ', q.code, pm.currency || ' ' || to_char(pm.amount, 'FM999999999990.00'), nullif(pm.method, '')),
               'link', 'settlement.html?quote=' || q.id::text) as j
        from public.quote_payments pm join public.quotes q on q.id = pm.quote_id and q.org_id = v_org
       where pm.org_id = v_org and pm.quote_id = any(v_quote_ids)
      union all
      select jsonb_build_object('kind', 'payments', 'at', coalesce(m.paid_at, m.created_at), 'id', m.id,
               'title', 'Milestone: ' || coalesce(nullif(m.label, ''), 'payment') || ' (' || m.status || ')',
               'subtitle', concat_ws(' / ', q.code, to_char(m.amount, 'FM999999999990.00'), 'due ' || to_char(m.due_date, 'YYYY-MM-DD')),
               'link', 'settlement.html?quote=' || q.id::text)
        from public.payment_milestones m join public.quotes q on q.id = m.quote_id and q.org_id = v_org
       where m.org_id = v_org and m.quote_id = any(v_quote_ids)) s;
    v_items := v_items || v_rows;
    -- 0068: same rule as the settlement page (store-api settlement.summary), per event:
    -- the quote_payments LEDGER when that event has any ledger row, otherwise its paid milestones.
    -- 0160: paid stays the 0068 rule (ledger when the event has any ledger row, else paid milestones);
    -- DUE = per CONFIRMED event, max(invoice total - paid, 0), invoice total = quote total + APPROVED
    -- change orders (the same balance the settlement page shows). Unconfirmed quotes owe nothing yet.
    select coalesce(sum(pd), 0), coalesce(sum(case when st = 'confirmed' then greatest(inv - pd, 0) else 0 end), 0)
      into v_paid, v_due
      from (select q.status as st, coalesce(
             case when (q.pricing ->> 'total') ~ '^\s*-?[0-9]+(\.[0-9]+)?\s*$' then (q.pricing ->> 'total')::numeric end,
             case when (to_jsonb(q) ->> 'total') ~ '^\s*-?[0-9]+(\.[0-9]+)?\s*$' then (to_jsonb(q) ->> 'total')::numeric end,
             0)
                   + coalesce((select sum(c.price_delta) from public.change_requests c
                                where c.org_id = v_org and c.quote_id = q.id and c.status = 'approved'), 0) as inv,
                   case when exists (select 1 from public.quote_payments x where x.org_id = v_org and x.quote_id = q.id)
                     then (select coalesce(sum(pm.amount), 0) from public.quote_payments pm
                            where pm.org_id = v_org and pm.quote_id = q.id and pm.status = 'paid')
                     else (select coalesce(sum(m.amount), 0) from public.payment_milestones m
                            where m.org_id = v_org and m.quote_id = q.id and m.status = 'paid') end as pd
              from public.quotes q where q.org_id = v_org and q.id = any(v_quote_ids)) s;
    v_totals := coalesce(v_totals, '{}'::jsonb) || jsonb_build_object('paid', round(v_paid, 2));
    if v_quotes then
      v_totals := v_totals || jsonb_build_object('due', round(v_due, 2));
    end if;
  end if;

  -- per-currency-0094: the same quoted / paid / due, one row per quote currency
  if v_totals is not null and cardinality(v_quote_ids) > 0 then
    select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object('currency', cur, 'events', n,
             'quoted', case when v_quotes then round(qd, 2) end,
             'paid', case when v_fin then round(pd, 2) end,
             'due', case when v_quotes and v_fin then round(dd, 2) end)) order by cur), '[]'::jsonb) into v_bycur
      from (select cur, count(*) as n, sum(base) as qd, sum(pd) as pd,
                   sum(case when st = 'confirmed' then greatest(base + chg - pd, 0) else 0 end) as dd
              from (select coalesce(nullif(upper(btrim(q.currency)), ''), 'INR') as cur, q.status as st,
                           coalesce(
             case when (q.pricing ->> 'total') ~ '^\s*-?[0-9]+(\.[0-9]+)?\s*$' then (q.pricing ->> 'total')::numeric end,
             case when (to_jsonb(q) ->> 'total') ~ '^\s*-?[0-9]+(\.[0-9]+)?\s*$' then (to_jsonb(q) ->> 'total')::numeric end,
             0) as base,
                           coalesce((select sum(c.price_delta) from public.change_requests c
                                      where c.org_id = v_org and c.quote_id = q.id and c.status = 'approved'), 0) as chg,
                           case when exists (select 1 from public.quote_payments x where x.org_id = v_org and x.quote_id = q.id)
                             then (select coalesce(sum(pm.amount), 0) from public.quote_payments pm
                                    where pm.org_id = v_org and pm.quote_id = q.id and pm.status = 'paid')
                             else (select coalesce(sum(m.amount), 0) from public.payment_milestones m
                                    where m.org_id = v_org and m.quote_id = q.id and m.status = 'paid') end as pd
                      from public.quotes q where q.org_id = v_org and q.id = any(v_quote_ids)) e
             group by cur) s;
    v_totals := v_totals || jsonb_build_object('by_currency', v_bycur);
  end if;

  if v_quotes or v_media then
    v_sections := v_sections || 'files'::text;
    select coalesce(jsonb_agg(j), '[]'::jsonb) into v_rows from (
      select jsonb_build_object('kind', 'files', 'at', f.created_at, 'id', f.id,
               'title', 'File uploaded: ' || coalesce(nullif(f.filename, ''), 'file'),
               'subtitle', q.code, 'link', 'event.html?id=' || q.id::text) as j
        from public.event_files f join public.quotes q on q.id = f.quote_id and q.org_id = v_org
       where f.org_id = v_org and f.quote_id = any(v_quote_ids)) s;
    v_items := v_items || v_rows;
  end if;

  if v_staff then
    v_sections := v_sections || 'tasks'::text;
    select coalesce(jsonb_agg(j), '[]'::jsonb) into v_rows from (
      select jsonb_build_object('kind', 'tasks', 'at', coalesce(t.completed_at, t.created_at), 'id', t.id,
               'title', 'Task: ' || coalesce(nullif(t.title, ''), 'task'),
               'subtitle', concat_ws(' / ', q.code, nullif(t.status, ''), nullif(t.assignee_name, '')),
               'link', 'ops.html?quote=' || q.id::text) as j
        from public.event_tasks t join public.quotes q on q.id = t.quote_id and q.org_id = v_org
       where t.org_id = v_org and t.quote_id = any(v_quote_ids)) s;
    v_items := v_items || v_rows;
  end if;

  -- messages: only event chats the caller can already see (membership / broadcast)
  v_sections := v_sections || 'messages'::text;
  select coalesce(jsonb_agg(j), '[]'::jsonb) into v_rows from (
    select jsonb_build_object('kind', 'messages', 'at', m.created_at, 'id', m.id,
             'title', 'Message in ' || coalesce(nullif(c.title, ''), 'event chat'),
             'subtitle', left(case when m.kind = 'text' then coalesce(m.body, '') else '[' || coalesce(m.kind, 'media') || ']' end, 140),
             'link', 'chat.html?c=' || c.id::text) as j
      from public.chat_messages m join public.chat_conversations c on c.id = m.conversation_id and c.org_id = v_org
     where m.org_id = v_org and not coalesce(m.deleted, false) and c.quote_id = any(v_quote_ids)
       and public.chat_can_see(c.id)
     order by m.created_at desc limit 100) s;
  v_items := v_items || v_rows;

  select coalesce(jsonb_agg(e order by (e ->> 'at')::timestamptz desc nulls last), '[]'::jsonb) into v_items
    from (select e from jsonb_array_elements(v_items) e order by (e ->> 'at')::timestamptz desc nulls last limit v_lim) s;

  return jsonb_build_object(
    'client', jsonb_build_object('name', coalesce(v_name, 'Client'), 'phone', v_phone, 'email', v_email, 'status', v_status),
    'totals', v_totals, 'sections', to_jsonb(v_sections),
    'counts', jsonb_strip_nulls(jsonb_build_object('leads', case when v_leads then cardinality(v_lead_ids) end,
                                                   'events', case when v_quotes then cardinality(v_quote_ids) end)),
    'items', v_items);
end $$;

revoke all on function public.client_timeline(uuid, integer) from public;
do $$ begin
  if exists (select 1 from pg_roles where rolname = 'anon') then execute 'revoke all on function public.client_timeline(uuid, integer) from anon'; end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then execute 'grant execute on function public.client_timeline(uuid, integer) to authenticated'; end if;
end $$;

notify pgrst, 'reload schema';
commit;

-- VERIFY (read-only; every row should say ok = true)
select item, ok from (values
  ('01 helm_quote_status_label exists', to_regprocedure('public.helm_quote_status_label(text,text,text)') is not null),
  ('02 label: locked + sent is not confirmed', public.helm_quote_status_label('confirmed', 'quote', 'sent') = 'sent - awaiting client approval'),
  ('03 label: client approved reads confirmed', public.helm_quote_status_label('confirmed', 'quote', 'approved') = 'confirmed' and public.helm_quote_status_label('confirmed', 'quote', 'paid') = 'confirmed'),
  ('04 label: locked, link not sent', public.helm_quote_status_label('confirmed', 'quote', 'none') = 'locked - not sent yet'),
  ('05 label: later stages unchanged', public.helm_quote_status_label('confirmed', 'planning', 'none') = 'planning' and public.helm_quote_status_label('quote', 'quote', 'none') = 'quote'),
  ('06 client_timeline uses the label', coalesce(pg_get_functiondef(to_regprocedure('public.client_timeline(uuid,integer)')) like '%helm_quote_status_label(q.status, q.lifecycle_stage, q.approval_status)%', false)),
  ('07 client_timeline still security definer + stable', coalesce((select prosecdef and provolatile = 's' from pg_proc where oid = to_regprocedure('public.client_timeline(uuid,integer)')), false)),
  ('08 Due still confirmed events only (0160)', coalesce(pg_get_functiondef(to_regprocedure('public.client_timeline(uuid,integer)')) like '%when st = ''confirmed'' then greatest(inv - pd, 0)%', false)),
  ('09 client_timeline callable by authenticated, not anon', has_function_privilege('authenticated', 'public.client_timeline(uuid,integer)', 'execute')
     and (not exists (select 1 from pg_roles where rolname = 'anon') or not has_function_privilege('anon', 'public.client_timeline(uuid,integer)', 'execute'))),
  ('10 label helper not callable by anon', not exists (select 1 from pg_roles where rolname = 'anon') or not has_function_privilege('anon', 'public.helm_quote_status_label(text,text,text)', 'execute'))
) v(item, ok) order by item;

-- ##########################################################################################
-- RELEASE SECTION 17/28: APPLY-0190.sql
-- In plain words: Faster free-trial sign-up and sample clone (stays far inside the 8 second API limit).
-- ##########################################################################################
-- APPLY-0190.sql - paste into the Supabase SQL editor (STAGING first; production when the owner says go).
-- Run AFTER APPLY-0168 / 0169 (works on the current production state 0166-0172 and on the trial bundle 0173-0177).
-- Free-trial sign-up reliability: the sign-up call (start_self_serve_trial) is 2-3x faster so it stays far
-- inside Supabase's 8 second API limit (a time-out cannot be caught and would undo the whole sign-up):
-- cheap time zone check instead of reading pg_timezone_names on every sign-up, and a faster sample clone
-- (same rows, same result). The clone also reports 'kept_existing' (sample rows the new studio already had,
-- e.g. the 145 library dishes + 6 menu packages create_studio copies) so the audit log no longer reads
-- "dish_catalog 0, menu_templates 0".
-- Functions only: 2 bodies replaced + 1 helper added; no table, column or row change, nothing deleted.
-- Safe to run twice. ASCII only.
begin;
-- ============================================================================
-- 0190_trial_clone_reliability.sql - CANONICAL forward-only. Free-trial sign-up: the sample
-- clone and the trial start are made fast enough that they can never hit the API time limit.
-- REQUIRES 0119 (start_self_serve_trial), 0166 + 0167 + 0168 (sample clone chain:
--          _sample_clone_into -> _sample_clone_into__pre0168), 0169 (_sample_clone_tables).
--
-- In plain words:
--   1  The free trial is created by ONE database call from the browser (start_self_serve_trial).
--      On Supabase every browser call has an 8 second limit (authenticated statement_timeout).
--      A time-out is NOT caught by the "a failed sample never blocks the trial" safety net
--      (PostgreSQL never lets a function catch a cancel): the whole sign-up would be undone and
--      the visitor would see an error. Today the call takes well under a second on a laptop, but
--      two parts of it were needlessly slow and grow with the sample size:
--        a) the visitor time zone was checked against pg_timezone_names, which reads every time
--           zone file from disk on each call (about 0.2 s here, more on a small cloud server).
--           It is now checked with a cheap name pattern + PostgreSQL's own time zone lookup;
--           anything unknown still falls back to UTC, exactly as before.
--        b) the clone (_sample_clone_into__pre0168, body from 0167) re-scanned the WHOLE id map
--           (about 500 ids) for every one of the ~500 sample rows, and re-read the table
--           definitions from the catalog for every row. It now finds only the ids that are in
--           the row, reads each table's definition once, and inserts each table's rows in one
--           statement. Same rows, same ids remapped, same dates, same dummy contacts, same
--           is_demo flags, same "do nothing on a duplicate" rule - only faster.
--   2  The clone result now also says how many sample rows were already present in the new
--      studio and therefore kept as they were ('kept_existing'), e.g. the 145 dishes and 6 menu
--      packages that create_studio() already copies from the Helm library studio. Before this
--      the audit log showed "dish_catalog 0, menu_templates 0", which looked like missing data.
--   3  Nothing else changes: 'own data' trials are still empty by design, paid studios are not
--      touched, the sample master is never a clone target, the switch / manifest rules are the
--      0167 / 0174 ones.
--
-- ZERO DATA LOSS: two function bodies replaced (CREATE OR REPLACE, same signatures, same grants);
-- no table, column, index or row is changed or removed; no trigger added. ASCII only. Safe to
-- run twice.
-- ============================================================================

do $$ begin
  if to_regprocedure('public._sample_clone_into__pre0168(uuid)') is null or to_regprocedure('public._sample_clone_into(uuid)') is null then
    raise exception '0190: apply 0166 + 0167 + 0168 (sample clone chain) first'; end if;
  if to_regprocedure('public._sample_clone_tables()') is null or to_regclass('public.helm_trial_seed_manifest') is null then
    raise exception '0190: apply 0167 + 0169 first'; end if;
  if to_regprocedure('public.start_self_serve_trial(text,text,text,text)') is null then
    raise exception '0190: apply 0119 (unified trial) first'; end if;
end $$;

-- ---- 1) the clone: same result as 0167, built set-wise --------------------------------------------
create or replace function public._sample_clone_into__pre0168(p_org uuid)
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
-- trial-clone-0190 (trial-sample-0167 / trial-sandbox-0166 semantics): own org only, once, every row
-- is_demo, from the frozen CURRENT manifest; per-table metadata read once, ids remapped by lookup,
-- one INSERT per table (per column set)
declare
  tpl public.helm_sample_template; m public.helm_trial_seed_manifest; v_src uuid; v_shift integer; v_map jsonb;
  v_batch uuid := gen_random_uuid(); v_tables text[] := public._sample_clone_tables(); t text; r record; k record; c record;
  v_txt text; v_row jsonb; v_cols text; v_counts jsonb := '{}'::jsonb; v_kept jsonb := '{}'::jsonb; n integer;
  v_seq integer := 0; v_total integer := 0; v_rel regclass; v_col text; v_has_id boolean; v_fix jsonb[] := '{}';
  f jsonb; v_pos integer; v_ins integer; v_sub jsonb; v_src_n integer;
  -- per-table metadata (read once per table, not per row)
  v_attrs text[]; v_fk_null text[]; v_fk_fix text[]; v_actor text[]; v_dates text[]; v_date_is_date boolean[];
  v_has_demo boolean; i integer;
  -- batch of rows sharing one column list
  v_bcols text; v_brows jsonb[] := '{}';
begin
  if p_org is null or not exists (select 1 from public.organizations o where o.id = p_org) then
    raise exception 'no studio' using errcode = '22023'; end if;
  select * into tpl from public.helm_sample_template x where x.id;
  select * into m from public.helm_trial_seed_manifest x where x.is_current;
  if tpl.org_id is null or not tpl.active or m.version is null then
    return jsonb_build_object('cloned', false, 'reason', 'no_template'); end if;
  v_src := m.source_org;
  if p_org = v_src or p_org = tpl.org_id or exists (select 1 from public.organizations o where o.id = p_org and o.is_sample_master) then
    raise exception 'the sample master is never a clone target' using errcode = '42501'; end if;

  perform pg_advisory_xact_lock(hashtextextended('helm:sample_clone:' || p_org::text, 0));
  if exists (select 1 from public.organizations o where o.id = p_org and o.sample_cloned_at is not null) then
    return jsonb_build_object('cloned', false, 'reason', 'already_cloned'); end if;

  v_shift := current_date - m.anchor_date;
  -- pass 1: a new id for every row (any reference, in any order, resolves) - one statement
  select jsonb_build_object(v_src::text, p_org::text) || coalesce(jsonb_object_agg(x.id, gen_random_uuid()::text), '{}'::jsonb)
    into v_map
    from (select e.j ->> 'id' as id
            from unnest(v_tables) tt(name)
            cross join lateral jsonb_array_elements(coalesce(m.payload #> array['tables', tt.name], '[]'::jsonb)) e(j)
           where e.j ? 'id' and e.j ->> 'id' is not null) x;
  if (select count(*) from jsonb_object_keys(v_map)) <= 1 then
    return jsonb_build_object('cloned', false, 'reason', 'template_empty'); end if;

  -- pass 2: insert, parents first
  foreach t in array v_tables loop
    n := 0;
    if to_regclass('public.' || t) is null then continue; end if;
    v_rel := format('public.%I', t)::regclass;
    v_pos := array_position(v_tables, t);
    v_src_n := jsonb_array_length(coalesce(m.payload #> array['tables', t], '[]'::jsonb));
    if v_src_n = 0 then v_counts := v_counts || jsonb_build_object(t, 0); continue; end if;

    -- table metadata, once
    select coalesce(array_agg(a.attname::text order by a.attnum), '{}') into v_attrs
      from pg_catalog.pg_attribute a
     where a.attrelid = v_rel and a.attnum > 0 and not a.attisdropped and a.attgenerated = '';
    v_fk_null := '{}'; v_fk_fix := '{}';
    for c in select a.attname::text as col, rn.nspname::text as rns, rc.relname::text as rrel
               from pg_catalog.pg_constraint cf
               join pg_catalog.pg_attribute a on a.attrelid = cf.conrelid and a.attnum = cf.conkey[1]
               join pg_catalog.pg_class rc on rc.oid = cf.confrelid
               join pg_catalog.pg_namespace rn on rn.oid = rc.relnamespace
              where cf.conrelid = v_rel and cf.contype = 'f' and array_length(cf.conkey, 1) = 1 loop
      -- links: login users and tenant rows this clone does not copy are dropped; a link to a row
      -- inserted LATER (e.g. lead -> quote, task -> task) is set after every row is in
      if (c.rns = 'auth' and c.rrel = 'users') or (c.rns = 'public' and c.rrel = 'profiles')
         or (c.rns = 'public' and c.rrel <> 'organizations' and not (c.rrel = any(v_tables))
             and exists (select 1 from pg_catalog.pg_attribute ra
                          where ra.attrelid = format('public.%I', c.rrel)::regclass and ra.attname = 'org_id'
                            and ra.attnum > 0 and not ra.attisdropped)) then
        v_fk_null := v_fk_null || c.col;
      elsif c.rns = 'public' and c.rrel = any(v_tables) and array_position(v_tables, c.rrel) >= v_pos then
        v_fk_fix := v_fk_fix || c.col;
      end if;
    end loop;
    select coalesce(array_agg(a.attname::text), '{}') into v_actor
      from pg_catalog.pg_attribute a
     where a.attrelid = v_rel and a.attnum > 0 and not a.attisdropped and a.atttypid = 'uuid'::regtype
       and a.attname in ('created_by', 'updated_by', 'profile_id', 'owner', 'confirmed_by', 'manager_id', 'archived_by',
                         'deleted_by', 'verified_by', 'reviewed_by', 'drafted_by', 'published_by');
    select coalesce(array_agg(a.attname::text order by a.attnum), '{}'), coalesce(array_agg(a.atttypid = 'date'::regtype order by a.attnum), '{}')
      into v_dates, v_date_is_date
      from pg_catalog.pg_attribute a
     where a.attrelid = v_rel and a.attnum > 0 and not a.attisdropped
       and a.atttypid in ('date'::regtype, 'timestamptz'::regtype, 'timestamp'::regtype)
       and a.attname not in ('created_at', 'updated_at', 'approval_token_expires_at');
    v_has_demo := 'is_demo' = any(v_attrs);
    v_bcols := null; v_brows := '{}';

    for r in select e.j from jsonb_array_elements(m.payload #> array['tables', t]) e(j) loop
      -- ids are unique uuids: remap every uuid in the row text (top-level AND nested jsonb references)
      -- that the map knows; only the uuids present in this row are looked up
      v_txt := r.j::text;
      for k in select distinct x.u[1] as u
                 from regexp_matches(v_txt, '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}', 'g') x(u) loop
        if v_map ? k.u then v_txt := replace(v_txt, k.u, v_map ->> k.u); end if;
      end loop;
      v_row := v_txt::jsonb;
      v_has_id := v_row ? 'id';
      foreach v_col in array v_fk_null loop
        if v_row ? v_col and jsonb_typeof(v_row -> v_col) <> 'null' then v_row := jsonb_set(v_row, array[v_col], 'null'::jsonb); end if;
      end loop;
      if v_has_id then
        foreach v_col in array v_fk_fix loop
          if v_row ? v_col and jsonb_typeof(v_row -> v_col) <> 'null' then
            v_fix := v_fix || jsonb_build_object('t', t, 'id', v_row ->> 'id', 'col', v_col, 'v', v_row ->> v_col);
            v_row := jsonb_set(v_row, array[v_col], 'null'::jsonb);
          end if;
        end loop;
      end if;
      foreach v_col in array v_actor loop
        if v_row ? v_col then v_row := jsonb_set(v_row, array[v_col], 'null'::jsonb); end if;
      end loop;
      -- contacts can never reach a person (already-dummy values are kept)
      v_seq := v_seq + 1;
      foreach v_col in array array['email', 'contact_email'] loop
        if v_row ? v_col and jsonb_typeof(v_row -> v_col) = 'string' then
          v_row := jsonb_set(v_row, array[v_col], to_jsonb(public._sample_safe_email(v_row ->> v_col, v_seq))); end if;
      end loop;
      foreach v_col in array array['phone', 'contact_phone', 'assignee_phone'] loop
        if v_row ? v_col and jsonb_typeof(v_row -> v_col) = 'string' then
          v_row := jsonb_set(v_row, array[v_col], to_jsonb(public._sample_safe_phone(v_row ->> v_col, v_seq))); end if;
      end loop;
      -- nested client contacts (quotes.client, quotes.pricing.client)
      foreach v_col in array array['client', 'pricing'] loop
        if jsonb_typeof(v_row -> v_col) = 'object' then
          v_sub := v_row -> v_col;
          if v_col = 'pricing' then v_sub := v_sub -> 'client'; end if;
          if jsonb_typeof(v_sub) = 'object' then
            if jsonb_typeof(v_sub -> 'email') = 'string' then v_sub := jsonb_set(v_sub, '{email}', to_jsonb(public._sample_safe_email(v_sub ->> 'email', v_seq))); end if;
            if jsonb_typeof(v_sub -> 'phone') = 'string' then v_sub := jsonb_set(v_sub, '{phone}', to_jsonb(public._sample_safe_phone(v_sub ->> 'phone', v_seq))); end if;
            if v_col = 'pricing' then v_row := jsonb_set(v_row, '{pricing,client}', v_sub); else v_row := jsonb_set(v_row, '{client}', v_sub); end if;
          end if;
        end if;
      end loop;
      -- an approval link is per trial: a fresh token, never the master's
      if t = 'quotes' and jsonb_typeof(v_row -> 'approval_token') = 'string' then
        v_row := v_row || jsonb_build_object('approval_token', gen_random_uuid(), 'approval_token_expires_at', now() + interval '30 days',
                                             'approval_token_revoked_at', null);
      end if;
      -- dates follow the signup day
      if v_shift <> 0 then
        for i in 1 .. coalesce(array_length(v_dates, 1), 0) loop
          if jsonb_typeof(v_row -> v_dates[i]) = 'string' then
            if v_date_is_date[i] then
              v_row := jsonb_set(v_row, array[v_dates[i]], to_jsonb(((v_row ->> v_dates[i])::date + v_shift)));
            else
              v_row := jsonb_set(v_row, array[v_dates[i]], to_jsonb(((v_row ->> v_dates[i])::timestamptz + make_interval(days => v_shift))));
            end if;
          end if;
        end loop;
      end if;
      v_row := v_row || jsonb_build_object('org_id', p_org);
      if v_has_demo then v_row := v_row || jsonb_build_object('is_demo', true); end if;
      if v_row ? 'created_at' then v_row := v_row || jsonb_build_object('created_at', now()); end if;
      if v_row ? 'updated_at' then v_row := v_row || jsonb_build_object('updated_at', now()); end if;
      -- only the columns this snapshot row carries (a column added later keeps its default)
      select string_agg(quote_ident(x.a), ', ' order by x.o) into v_cols
        from unnest(v_attrs) with ordinality x(a, o) where v_row ? x.a;
      if v_bcols is not null and v_cols is distinct from v_bcols then
        execute format('insert into public.%I (%s) select %s from jsonb_populate_recordset(null::public.%I, $1) on conflict do nothing',
                       t, v_bcols, v_bcols, t) using to_jsonb(v_brows);
        get diagnostics v_ins = row_count;
        n := n + v_ins; v_brows := '{}';
      end if;
      v_bcols := v_cols; v_brows := v_brows || v_row;
    end loop;
    if v_bcols is not null and coalesce(array_length(v_brows, 1), 0) > 0 then
      execute format('insert into public.%I (%s) select %s from jsonb_populate_recordset(null::public.%I, $1) on conflict do nothing',
                     t, v_bcols, v_bcols, t) using to_jsonb(v_brows);
      get diagnostics v_ins = row_count;
      n := n + v_ins;
    end if;
    v_counts := v_counts || jsonb_build_object(t, n); v_total := v_total + n;
    if v_src_n > n then v_kept := v_kept || jsonb_build_object(t, v_src_n - n); end if;
  end loop;

  -- links to rows inserted later
  foreach f in array v_fix loop
    execute format('update public.%I set %I = $1::uuid where id = $2::uuid and org_id = $3 and %I is distinct from $1::uuid',
                   f ->> 't', f ->> 'col', f ->> 'col')
      using f ->> 'v', f ->> 'id', p_org;
  end loop;

  update public.organizations
     set sample_cloned_at = now(), sample_source_org = v_src, sample_batch_id = v_batch, sample_version = m.version
   where id = p_org;
  insert into public.trial_sample_runs(org_id, source_org, version, batch_id, counts, manifest_version)
    values (p_org, v_src, m.version, v_batch, v_counts, m.version);
  insert into public.audit_log(actor, actor_email, action, entity, entity_id, changed, org_id, at)
    values (auth.uid(), null, 'trial.sample_cloned', 'organizations', p_org::text,
            jsonb_build_object('version', m.version, 'batch', v_batch, 'counts', v_counts, 'kept_existing', v_kept,
                               'shift_days', v_shift), p_org, now());
  return jsonb_build_object('cloned', true, 'seeded', true, 'source', 'sample_manifest', 'version', m.version,
                            'batch', v_batch, 'rows', v_total, 'counts', v_counts, 'kept_existing', v_kept);
end $$;

-- ---- 2) trial start: the 0119 body, time zone checked without reading every zone file ----------
create or replace function public._tz_name_ok(p text)
returns boolean language plpgsql stable set search_path = '' as $$
-- trial-clone-0190: an IANA zone name ("Asia/Kolkata", "America/Argentina/Buenos_Aires", "UTC")
-- that PostgreSQL knows; POSIX offsets like "+05:30" or "UTC+5" are refused (fall back to UTC)
declare v timestamp;
begin
  if p is null or char_length(p) > 64 then return false; end if;
  if p !~ '^(UTC|GMT|[A-Z][A-Za-z_]+(/[A-Za-z0-9_+-]+){1,2})$' then return false; end if;
  v := now() at time zone p;
  return true;
exception when others then return false;
end $$;
revoke all on function public._tz_name_ok(text) from public;
do $$ begin
  if exists (select 1 from pg_roles where rolname = 'anon') then revoke all on function public._tz_name_ok(text) from anon; end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then revoke all on function public._tz_name_ok(text) from authenticated; end if;
end $$;

create or replace function public.start_self_serve_trial(p_name text, p_timezone text, p_currency text, p_mode text)
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
-- unified-trial-0119 trial-clone-0190 (cheap time zone name check, _tz_name_ok)
declare
  v_uid uuid := auth.uid();
  v_tz text := 'UTC'; v_cur text := 'USD';
  v_mode text := lower(btrim(coalesce(p_mode, 'demo')));
  v_name text := nullif(btrim(regexp_replace(coalesce(p_name, ''), '\s+', ' ', 'g')), '');
  v_had uuid; v_org uuid; v_n bigint; v_end timestamptz;
  v_seed jsonb; v_extra jsonb; o public.organizations;
begin
  if v_uid is null then raise exception 'must be signed in to start a trial' using errcode = '42501'; end if;
  -- already in a studio: hand it back, create / seed / change nothing
  select p.org_id into v_had from public.profiles p where p.id = v_uid;
  if v_had is not null then
    select * into o from public.organizations x where x.id = v_had;
    return jsonb_build_object('result', 'has_studio', 'org_id', v_had, 'name', o.name, 'trial_ends_at', o.trial_ends_at);
  end if;
  if coalesce(public.is_platform_admin(), false) then
    raise exception 'Helm operators do not get a studio' using errcode = '42501'; end if;
  if v_mode not in ('demo', 'own') then raise exception 'choose demo or own' using errcode = '22023'; end if;
  if v_name is not null and (char_length(v_name) < 2 or char_length(v_name) > 80) then
    raise exception 'studio name must be 2 to 80 characters' using errcode = '22023'; end if;
  -- visitor's own time zone + currency (0118 rules: unknown values fall back to UTC / USD)
  if p_timezone is not null and public._tz_name_ok(btrim(p_timezone)) then
    v_tz := btrim(p_timezone); end if;
  if p_currency is not null and upper(btrim(p_currency)) in ('INR','USD','AED','GBP','SGD','AUD','CAD','EUR') then
    v_cur := upper(btrim(p_currency)); end if;

  if v_name is null then
    -- one "Demo N" at a time across the whole database (same lock as 0116)
    perform pg_advisory_xact_lock(hashtextextended('helm:start_trial:demo_n', 0));
    v_n := public._trial_next_demo_number();
    v_name := 'Demo ' || v_n::text;
  end if;
  v_org := public.create_studio(v_name, null, v_cur, v_tz);
  select * into o from public.organizations x where x.id = v_org;
  -- never touch a studio this call did not just create
  if o.id is null or o.created_by is distinct from v_uid or o.trial_ends_at is not null then
    return jsonb_build_object('result', 'has_studio', 'org_id', v_org, 'name', o.name, 'trial_ends_at', o.trial_ends_at);
  end if;

  v_end := now() + make_interval(days => public._trial_days());
  update public.organizations set trial_ends_at = v_end, trial_mode = v_mode
   where id = v_org and trial_ends_at is null;
  insert into public.studio_subscriptions(org_id, status, trial_ends_at, trial_source, updated_at, updated_by)
    values (v_org, 'trial', (v_end at time zone 'UTC')::date, 'bypass', now(), v_uid)
  on conflict (org_id) do nothing;

  if v_mode = 'demo' then
    -- sample data: a failure here never blocks the trial (that block alone is rolled back)
    begin v_seed := public._demo_seed(v_org);
    exception when others then v_seed := jsonb_build_object('seeded', false, 'error', sqlstate); end;
    begin v_extra := public._trial_seed_extra(v_org);
    exception when others then v_extra := jsonb_build_object('seeded', false, 'error', sqlstate); end;
  end if;

  insert into public.audit_log(actor, actor_email, action, entity, entity_id, changed, org_id, at)
    select v_uid, (select u.email from auth.users u where u.id = v_uid), 'subscription.trial_started',
           'organizations', v_org::text,
           jsonb_build_object('source', 'start_self_serve_trial', 'name', v_name, 'mode', v_mode,
                              'trial_ends_at', v_end, 'seed', v_seed, 'extra', v_extra),
           v_org, now();
  return jsonb_build_object('result', 'started', 'org_id', v_org, 'name', v_name, 'mode', v_mode,
                            'trial_ends_at', v_end, 'trial_days', public._trial_days(), 'seed', v_seed, 'extra', v_extra);
end $$;

-- ---- privileges: unchanged (re-stated so a re-run never widens them) -------------------------------
do $$
begin
  revoke all on function public._sample_clone_into__pre0168(uuid) from public;
  revoke all on function public.start_self_serve_trial(text, text, text, text) from public;
  if exists (select 1 from pg_roles where rolname = 'anon') then
    revoke all on function public._sample_clone_into__pre0168(uuid) from anon;
    revoke all on function public.start_self_serve_trial(text, text, text, text) from anon;
  end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    revoke all on function public._sample_clone_into__pre0168(uuid) from authenticated;
    grant execute on function public.start_self_serve_trial(text, text, text, text) to authenticated;
  end if;
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    grant execute on function public._sample_clone_into__pre0168(uuid) to service_role;
    grant execute on function public.start_self_serve_trial(text, text, text, text) to service_role;
  end if;
end $$;

notify pgrst, 'reload schema';
commit;

-- VERIFY (every row should say ok = true)
select item, ok from (values
  ('01 clone is the 0190 version', position('trial-clone-0190' in (select prosrc from pg_proc where oid = 'public._sample_clone_into__pre0168(uuid)'::regprocedure)) > 0),
  ('02 trial start is the 0190 version (no pg_timezone_names)', position('trial-clone-0190' in (select prosrc from pg_proc where oid = 'public.start_self_serve_trial(text,text,text,text)'::regprocedure)) > 0
       and position('pg_timezone_names' in (select prosrc from pg_proc where oid = 'public.start_self_serve_trial(text,text,text,text)'::regprocedure)) = 0),
  ('03 app roles cannot call the clone or the tz helper', not has_function_privilege('authenticated', 'public._sample_clone_into__pre0168(uuid)', 'execute')
       and not has_function_privilege('anon', 'public._sample_clone_into__pre0168(uuid)', 'execute')
       and not has_function_privilege('authenticated', 'public._sample_clone_into(uuid)', 'execute')
       and not has_function_privilege('authenticated', 'public._tz_name_ok(text)', 'execute')),
  ('04 signed-in users can still start a trial, anon cannot', has_function_privilege('authenticated', 'public.start_self_serve_trial(text,text,text,text)', 'execute')
       and not has_function_privilege('anon', 'public.start_self_serve_trial(text,text,text,text)', 'execute')),
  ('05 time zone check: Asia/Kolkata yes, +05:30 no', public._tz_name_ok('Asia/Kolkata') and not public._tz_name_ok('+05:30')),
  ('06 switch on + manifest current (false = sample switch still off)', public._sample_template_ready())
) v(item, ok) order by item;

-- ##########################################################################################
-- RELEASE SECTION 18/28: APPLY-0192.sql
-- In plain words: Menu packages: the database refuses a cleared / zero price or an active package with no dishes.
-- ##########################################################################################
-- APPLY-0192.sql - paste into the Supabase SQL editor (staging first, then production).
-- Menu packages: the database refuses an app save that clears a package price, sets it to 0 or less,
-- or leaves an ACTIVE package with no price or no dishes (Control Center > Menus & catalog).
-- Additive + idempotent: one trigger function (create or replace) + one trigger (created only when missing).
-- Only new / changed values are checked; no existing row is changed or re-checked. Safe to run twice.
begin;
-- 0192_menu_package_validation.sql - CANONICAL forward-only.
-- REQUIRES the base menu_templates table (price_per_plate numeric not null, dishes jsonb, active boolean).
--
-- In plain words (Control Center > Menus & catalog > Menu packages):
--   Clearing the price of a package and pressing "Save package" used to save the package with no
--   price. The page now refuses that, and this file makes the database refuse it too, so no other
--   screen or a hand-made API call can do it either.
--   A BEFORE INSERT / UPDATE trigger on public.menu_templates refuses a write made straight from the
--   app (signed-in user or client link: current_user anon / authenticated) when:
--     * an ACTIVE package would have no price, a price of 0 or less, or no dishes;
--     * a price is cleared (null) or changed to 0 or less, also on an inactive package;
--     * a NEW price is above 1,00,000 per plate or has more than 2 decimal places;
--     * a NEW dish list is not a list, has a dish with no name, a name over 120 characters,
--       a category over 80 characters, a type other than veg / nonveg / special, the same dish
--       twice, or more than 500 dishes.
--   Only NEW or CHANGED values are checked. An existing row that already has a 0 price or an empty
--   list is never re-checked: changing its name, order or description still works, and nothing
--   already stored is rewritten. Helm's own functions (trial start, the 0167 sample clone, demo
--   seed / clear, 0170 refresh) and SQL run by the owner do not run as anon / authenticated, so
--   they are unchanged. The 0173 free-trial "no new packages" refusal still fires first (trigger
--   name order), with its own message.
--   Additive + idempotent: create or replace function, trigger created only when missing.
--   No DROP of data, DELETE, UPDATE or TRUNCATE. Safe to run twice.
--   ROLLBACK (manual, only if ever needed): drop trigger zzzzz_menu_pkg_validate_0192 on
--   public.menu_templates; drop function public.tg_menu_pkg_validate_0192(). No data is touched.
-- ============================================================================

do $$ begin
  if to_regclass('public.menu_templates') is null then raise exception '0192: public.menu_templates is missing'; end if;
  if not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'menu_templates' and column_name = 'price_per_plate') then
    raise exception '0192: menu_templates.price_per_plate is missing'; end if;
  if not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'menu_templates' and column_name = 'dishes') then
    raise exception '0192: menu_templates.dishes is missing'; end if;
  if not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'menu_templates' and column_name = 'active') then
    raise exception '0192: menu_templates.active is missing'; end if;
end $$;

create or replace function public.tg_menu_pkg_validate_0192()
returns trigger language plpgsql set search_path = '' as $$
-- menu-pkg-validate-0192: SECURITY INVOKER on purpose (current_user = the app role). Only direct app
-- writes are checked; Helm's own SECURITY DEFINER functions and owner SQL keep working as before.
declare
  v_ins boolean := tg_op = 'INSERT';
  v_price_new boolean; v_dishes_new boolean; v_on boolean;
  v_n integer; v_bad integer; v_dup integer;
begin
  if current_user not in ('anon', 'authenticated') then return new; end if;
  v_price_new := v_ins or new.price_per_plate is distinct from old.price_per_plate;
  v_dishes_new := v_ins or new.dishes is distinct from old.dishes;
  v_on := coalesce(new.active, false) and (v_ins or not coalesce(old.active, false));   -- created active / switched on

  -- price ----------------------------------------------------------------------------------------
  if v_price_new and new.price_per_plate is null then
    raise exception 'Enter a price per plate. A package price cannot be cleared.' using errcode = '23514', hint = 'menu_pkg_invalid';
  end if;
  if v_price_new and not v_ins and new.price_per_plate <= 0 then
    raise exception 'Enter a price per plate above 0. A package price cannot be cleared or set to 0.' using errcode = '23514', hint = 'menu_pkg_invalid';
  end if;
  if coalesce(new.active, false) and (v_price_new or v_on) and coalesce(new.price_per_plate, 0) <= 0 then
    raise exception 'Enter a price per plate above 0 for an active package.' using errcode = '23514', hint = 'menu_pkg_invalid';
  end if;
  if v_price_new and new.price_per_plate > 100000 then
    raise exception 'Price per plate can be at most 1,00,000.' using errcode = '23514', hint = 'menu_pkg_invalid';
  end if;
  if v_price_new and new.price_per_plate <> round(new.price_per_plate, 2) then
    raise exception 'Price per plate can have at most 2 decimal places.' using errcode = '23514', hint = 'menu_pkg_invalid';
  end if;

  -- dishes ---------------------------------------------------------------------------------------
  if v_dishes_new then
    if new.dishes is null or jsonb_typeof(new.dishes) <> 'array' then
      raise exception 'The dish list must be a list of dishes.' using errcode = '23514', hint = 'menu_pkg_invalid';
    end if;
    v_n := jsonb_array_length(new.dishes);
    if v_n > 500 then
      raise exception 'A package can have at most 500 dishes.' using errcode = '23514', hint = 'menu_pkg_invalid';
    end if;
    -- a dish is a {n|name, c|category, k|kind} object, or (older rows) a plain name string
    select count(*) filter (where
             case jsonb_typeof(e.j)
               when 'string' then btrim(e.j #>> '{}') = '' or char_length(e.j #>> '{}') > 120
               when 'object' then btrim(coalesce(e.j ->> 'n', e.j ->> 'name', '')) = ''
                               or char_length(coalesce(e.j ->> 'n', e.j ->> 'name', '')) > 120
                               or char_length(coalesce(e.j ->> 'c', e.j ->> 'category', '')) > 80
                               or lower(coalesce(e.j ->> 'k', e.j ->> 'kind', 'veg')) not in ('veg', 'nonveg', 'special')
               else true end),
           count(*) - count(distinct lower(btrim(coalesce(e.j ->> 'c', e.j ->> 'category', ''))) || chr(1)
                                     || lower(btrim(case jsonb_typeof(e.j) when 'string' then e.j #>> '{}'
                                                         else coalesce(e.j ->> 'n', e.j ->> 'name', '') end)))
      into v_bad, v_dup
      from jsonb_array_elements(new.dishes) e(j);
    if v_bad > 0 then
      raise exception 'Every dish needs a name (at most 120 characters), a category of at most 80 characters and a type of veg, nonveg or special.'
        using errcode = '23514', hint = 'menu_pkg_invalid';
    end if;
    if v_dup > 0 then
      raise exception 'The same dish is in this package twice. Remove the duplicate.' using errcode = '23514', hint = 'menu_pkg_invalid';
    end if;
  end if;
  if coalesce(new.active, false) and (v_dishes_new or v_on)
     and (new.dishes is null or jsonb_typeof(new.dishes) <> 'array' or jsonb_array_length(new.dishes) = 0) then
    raise exception 'Add at least one dish to an active package.' using errcode = '23514', hint = 'menu_pkg_invalid';
  end if;
  return new;
end $$;
revoke all on function public.tg_menu_pkg_validate_0192() from public, anon, authenticated;

-- after zzzz_tl173_no_add (BEFORE triggers fire in name order): the free-trial refusal keeps its message
do $$ begin
  if not exists (select 1 from pg_trigger where tgrelid = 'public.menu_templates'::regclass
                  and tgname = 'zzzzz_menu_pkg_validate_0192' and not tgisinternal) then
    create trigger zzzzz_menu_pkg_validate_0192 before insert or update on public.menu_templates
      for each row execute function public.tg_menu_pkg_validate_0192();
  end if;
end $$;

notify pgrst, 'reload schema';
commit;

-- VERIFY (every row should say ok = true)
select item, ok from (values
  ('01 trigger function present', to_regprocedure('public.tg_menu_pkg_validate_0192()') is not null),
  ('02 trigger function is SECURITY INVOKER', not coalesce((select prosecdef from pg_proc where oid = to_regprocedure('public.tg_menu_pkg_validate_0192()')), true)),
  ('03 trigger function search_path pinned', coalesce((select proconfig::text from pg_proc where oid = to_regprocedure('public.tg_menu_pkg_validate_0192()')), '') like '%search_path=%'),
  ('04 one BEFORE INSERT OR UPDATE trigger on menu_templates', (select count(*) from pg_trigger where tgrelid = 'public.menu_templates'::regclass and tgname = 'zzzzz_menu_pkg_validate_0192' and not tgisinternal and tgenabled <> 'D' and (tgtype & 2) = 2 and (tgtype & 4) = 4 and (tgtype & 16) = 16) = 1),
  ('05 fires after the 0173 trial no-add trigger', not exists (select 1 from pg_trigger where tgrelid = 'public.menu_templates'::regclass and tgname = 'zzzz_tl173_no_add') or 'zzzz_tl173_no_add' < 'zzzzz_menu_pkg_validate_0192'),
  ('06 app roles cannot call the trigger function', not has_function_privilege('authenticated', 'public.tg_menu_pkg_validate_0192()', 'execute') and not has_function_privilege('anon', 'public.tg_menu_pkg_validate_0192()', 'execute')),
  ('07 existing rows untouched (count is informational, never changed by this file)', (select count(*) from public.menu_templates) >= 0)
) v(item, ok) order by item;

-- ##########################################################################################
-- RELEASE SECTION 19/28: APPLY-0194.sql
-- In plain words: Event group "Add people": staff / vendors / client as group contacts (nothing is sent).
-- ##########################################################################################
-- APPLY-0194.sql - paste into the Supabase SQL editor (staging first, then production).
-- Additive + idempotent: event group "Add people" (staff / vendors / client as group contacts, name only; nothing is sent). Safe to run twice.
begin;
-- 0194_event_group_people.sql - CANONICAL forward-only. REQUIRES 0016 (chat), 0035 (event groups),
-- 0041 (crew_members.profile_id), 0166 (_is_trial_org).
--
-- In plain words:
--   EVENT GROUP "ADD PEOPLE". An event group (the team chat of a confirmed event) could only hold
--   people who sign in to Helm (chat_members needs a login). The picker therefore listed only signed-in
--   teammates; in a free-trial studio that is usually nobody but the owner, so the staff, vendors and
--   client the owner ticked were never added and the group stayed empty.
--     1) New table chat_group_contacts: the staff (crew_members), vendors and the client of an event
--        group who do not sign in to Helm. It keeps only who they are (kind + their row id + name), not
--        their phone or e-mail. Members of the group can read it (row level security); nobody writes it
--        directly - only the RPCs below.
--     2) event_group_add_people(conversation, people jsonb): adds people to an event group the caller is
--        a member of. Each entry is {kind: user|staff|vendor|client, id}. A teammate (user) or a staff
--        member linked to a login becomes a real chat member; other staff, vendors and the client are
--        added as contacts. Names always come from the studio's own rows (never from the request), only
--        rows of the caller's studio are accepted, at most 200 entries. Nothing is sent to anyone (no
--        WhatsApp / SMS / e-mail) - in a free trial and outside it. Returns the counts.
--     3) event_group_remove_contact(conversation, contact): takes a contact off the group. The row is
--        kept and marked removed (removed_at), never deleted; adding the person again restores it.
--   Changes: 1 new table (+ 2 indexes, RLS, 1 read policy, the studio read-only guard trigger), 2 new functions. No existing table,
--   column, function, policy or row is changed. Additive + idempotent: safe to run twice. ASCII only.

do $$ begin
  if to_regclass('public.chat_conversations') is null or to_regclass('public.chat_members') is null
     or to_regprocedure('public.chat_is_member(uuid)') is null or to_regprocedure('public.chat_can_see(uuid)') is null then
    raise exception '0194: apply 0016 (chat) first'; end if;
  if to_regprocedure('public.create_event_group(uuid,uuid[])') is null then
    raise exception '0194: apply 0035 (event groups) first'; end if;
  if not exists (select 1 from information_schema.columns where table_schema = 'public'
                  and table_name = 'crew_members' and column_name = 'profile_id') then
    raise exception '0194: apply 0041 (crew_members.profile_id) first'; end if;
  if to_regprocedure('public._is_trial_org(uuid)') is null then
    raise exception '0194: apply 0166 (_is_trial_org) first'; end if;
end $$;

-- ---- 1) the contacts of an event group ------------------------------------------------------------
create table if not exists public.chat_group_contacts (
  id              uuid primary key default gen_random_uuid(),
  conversation_id uuid not null references public.chat_conversations(id) on delete cascade,
  org_id          uuid not null default public.current_org_id() references public.organizations(id) on delete cascade,
  kind            text not null check (kind in ('staff', 'vendor', 'client')),
  ref_id          uuid,
  ref_key         text not null,
  name            text not null check (char_length(name) between 1 and 120),
  added_by        uuid,
  created_at      timestamptz not null default now(),
  removed_at      timestamptz
);
create unique index if not exists chat_group_contacts_person_key
  on public.chat_group_contacts (conversation_id, kind, ref_key);
create index if not exists chat_group_contacts_org_idx on public.chat_group_contacts (org_id);

alter table public.chat_group_contacts enable row level security;
drop policy if exists chat_group_contacts_sel on public.chat_group_contacts;
create policy chat_group_contacts_sel on public.chat_group_contacts for select to authenticated
  using ( org_id = (select public.current_org_id()) and public.chat_can_see(conversation_id) );
revoke all on table public.chat_group_contacts from public;
do $$ begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on table public.chat_group_contacts from anon'; end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'revoke all on table public.chat_group_contacts from authenticated';
    execute 'grant select on table public.chat_group_contacts to authenticated'; end if;
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    execute 'grant all on table public.chat_group_contacts to service_role'; end if;
end $$;

-- ended-trial / suspended studios are read-only (the same 0045 guard every studio table has, 0136)
do $$ begin
  if to_regprocedure('public.tg_studio_read_only()') is not null then
    execute 'drop trigger if exists zzz_studio_read_only on public.chat_group_contacts';
    execute 'create trigger zzz_studio_read_only before insert or update or delete on public.chat_group_contacts for each row execute function public.tg_studio_read_only(''org_id'')';
  end if;
end $$;

-- ---- 2) add people to an event group --------------------------------------------------------------
create or replace function public.event_group_add_people(p_conversation uuid, p_people jsonb)
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
-- helm-0194-event-group-people
declare
  v_me uuid := auth.uid(); v_org uuid := public.current_org_id();
  c record; e jsonb; v_kind text; v_ref uuid; v_name text; v_prof uuid; v_rows integer;
  v_users integer := 0; v_contacts integer := 0; v_skipped integer := 0; v_names text[] := '{}'; v_email text;
begin
  if v_me is null or v_org is null or not public.has_area('quotes', 'view') then
    raise exception 'not authorized' using errcode = '42501';
  end if;
  select cc.id, cc.kind, cc.quote_id into c
    from public.chat_conversations cc where cc.id = p_conversation and cc.org_id = v_org;
  if c.id is null or not public.chat_is_member(p_conversation) then
    raise exception 'not authorized' using errcode = '42501';
  end if;
  if c.kind is distinct from 'group' or c.quote_id is null then
    raise exception 'People can be added this way only to an event group.' using errcode = '22023';
  end if;
  if p_people is null or jsonb_typeof(p_people) <> 'array' then
    raise exception 'people must be a list' using errcode = '22023';
  end if;
  if jsonb_array_length(p_people) > 200 then
    raise exception 'Add at most 200 people at a time.' using errcode = '22023';
  end if;

  for e in select x from jsonb_array_elements(p_people) as t(x) loop
    v_kind := case when jsonb_typeof(e) = 'object' then e ->> 'kind' end;
    v_ref := case when jsonb_typeof(e) = 'object'
                   and (e ->> 'id') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                  then (e ->> 'id')::uuid end;
    v_name := null; v_prof := null;
    if v_kind = 'user' then
      if v_ref is not null and v_ref <> v_me
         and exists (select 1 from public.profiles p where p.id = v_ref and p.org_id = v_org) then
        insert into public.chat_members (conversation_id, user_id, org_id) values (p_conversation, v_ref, v_org)
          on conflict do nothing;
        get diagnostics v_rows = row_count; v_users := v_users + v_rows; continue;
      end if;
      v_skipped := v_skipped + 1; continue;
    elsif v_kind = 'staff' then
      select cm.name, cm.profile_id into v_name, v_prof from public.crew_members cm
       where cm.id = v_ref and cm.org_id = v_org and cm.active;
      if v_name is null then v_skipped := v_skipped + 1; continue; end if;
      -- a staff member who signs in to Helm joins the chat itself
      if v_prof is not null and v_prof <> v_me
         and exists (select 1 from public.profiles p where p.id = v_prof and p.org_id = v_org) then
        insert into public.chat_members (conversation_id, user_id, org_id) values (p_conversation, v_prof, v_org)
          on conflict do nothing;
        get diagnostics v_rows = row_count; v_users := v_users + v_rows; continue;
      end if;
      if v_prof is not null and v_prof = v_me then v_skipped := v_skipped + 1; continue; end if;
    elsif v_kind = 'vendor' then
      select vv.name into v_name from public.vendors vv where vv.id = v_ref and vv.org_id = v_org and vv.active;
      if v_name is null then v_skipped := v_skipped + 1; continue; end if;
    elsif v_kind = 'client' then
      v_ref := null;
      select coalesce(nullif(btrim(q.client ->> 'name'), ''), 'Client') into v_name
        from public.quotes q where q.id = c.quote_id and q.org_id = v_org;
      if v_name is null then v_skipped := v_skipped + 1; continue; end if;
    else
      v_skipped := v_skipped + 1; continue;
    end if;
    v_name := left(btrim(regexp_replace(v_name, '[[:cntrl:]]', ' ', 'g')), 120);
    if v_name = '' then v_name := initcap(v_kind); end if;
    insert into public.chat_group_contacts (conversation_id, org_id, kind, ref_id, ref_key, name, added_by)
      values (p_conversation, v_org, v_kind, v_ref, coalesce(v_ref::text, v_kind), v_name, v_me)
      on conflict (conversation_id, kind, ref_key) do update
        set name = excluded.name, removed_at = null, added_by = excluded.added_by
        where public.chat_group_contacts.removed_at is not null or public.chat_group_contacts.name is distinct from excluded.name;
    get diagnostics v_rows = row_count;
    if v_rows > 0 then v_contacts := v_contacts + 1; v_names := array_append(v_names, v_name); end if;
  end loop;

  if v_users + v_contacts > 0 then
    update public.chat_conversations set last_message_at = coalesce(last_message_at, now()) where id = p_conversation;
    select p.email into v_email from public.profiles p where p.id = v_me;
    insert into public.audit_log (actor, actor_email, action, entity, entity_id, quote_id, org_id, changed)
      values (v_me, v_email, 'chat.event_group.add_people', 'chat_conversations', p_conversation::text, c.quote_id, v_org,
              jsonb_build_object('users', v_users, 'contacts', v_contacts, 'names', to_jsonb(v_names)));
  end if;
  return jsonb_build_object('users', v_users, 'contacts', v_contacts, 'skipped', v_skipped,
                            'trial', coalesce(public._is_trial_org(v_org), false), 'messages_sent', 0);
end $$;

-- ---- 3) take a contact off an event group (kept, marked removed) ----------------------------------
create or replace function public.event_group_remove_contact(p_conversation uuid, p_contact uuid)
returns boolean language plpgsql volatile security definer set search_path = '' as $$
-- helm-0194-event-group-people
declare v_me uuid := auth.uid(); v_org uuid := public.current_org_id(); v_rows integer; v_q uuid; v_email text;
begin
  if v_me is null or v_org is null or not public.has_area('quotes', 'view')
     or not public.chat_is_member(p_conversation) then
    raise exception 'not authorized' using errcode = '42501';
  end if;
  update public.chat_group_contacts g set removed_at = now()
   where g.id = p_contact and g.conversation_id = p_conversation and g.org_id = v_org and g.removed_at is null;
  get diagnostics v_rows = row_count;
  if v_rows > 0 then
    select cc.quote_id into v_q from public.chat_conversations cc where cc.id = p_conversation;
    select p.email into v_email from public.profiles p where p.id = v_me;
    insert into public.audit_log (actor, actor_email, action, entity, entity_id, quote_id, org_id, changed)
      values (v_me, v_email, 'chat.event_group.remove_contact', 'chat_group_contacts', p_contact::text, v_q, v_org, '{}'::jsonb);
  end if;
  return v_rows > 0;
end $$;

revoke all on function public.event_group_add_people(uuid, jsonb) from public;
revoke all on function public.event_group_remove_contact(uuid, uuid) from public;
do $$ begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on function public.event_group_add_people(uuid, jsonb) from anon';
    execute 'revoke all on function public.event_group_remove_contact(uuid, uuid) from anon'; end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'grant execute on function public.event_group_add_people(uuid, jsonb) to authenticated';
    execute 'grant execute on function public.event_group_remove_contact(uuid, uuid) to authenticated'; end if;
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    execute 'grant execute on function public.event_group_add_people(uuid, jsonb) to service_role';
    execute 'grant execute on function public.event_group_remove_contact(uuid, uuid) to service_role'; end if;
end $$;
commit;

-- VERIFY (every row should say ok = true)
select item, ok from (values
  ('01 chat_group_contacts exists with RLS on', to_regclass('public.chat_group_contacts') is not null
      and (select c.relrowsecurity from pg_class c where c.oid = 'public.chat_group_contacts'::regclass)),
  ('02 read policy for group members only', exists (select 1 from pg_policy p where p.polrelid = 'public.chat_group_contacts'::regclass
      and p.polname = 'chat_group_contacts_sel' and p.polcmd = 'r')),
  ('03 app roles cannot write the table directly', not has_table_privilege('authenticated', 'public.chat_group_contacts', 'INSERT')
      and not has_table_privilege('authenticated', 'public.chat_group_contacts', 'UPDATE')
      and not has_table_privilege('authenticated', 'public.chat_group_contacts', 'DELETE')
      and not has_table_privilege('anon', 'public.chat_group_contacts', 'SELECT')),
  ('04 no phone / e-mail column kept', not exists (select 1 from information_schema.columns where table_schema = 'public'
      and table_name = 'chat_group_contacts' and column_name in ('phone', 'email'))),
  ('05 add / remove RPCs for signed-in users only', has_function_privilege('authenticated', 'public.event_group_add_people(uuid,jsonb)', 'execute')
      and has_function_privilege('authenticated', 'public.event_group_remove_contact(uuid,uuid)', 'execute')
      and not has_function_privilege('anon', 'public.event_group_add_people(uuid,jsonb)', 'execute')
      and not has_function_privilege('anon', 'public.event_group_remove_contact(uuid,uuid)', 'execute')),
  ('06 add RPC sends nothing', position('''messages_sent'', 0' in pg_get_functiondef('public.event_group_add_people(uuid,jsonb)'::regprocedure)) > 0),
  ('07 remove keeps the row (removed_at)', position('set removed_at = now()' in pg_get_functiondef('public.event_group_remove_contact(uuid,uuid)'::regprocedure)) > 0),
  ('08 studio read-only guard on the table', exists (select 1 from pg_trigger t where t.tgrelid = 'public.chat_group_contacts'::regclass
      and t.tgname = 'zzz_studio_read_only')),
  ('09 existing event group functions unchanged', to_regprocedure('public.create_event_group(uuid,uuid[])') is not null
      and to_regprocedure('public.chat_add_members(uuid,uuid[])') is not null)
) v(item, ok) order by item;

-- ##########################################################################################
-- RELEASE SECTION 20/28: APPLY-0195.sql
-- In plain words: Invitation website "Send to client" (queued e-mail / WhatsApp; free trial = skipped).
-- ##########################################################################################
-- APPLY-0195.sql - paste into the Supabase SQL editor (staging first, then production).
-- Additive + idempotent: invitation website "Send to client" (queued e-mail / WhatsApp; free trial = skipped, nothing sent). Safe to run twice.
begin;
-- 0195_invite_site_share.sql - CANONICAL forward-only. REQUIRES phase87 (event_sites), 0078 (comms_outbox,
-- _comms_cfg, _comms_quote_live), 0151 (wa_proposal_optins, _wa151_e164), 0155 (_wa_opted_out, claim wrapper),
-- 0166 (_sample_outbound_blocked + the trial outbox skip trigger on comms_outbox).
--
-- In plain words: "Send to client" on the Invitation Studio.
--   1) event_site_send(site, channel, to, opt_in, consent_text): the studio (quotes EDIT, own studio) sends the
--      PUBLISHED invitation website link to the client by e-mail or WhatsApp. The message is fixed text built
--      here ("Hi <client>, here is your invitation website:" + the link); the studio only picks the channel
--      and the address (pre-filled from the quote, editable). It is QUEUED in comms_outbox (purpose
--      'invite_site') and sent by comms-dispatch like payment reminders. Rules:
--        * the site must be published and its link still open; the event not cancelled / closed
--        * WhatsApp: the client's opt-in must be on record for that number (the tick is stored in
--          wa_proposal_optins with who / when), a number that replied STOP is refused, and the studio
--          must have its WhatsApp number set up (Messages settings)
--        * caps: 10 sends per invitation per day, 5 different recipients per invitation per day,
--          60 per studio per hour
--        * FREE TRIAL / sample studio / demo event: nothing is sent - the row is stored as 'skipped'
--          (the 0166 trigger does this for a trial studio on every comms_outbox insert; demo events are
--          skipped here) and the answer says { status: 'skipped', reason: 'free_trial' | 'demo' }
--      Log: audit_log 'event_site.link_sent' (masked address) + the quote's activity (notifications).
--   2) event_site_send_log(site): the last 10 sends of this invitation (masked address, status).
--   3) comms_outbox_claim: wrapper (the previous one is kept as comms_outbox_claim__pre0195) that first
--      hands out 'invite_site' rows after re-checking them (still published, same link, event live, not a
--      trial, WhatsApp: STOP + studio number), then the previous claim for everything else.
--   4) comms_outbox purpose check widened with 'invite_site' (every existing value kept).
--   5) AFTER UPDATE trigger: when an 'invite_site' row is finally sent / failed / skipped, one activity row.
--   The link itself is never stored as a URL: the row carries the path (i/<slug> or <studio>/invite/<slug>)
--   and comms-dispatch joins it to its own APP_URL. A dispatcher that does not know 'invite_site' yet finds
--   no text and marks the row skipped (fails closed - nothing half-written is sent).
-- Additive + idempotent: 3 new functions, 1 wrapper (original kept), 1 trigger, 1 CHECK widened. No row is
-- changed or deleted. Safe to run twice. ASCII only.

do $$ begin
  if to_regclass('public.event_sites') is null or to_regclass('public.comms_outbox') is null
     or to_regclass('public.wa_proposal_optins') is null then
    raise exception '0195: apply phase87 + 0078 + 0151 first'; end if;
  if to_regprocedure('public._sample_outbound_blocked(uuid,text)') is null or to_regprocedure('public._wa_opted_out(text,uuid)') is null
     or to_regprocedure('public._wa151_e164(text,text)') is null or to_regprocedure('public._comms_cfg(uuid)') is null
     or to_regprocedure('public._comms_quote_live(uuid)') is null or to_regprocedure('public.comms_outbox_claim(integer)') is null
     or to_regprocedure('public.event_site_live_until(uuid)') is null or to_regprocedure('public._comms_country(uuid)') is null
     or to_regclass('public.audit_log') is null or to_regclass('public.notifications') is null then
    raise exception '0195: apply 0022 + 0078 + 0151 + 0155 + 0166 first'; end if;
end $$;

-- ---- 4) purpose check: keep every existing value, add 'invite_site' -----------------------------------
do $$
declare c record; v_vals text[]; v_list text;
begin
  select con.conname, pg_get_constraintdef(con.oid) as def into c
    from pg_constraint con
   where con.conrelid = 'public.comms_outbox'::regclass and con.contype = 'c'
     and pg_get_constraintdef(con.oid) like '%purpose%' and pg_get_constraintdef(con.oid) like '%pay_reminder%'
   order by con.conname limit 1;
  if c.conname is not null and position('invite_site' in c.def) > 0 then return; end if;
  if c.conname is not null then
    select array_agg(distinct m[1] order by m[1]) into v_vals from regexp_matches(c.def, '''([a-z_]+)''', 'g') m;
  end if;
  v_vals := coalesce(v_vals, array['follow_up', 'pay_reminder', 'wa_forward']::text[]);
  if not ('invite_site' = any (v_vals)) then v_vals := v_vals || 'invite_site'::text; end if;
  select string_agg(quote_literal(x), ', ' order by x) into v_list from unnest(v_vals) x;
  if c.conname is not null then execute format('alter table public.comms_outbox drop constraint %I', c.conname); end if;
  execute format('alter table public.comms_outbox add constraint comms_outbox_purpose_check check (purpose in (%s))', v_list);
end $$;

create index if not exists comms_outbox_invite_site_idx195 on public.comms_outbox ((payload ->> 'site_id'), created_at)
  where purpose = 'invite_site';

-- ---- helpers (internal) --------------------------------------------------------------------------------
-- the public path of a site's link (same rule as the app: /<studio link name>/invite/<slug>, else /i/<slug>)
create or replace function public._is195_link_path(p_site uuid)
returns text language sql stable security definer set search_path = '' as $$
  -- invite-share-0195
  select case when s.slug is null or s.slug !~ '^[A-Za-z0-9][A-Za-z0-9_-]{0,199}$' then null
              when coalesce(o.public_slug, '') ~ '^[a-z0-9-]{3,40}$' then o.public_slug || '/invite/' || s.slug
              else 'i/' || s.slug end
    from public.event_sites s left join public.organizations o on o.id = s.org_id
   where s.id = p_site;
$$;

create or replace function public._is195_mask(p_channel text, p_to text)
returns text language sql immutable set search_path = '' as $$
  -- invite-share-0195: a***@b.com / +91******3210
  select case when p_channel = 'email' and position('@' in coalesce(p_to, '')) > 1
              then left(p_to, 1) || '***' || substr(p_to, position('@' in p_to))
              when p_channel = 'whatsapp' and length(coalesce(p_to, '')) >= 6
              then '+' || left(p_to, 2) || repeat('*', greatest(length(p_to) - 6, 0)) || right(p_to, 4)
              else '***' end;
$$;

-- ---- 1) studio: send the invitation link -------------------------------------------------------------
create or replace function public.event_site_send(p_site uuid, p_channel text, p_to text,
                                                  p_opt_in boolean default false, p_consent_text text default null)
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
-- invite-share-0195
declare
  v_org uuid := public.current_org_id(); s record; q record; v_to text; v_e164 text; v_dial text; v_path text;
  v_until timestamptz; v_cfg jsonb; v_blocked boolean; v_reason text; v_opt boolean; v_name text; v_studio text;
  v_body text; v_id uuid; v_status text; v_n integer; v_key text; v_client_to boolean;
begin
  if auth.uid() is null or v_org is null or not coalesce(public.has_area('quotes', 'edit'), false) then
    raise exception 'not authorized' using errcode = '42501'; end if;
  if p_channel is null or p_channel not in ('email', 'whatsapp') then
    raise exception 'choose Email or WhatsApp' using errcode = '22023'; end if;
  select x.id, x.org_id, x.quote_id, x.status, x.slug into s from public.event_sites x where x.id = p_site and x.org_id = v_org;
  if s.id is null then raise exception 'not authorized' using errcode = '42501'; end if;
  if s.status is distinct from 'published' then
    raise exception 'Publish the invitation first, then send it.' using errcode = 'P0001', hint = 'not_published'; end if;
  select x.id, x.org_id, x.client, x.is_demo, x.tax_snapshot into q from public.quotes x where x.id = s.quote_id and x.org_id = v_org;
  if q.id is null then raise exception 'not authorized' using errcode = '42501'; end if;
  if not public._comms_quote_live(q.id) then
    raise exception 'This event is closed or cancelled - nothing can be sent for it.' using errcode = 'P0001', hint = 'event_closed'; end if;
  v_until := public.event_site_live_until(s.id);
  if v_until is not null and v_until <= now() then
    raise exception 'This invitation has ended - change the event date to reopen it first.' using errcode = 'P0001', hint = 'site_ended'; end if;
  v_path := public._is195_link_path(s.id);
  if v_path is null then raise exception 'Publish the invitation first, then send it.' using errcode = 'P0001', hint = 'not_published'; end if;

  -- recipient (pre-filled from the quote in the app, editable): format checked here
  if p_channel = 'email' then
    v_to := lower(btrim(coalesce(p_to, '')));
    if v_to !~ '^[^\s@<>"'',;:\\]{1,64}@[A-Za-z0-9.-]{1,190}\.[A-Za-z]{2,24}$' then
      raise exception 'Enter a valid e-mail address.' using errcode = '22023'; end if;
    v_client_to := v_to = lower(btrim(coalesce(q.client ->> 'email', '')));
  else
    v_dial := case upper(coalesce(nullif(q.tax_snapshot ->> 'country', ''), public._comms_country(v_org)))
                when 'AE' then '971' when 'US' then '1' else '91' end;
    v_e164 := public._wa151_e164(p_to, v_dial);
    if v_e164 is null then raise exception 'Enter a valid mobile number with country code.' using errcode = '22023'; end if;
    v_to := substr(v_e164, 2);
    v_client_to := v_e164 is not distinct from public._wa151_e164(q.client ->> 'phone', v_dial);
  end if;

  v_blocked := public._sample_outbound_blocked(v_org, v_to);
  v_reason := case when v_blocked then 'free_trial' when coalesce(q.is_demo, false) then 'demo' end;

  if p_channel = 'whatsapp' then
    if public._wa_opted_out(v_to, v_org) then
      raise exception 'This number replied STOP to WhatsApp messages - send the link another way.' using errcode = 'HL451'; end if;
    if p_opt_in is true then
      if coalesce(btrim(p_consent_text), '') = '' or char_length(p_consent_text) > 500 then
        raise exception 'opt-in wording is required' using errcode = '22023'; end if;
      insert into public.wa_proposal_optins(org_id, quote_id, phone_e164, opted_in, consent_text, source, recorded_by)
        values (v_org, q.id, v_e164, true, p_consent_text, 'invite_site_send', auth.uid());
    end if;
    select o.opted_in into v_opt from public.wa_proposal_optins o
     where o.quote_id = q.id and o.phone_e164 = v_e164 order by o.recorded_at desc, o.id desc limit 1;
    if v_opt is not true then
      raise exception 'Tick "Client agreed to receive WhatsApp messages" first.' using errcode = 'P0001', hint = 'opt_in'; end if;
    v_cfg := public._comms_cfg(v_org);
    if v_reason is null and coalesce(v_cfg ->> 'studio_whatsapp', '') !~ '^[0-9]{8,15}$' then
      raise exception 'WhatsApp sending is not set up for your studio yet - use Email or Copy link.' using errcode = 'P0001', hint = 'wa_not_setup'; end if;
  end if;

  -- double click: the same message to the same address in the last 2 minutes is not queued again
  perform pg_advisory_xact_lock(hashtextextended('helm:invite-send:' || s.id::text, 0));
  if exists (select 1 from public.comms_outbox c
              where c.purpose = 'invite_site' and c.payload ->> 'site_id' = s.id::text and c.channel = p_channel
                and c.recipient = v_to and c.created_at > now() - interval '2 minutes') then
    return jsonb_build_object('status', 'already_queued', 'channel', p_channel, 'masked', public._is195_mask(p_channel, v_to));
  end if;
  -- caps (counted on every row, skipped ones too, so a trial cannot loop either)
  select count(*) into v_n from public.comms_outbox c
   where c.purpose = 'invite_site' and c.payload ->> 'site_id' = s.id::text and c.created_at > now() - interval '1 day';
  if v_n >= 10 then raise exception 'This invitation was sent 10 times today - try again tomorrow.' using errcode = 'HL429'; end if;
  select count(distinct c.recipient) into v_n from public.comms_outbox c
   where c.purpose = 'invite_site' and c.payload ->> 'site_id' = s.id::text and c.created_at > now() - interval '1 day'
     and c.recipient <> v_to;
  if v_n >= 5 then raise exception 'This invitation went to 5 different people today - try again tomorrow.' using errcode = 'HL429'; end if;
  select count(*) into v_n from public.comms_outbox c
   where c.org_id = v_org and c.purpose = 'invite_site' and c.created_at > now() - interval '1 hour';
  if v_n >= 60 then raise exception 'Sending limit reached for your studio - try again in an hour.' using errcode = 'HL429'; end if;

  v_name := coalesce(nullif(left(regexp_replace(btrim(coalesce(q.client ->> 'name', '')), '\s+', ' ', 'g'), 60), ''), 'there');
  select left(o.name, 60) into v_studio from public.organizations o where o.id = v_org;
  v_body := 'Hi ' || v_name || ', here is your invitation website:';
  v_key := 'invite:' || s.id || ':' || gen_random_uuid();
  insert into public.comms_outbox(org_id, quote_id, purpose, channel, recipient, payload, dedupe_key, created_by, status, created_at)
    values (v_org, q.id, 'invite_site', p_channel, v_to,
            jsonb_build_object('site_id', s.id, 'link_path', v_path, 'body', v_body, 'client', v_name,
                               'studio', coalesce(v_studio, ''), 'subject', 'Your invitation website from ' || coalesce(nullif(v_studio, ''), 'your planner'),
                               'to_is_client', v_client_to),
            v_key, auth.uid(), case when v_reason = 'demo' then 'skipped' else 'pending' end, clock_timestamp())
    on conflict (dedupe_key) do nothing
    returning id, status into v_id, v_status;
  if v_id is null then
    return jsonb_build_object('status', 'already_queued', 'channel', p_channel, 'masked', public._is195_mask(p_channel, v_to));
  end if;
  if v_status = 'skipped' then
    if v_reason is null then v_reason := 'not_sent'; end if;
    update public.comms_outbox set sent_at = now() where id = v_id and sent_at is null;   -- finished (never handed out)
  end if;

  insert into public.audit_log(actor, action, entity, entity_id, quote_id, changed, org_id)
    values (auth.uid(), 'event_site.link_sent', 'event_sites', s.id::text, q.id,
            jsonb_build_object('channel', p_channel, 'to', public._is195_mask(p_channel, v_to),
                               'status', case when v_status = 'skipped' then 'skipped' else 'queued' end,
                               'reason', v_reason, 'to_is_client', v_client_to), v_org);
  if v_status = 'skipped' then
    insert into public.notifications(quote_id, channel, recipient, kind, status, detail, org_id)
      values (q.id, p_channel, v_to, 'invite_site_link', 'suppressed',
              jsonb_build_object('via', 'invite_site', 'skipped', v_reason, 'outbox_id', v_id), v_org);
  end if;
  return jsonb_build_object('status', case when v_status = 'skipped' then 'skipped' else 'queued' end,
                            'reason', v_reason, 'channel', p_channel, 'masked', public._is195_mask(p_channel, v_to), 'id', v_id);
end $$;

-- ---- 2) studio: what was sent for this invitation ------------------------------------------------------
create or replace function public.event_site_send_log(p_site uuid)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
-- invite-share-0195
declare v_org uuid := public.current_org_id();
begin
  if auth.uid() is null or v_org is null or not coalesce(public.has_area('quotes', 'view'), false) then
    raise exception 'not authorized' using errcode = '42501'; end if;
  if not exists (select 1 from public.event_sites s where s.id = p_site and s.org_id = v_org) then
    raise exception 'not authorized' using errcode = '42501'; end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object('at', x.created_at, 'channel', x.channel, 'to', public._is195_mask(x.channel, x.recipient),
                                        'status', case when x.status = 'pending' then 'queued' else x.status end,
                                        'sent_at', x.sent_at) order by x.created_at desc, x.id)
      from (select c.* from public.comms_outbox c
             where c.org_id = v_org and c.purpose = 'invite_site' and c.payload ->> 'site_id' = p_site::text
             order by c.created_at desc limit 10) x), '[]'::jsonb);
end $$;

-- ---- 3) dispatcher claim: invitation rows first (re-checked), then the previous claim ------------------
do $$ begin
  if to_regprocedure('public.comms_outbox_claim__pre0195(integer)') is null then
    alter function public.comms_outbox_claim(integer) rename to comms_outbox_claim__pre0195;
  end if;
end $$;

create or replace function public.comms_outbox_claim(p_limit integer default 25)
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
-- invite-share-0195: 'invite_site' rows (re-checked here), then the previous claim (0155 -> 0092) for the rest
declare r record; v_lim integer := greatest(1, least(coalesce(p_limit, 25), 100)); v_n integer := 0; v_out jsonb := '[]'::jsonb;
        v_ok boolean; v_site record; v_cfg jsonb;
begin
  update public.comms_outbox set status = 'failed', sent_at = now()
   where purpose = 'invite_site' and sent_at is null and attempts >= 5;
  update public.comms_outbox set status = 'skipped', sent_at = now()
   where purpose = 'invite_site' and sent_at is null and created_at < now() - interval '3 days';
  for r in select c.* from public.comms_outbox c
     where c.purpose = 'invite_site' and c.sent_at is null and c.status = 'pending'
       and (c.claimed_at is null or c.claimed_at < now() - interval '10 minutes')
     order by c.created_at limit v_lim for update skip locked
  loop
    select s.id, s.org_id, s.status into v_site from public.event_sites s where s.id::text = r.payload ->> 'site_id';
    v_ok := v_site.id is not null and v_site.org_id = r.org_id and v_site.status = 'published'
            and public._is195_link_path(v_site.id) is not distinct from (r.payload ->> 'link_path')
            and coalesce(public.event_site_live_until(v_site.id) > now(), true)
            and public._comms_quote_live(r.quote_id)
            and not coalesce((select q.is_demo from public.quotes q where q.id = r.quote_id), false)
            and not public._sample_outbound_blocked(r.org_id, r.recipient);
    if v_ok and r.channel = 'whatsapp' then
      v_cfg := public._comms_cfg(r.org_id);
      v_ok := coalesce(v_cfg ->> 'studio_whatsapp', '') ~ '^[0-9]{8,15}$' and not public._wa_opted_out(r.recipient, r.org_id);
    end if;
    if not coalesce(v_ok, false) then
      update public.comms_outbox set status = 'skipped', sent_at = now() where id = r.id;
      continue;
    end if;
    update public.comms_outbox set claimed_at = now(), attempts = attempts + 1 where id = r.id;
    v_out := v_out || jsonb_build_array(jsonb_build_object('id', r.id, 'purpose', r.purpose, 'channel', r.channel,
      'to', r.recipient, 'payload', r.payload));
    v_n := v_n + 1;
  end loop;
  if v_n < v_lim then
    v_out := v_out || coalesce(public.comms_outbox_claim__pre0195(v_lim - v_n), '[]'::jsonb);
  end if;
  return v_out;
end $$;

-- ---- 5) activity row when an invitation send is finished -----------------------------------------------
create or replace function public._is195_tg_outbox_done()
returns trigger language plpgsql security definer set search_path = '' as $$
-- invite-share-0195
begin
  -- only rows that were queued (a row stored as skipped at send time is logged by event_site_send)
  if new.purpose = 'invite_site' and old.status = 'pending' and old.sent_at is null and new.sent_at is not null
     and new.status in ('sent', 'failed', 'skipped') and new.quote_id is not null then
    begin
      insert into public.notifications(quote_id, channel, recipient, kind, status, detail, org_id)
        values (new.quote_id, new.channel, new.recipient, 'invite_site_link',
                case new.status when 'sent' then 'sent' when 'failed' then 'failed' else 'suppressed' end,
                jsonb_build_object('via', 'invite_site', 'outbox_id', new.id), new.org_id);
    exception when others then raise warning 'invite-share-0195: activity row skipped (%)', sqlstate;
    end;
  end if;
  return null;
end $$;

do $$ begin
  if not exists (select 1 from pg_trigger where tgrelid = 'public.comms_outbox'::regclass and tgname = 'zzzz_is195_done') then
    create trigger zzzz_is195_done after update of status, sent_at on public.comms_outbox
      for each row execute function public._is195_tg_outbox_done();
  end if;
end $$;

-- ---- privileges ------------------------------------------------------------------------------------------
do $$
declare f text;
begin
  foreach f in array array['public._is195_link_path(uuid)', 'public._is195_mask(text, text)', 'public._is195_tg_outbox_done()',
                           'public.comms_outbox_claim(integer)', 'public.comms_outbox_claim__pre0195(integer)',
                           'public.event_site_send(uuid, text, text, boolean, text)', 'public.event_site_send_log(uuid)'] loop
    execute format('revoke all on function %s from public', f);
    if exists (select 1 from pg_roles where rolname = 'anon') then execute format('revoke all on function %s from anon', f); end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then execute format('revoke all on function %s from authenticated', f); end if;
  end loop;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    grant execute on function public.event_site_send(uuid, text, text, boolean, text) to authenticated;
    grant execute on function public.event_site_send_log(uuid) to authenticated;
  end if;
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    grant execute on function public.comms_outbox_claim(integer) to service_role;
    grant execute on function public.comms_outbox_claim__pre0195(integer) to service_role;
  end if;
end $$;
commit;

-- VERIFY (every row should say ok = true)
select item, ok from (values
  ('01 event_site_send + log exist, app (signed-in) only',
      to_regprocedure('public.event_site_send(uuid,text,text,boolean,text)') is not null
      and has_function_privilege('authenticated', 'public.event_site_send(uuid,text,text,boolean,text)', 'execute')
      and not has_function_privilege('anon', 'public.event_site_send(uuid,text,text,boolean,text)', 'execute')
      and has_function_privilege('authenticated', 'public.event_site_send_log(uuid)', 'execute')
      and not has_function_privilege('anon', 'public.event_site_send_log(uuid)', 'execute')),
  ('02 send refuses unpublished + uses the trial outbound guard + STOP + caps',
      position('''published''' in pg_get_functiondef('public.event_site_send(uuid,text,text,boolean,text)'::regprocedure)) > 0
      and position('_sample_outbound_blocked' in pg_get_functiondef('public.event_site_send(uuid,text,text,boolean,text)'::regprocedure)) > 0
      and position('_wa_opted_out' in pg_get_functiondef('public.event_site_send(uuid,text,text,boolean,text)'::regprocedure)) > 0
      and position('HL429' in pg_get_functiondef('public.event_site_send(uuid,text,text,boolean,text)'::regprocedure)) > 0),
  ('03 trial outbox skip trigger still on comms_outbox (0166)',
      exists (select 1 from pg_trigger where tgrelid = 'public.comms_outbox'::regclass and tgname = 'zzzz_ts166_outbox_skip')),
  ('04 claim wrapper: invite rows re-checked, previous claim kept (service role only)',
      to_regprocedure('public.comms_outbox_claim__pre0195(integer)') is not null
      -- (after APPLY-0200 the 0195 wrapper sits one level down, as comms_outbox_claim__pre0200)
      and (position('comms_outbox_claim__pre0195' in pg_get_functiondef('public.comms_outbox_claim(integer)'::regprocedure)) > 0
           or position('comms_outbox_claim__pre0195' in coalesce(pg_get_functiondef(to_regprocedure('public.comms_outbox_claim__pre0200(integer)')), '')) > 0)
      and has_function_privilege('service_role', 'public.comms_outbox_claim(integer)', 'execute')
      and not has_function_privilege('authenticated', 'public.comms_outbox_claim(integer)', 'execute')
      and not has_function_privilege('authenticated', 'public.comms_outbox_claim__pre0195(integer)', 'execute')),
  ('05 purpose CHECK keeps pay_reminder / follow_up / wa_forward and adds invite_site',
      (select pg_get_constraintdef(c.oid) from pg_constraint c where c.conrelid = 'public.comms_outbox'::regclass and c.conname = 'comms_outbox_purpose_check')
        ~ 'follow_up' and (select pg_get_constraintdef(c.oid) from pg_constraint c where c.conrelid = 'public.comms_outbox'::regclass and c.conname = 'comms_outbox_purpose_check') ~ 'invite_site'
      and (select pg_get_constraintdef(c.oid) from pg_constraint c where c.conrelid = 'public.comms_outbox'::regclass and c.conname = 'comms_outbox_purpose_check') ~ 'pay_reminder'
      and (select pg_get_constraintdef(c.oid) from pg_constraint c where c.conrelid = 'public.comms_outbox'::regclass and c.conname = 'comms_outbox_purpose_check') ~ 'wa_forward'),
  ('06 activity trigger present', exists (select 1 from pg_trigger where tgrelid = 'public.comms_outbox'::regclass and tgname = 'zzzz_is195_done')),
  ('07 internal helpers not callable by the app', not has_function_privilege('authenticated', 'public._is195_link_path(uuid)', 'execute')
      and not has_function_privilege('anon', 'public._is195_mask(text,text)', 'execute')),
  ('08 no trial studio has a sendable invite row', not exists (select 1 from public.comms_outbox c where c.purpose = 'invite_site'
      and c.status = 'pending' and public._is_trial_org(c.org_id)))
) v(item, ok) order by item;

-- ##########################################################################################
-- RELEASE SECTION 21/28: APPLY-0196.sql
-- In plain words: Budget & margin from the client's requirements (4 nullable columns on event_costs, no row changed).
-- ##########################################################################################
-- APPLY-0196.sql - paste into the Supabase SQL editor (staging first, then production).
-- Additive + idempotent: 4 nullable budget-planning columns on event_costs + unique (quote_id, requirement_key) index + same-studio vendor guard. No row changed. Safe to run twice.
begin;
-- 0196_budget_from_requirements.sql - CANONICAL forward-only.
-- REQUIRES base event_costs / vendors / quotes (org_id + tg_org_from_quote), 0026 (money CHECK naming).
--
-- In plain words:
--   BUDGET FROM REQUIREMENTS. The event's Budget & margin page now builds its cost lines from the
--   client's requirements (quote step 3: Must-have / Nice-to-have / Optional) plus standard lines
--   most events need (venue, catering, chairs, decor, sound & lights, staff, logistics, contingency).
--   The page itself does the matching; the database only needs four new, NULLABLE columns on the
--   existing cost line table (public.event_costs):
--     requirement_key  which requirement / standard line a row came from ('req:<name>' or 'std:<id>')
--     priority         that requirement's priority when the row was made (mandatory / nice / optional)
--     quoted           what the client is quoted for this line (prefilled from the quote's own lines)
--     vendor_id        the vendor chosen for this line (a vendor of the SAME studio only)
--   * One unique index on (quote_id, requirement_key): pulling requirements again (reload, two tabs)
--     can never create a second row for the same requirement. Rows without a key (every existing
--     row, and lines typed by hand) are NULL and never collide, so nothing existing is affected.
--   * A trigger refuses a vendor_id that belongs to another studio (cross-tenant guard).
--   * Money: quoted is NULL or finite, >= 0 and < 1e12 (same rule as estimated / actual, 0026).
--   Nothing is updated or deleted: no existing row changes, totals / P&L are unchanged (they read
--   estimated / actual only). Not a trial cap table (0173 caps leads / quotes / inventory /
--   vendors / staff / venues only), so budget lines work in a free trial.
--   Additive + idempotent: add column if not exists, constraints / indexes by name if missing,
--   create or replace, drop trigger if exists + create. No DROP of data, DELETE or TRUNCATE. ASCII only.
-- ============================================================================

do $$ begin
  if to_regclass('public.event_costs') is null then raise exception '0196: public.event_costs is missing'; end if;
  if to_regclass('public.vendors') is null then raise exception '0196: public.vendors is missing'; end if;
  if not exists (select 1 from information_schema.columns where table_schema = 'public'
                 and table_name = 'event_costs' and column_name = 'org_id') then
    raise exception '0196: event_costs.org_id is missing (multitenant base)'; end if;
end $$;

alter table public.event_costs add column if not exists requirement_key text;
alter table public.event_costs add column if not exists priority text;
alter table public.event_costs add column if not exists quoted numeric;
alter table public.event_costs add column if not exists vendor_id uuid;

do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'event_costs_requirement_key_0196_chk'
                  and conrelid = 'public.event_costs'::regclass) then
    alter table public.event_costs add constraint event_costs_requirement_key_0196_chk
      check (requirement_key is null or (length(requirement_key) between 5 and 300 and requirement_key ~ '^(req|std):')) not valid;
  end if;
  if not exists (select 1 from pg_constraint where conname = 'event_costs_priority_0196_chk'
                  and conrelid = 'public.event_costs'::regclass) then
    alter table public.event_costs add constraint event_costs_priority_0196_chk
      check (priority is null or priority in ('mandatory', 'nice', 'optional')) not valid;
  end if;
  -- same name pattern as 0026 (<table>_<column>_finite_chk); NULL passes
  if not exists (select 1 from pg_constraint where conname = 'event_costs_quoted_finite_chk'
                  and conrelid = 'public.event_costs'::regclass) then
    alter table public.event_costs add constraint event_costs_quoted_finite_chk
      check (quoted >= 0 and quoted < 1e12) not valid;
  end if;
  if not exists (select 1 from pg_constraint where conname = 'event_costs_vendor_id_0196_fkey'
                  and conrelid = 'public.event_costs'::regclass) then
    alter table public.event_costs add constraint event_costs_vendor_id_0196_fkey
      foreign key (vendor_id) references public.vendors(id) on delete set null;
  end if;
end $$;

-- one row per requirement / standard line per event (NULL keys = hand-typed lines, never collide)
create unique index if not exists event_costs_req_key_0196_uq on public.event_costs (quote_id, requirement_key);
create index if not exists event_costs_vendor_0196_idx on public.event_costs (vendor_id) where vendor_id is not null;

-- a cost line may only name a vendor of its own studio (runs after org_from_quote set org_id)
create or replace function public.tg_event_costs_vendor_org_0196()
returns trigger language plpgsql security definer set search_path = '' as $$
-- budget-plan-0196
begin
  if new.vendor_id is null then return new; end if;
  if tg_op = 'UPDATE' and new.vendor_id is not distinct from old.vendor_id and new.org_id is not distinct from old.org_id then
    return new;
  end if;
  if not exists (select 1 from public.vendors v where v.id = new.vendor_id and v.org_id = new.org_id) then
    raise exception 'That vendor is not in this studio.' using errcode = '42501', hint = 'vendor_other_studio';
  end if;
  return new;
end $$;
revoke all on function public.tg_event_costs_vendor_org_0196() from public, anon, authenticated;

drop trigger if exists zz_event_costs_vendor_org_0196 on public.event_costs;
create trigger zz_event_costs_vendor_org_0196 before insert or update of vendor_id, org_id on public.event_costs
  for each row execute function public.tg_event_costs_vendor_org_0196();

comment on column public.event_costs.requirement_key is '0196: req:<requirement name, folded> or std:<standard line id>; unique per event';
comment on column public.event_costs.priority is '0196: requirement priority when the line was made (mandatory / nice / optional)';
comment on column public.event_costs.quoted is '0196: amount quoted to the client for this line (planning only; revenue is the quote total)';
comment on column public.event_costs.vendor_id is '0196: vendor for this line (same studio only)';
commit;

-- VERIFY (every row should say ok = true)
select item, ok from (values
  ('01 four new nullable columns on event_costs', (select count(*) from information_schema.columns where table_schema = 'public' and table_name = 'event_costs'
      and column_name in ('requirement_key', 'priority', 'quoted', 'vendor_id') and is_nullable = 'YES') = 4),
  ('02 unique (quote_id, requirement_key) index', exists (select 1 from pg_indexes where schemaname = 'public' and tablename = 'event_costs'
      and indexname = 'event_costs_req_key_0196_uq' and indexdef like 'CREATE UNIQUE INDEX%(quote_id, requirement_key)%')),
  ('03 priority / key / quoted checks', (select count(*) from pg_constraint where conrelid = 'public.event_costs'::regclass
      and conname in ('event_costs_requirement_key_0196_chk', 'event_costs_priority_0196_chk', 'event_costs_quoted_finite_chk')) = 3),
  ('04 vendor FK (on delete set null)', exists (select 1 from pg_constraint where conrelid = 'public.event_costs'::regclass
      and conname = 'event_costs_vendor_id_0196_fkey' and confdeltype = 'n')),
  ('05 same-studio vendor trigger', exists (select 1 from pg_trigger where tgrelid = 'public.event_costs'::regclass
      and tgname = 'zz_event_costs_vendor_org_0196' and not tgisinternal)),
  ('06 trigger function not callable by the app', not has_function_privilege('authenticated', 'public.tg_event_costs_vendor_org_0196()', 'execute')
      and not has_function_privilege('anon', 'public.tg_event_costs_vendor_org_0196()', 'execute')),
  ('07 not a trial-capped table', not exists (select 1 from pg_trigger where tgrelid = 'public.event_costs'::regclass and tgname like 'zzzz_tl173%'))
) v(item, ok) order by item;

-- ##########################################################################################
-- RELEASE SECTION 22/28: APPLY-0197.sql
-- In plain words: Over-capacity decision on a quote + stock-shortage sourcing on "Reserve for this event".
-- ##########################################################################################
-- APPLY-0197.sql - paste into the Supabase SQL editor (staging first, then production).
-- Over-capacity decision on a quote (change venue / reduce guests / extend the space / proceed with a note)
-- and stock-shortage sourcing on "Reserve for this event" (reserve what is free, rent the rest from a vendor,
-- outsource / buy, or record it as unsourced - available stock never goes below 0).
-- Additive + idempotent: 4 new nullable columns, constraints / indexes / triggers created only when missing,
-- 2 new functions (create or replace). No existing row is changed. Safe to run twice.
begin;
-- 0197_capacity_and_stock_shortage.sql - CANONICAL forward-only.
-- REQUIRES the base quotes / inventory_items / inventory_reservations / inventory_checkouts /
-- event_stock_requests (phase23) / event_resources / vendors tables, 0026 (tg_ref_org_match),
-- 0071 (reserve_inventory demand rule) and phase72 (assert_quote_org).
--
-- In plain words:
--   1) OVER-CAPACITY DECISION. A quote can have more guests than its linked venue holds
--      (seated + floating). Before the quote is sent, a PDF is made or the booking is confirmed,
--      the app now asks how to resolve it: change venue, reduce guests, extend the space (an
--      overflow tent / extra seating line) or proceed anyway with a note. The answer is kept on
--      the quote in a NEW nullable column quotes.capacity_decision (jsonb), written only through
--      set_quote_capacity_decision(quote, decision): quotes edit right + own studio, shape
--      checked, the venue / inventory item / vendor it names must be the caller's own studio's.
--      The app never writes the column directly (no column grant), so the shape is always valid.
--   2) STOCK SHORTAGE SOURCING. "Reserve for this event" asking for more than is free no longer
--      over-commits stock (which showed a minus on inventory and the calendar). The new
--      reserve_inventory_with_sourcing(item, quote, qty, note, source, vendor, rate, source_note)
--      does it in ONE transaction: locks the item, works out what is free on the event's date
--      exactly like reserve_inventory (0071: live reservations + still-out check-outs, shelved /
--      cancelled / closed events ignored), reserves only what is free, and records the rest as a
--      shortage on event_stock_requests (new nullable columns source / booking_id / vendor_id):
--        source 'vendor' - rent from a vendor: also adds a vendor booking (event_resources,
--                          status enquiry, cost = shortfall x rate) so it shows in Budget & margin
--                          and the vendor's history;
--        source 'buy'    - outsource / buy (note only);
--        source 'none'   - not sourced yet (shows as "unsourced").
--      Available stock can never go below zero through this path.
--   Additive + idempotent: ADD COLUMN IF NOT EXISTS (nullable, no default, no backfill), check /
--   foreign-key constraints on those new all-null columns created only when missing (so they pass
--   on every existing row), org-match triggers created only when missing, CREATE OR REPLACE FUNCTION. No DROP of data, DELETE, UPDATE or TRUNCATE; no existing
--   row is changed. The 0167 sample clone and trial seed are untouched (new columns stay null).
--   ROLLBACK (manual, only if ever needed): drop function public.set_quote_capacity_decision(uuid, jsonb);
--   drop function public.reserve_inventory_with_sourcing(uuid, uuid, numeric, text, text, uuid, numeric, text);
--   the new columns can stay (all nullable) - dropping them would discard recorded decisions.
-- ============================================================================

do $$ begin
  if to_regclass('public.quotes') is null then raise exception '0197: public.quotes is missing'; end if;
  if to_regclass('public.event_stock_requests') is null then raise exception '0197: public.event_stock_requests is missing (phase23)'; end if;
  if to_regclass('public.event_resources') is null then raise exception '0197: public.event_resources is missing'; end if;
  if to_regclass('public.inventory_reservations') is null then raise exception '0197: public.inventory_reservations is missing'; end if;
  if to_regclass('public.vendors') is null then raise exception '0197: public.vendors is missing'; end if;
  if to_regprocedure('public.has_area(text,text)') is null then raise exception '0197: public.has_area(text,text) is missing'; end if;
  if to_regprocedure('public.current_org_id()') is null then raise exception '0197: public.current_org_id() is missing'; end if;
end $$;

-- ---- 1) new nullable columns ------------------------------------------------------------------
alter table public.quotes add column if not exists capacity_decision jsonb;
alter table public.event_stock_requests add column if not exists source text;
alter table public.event_stock_requests add column if not exists booking_id uuid;
alter table public.event_stock_requests add column if not exists vendor_id uuid;

do $$ begin
  if not exists (select 1 from pg_constraint where conrelid = 'public.quotes'::regclass and conname = 'quotes_capacity_decision_shape_0197') then
    alter table public.quotes add constraint quotes_capacity_decision_shape_0197
      check (capacity_decision is null or (jsonb_typeof(capacity_decision) = 'object'
             and capacity_decision ->> 'choice' in ('venue', 'reduce', 'extend', 'proceed')
             and pg_column_size(capacity_decision) <= 8192));
  end if;
  if not exists (select 1 from pg_constraint where conrelid = 'public.event_stock_requests'::regclass and conname = 'event_stock_requests_source_0197') then
    alter table public.event_stock_requests add constraint event_stock_requests_source_0197
      check (source is null or source in ('vendor', 'buy', 'none'));
  end if;
  if not exists (select 1 from pg_constraint where conrelid = 'public.event_stock_requests'::regclass and conname = 'event_stock_requests_booking_fk_0197') then
    alter table public.event_stock_requests add constraint event_stock_requests_booking_fk_0197
      foreign key (booking_id) references public.event_resources(id) on delete set null;
  end if;
  if not exists (select 1 from pg_constraint where conrelid = 'public.event_stock_requests'::regclass and conname = 'event_stock_requests_vendor_fk_0197') then
    alter table public.event_stock_requests add constraint event_stock_requests_vendor_fk_0197
      foreign key (vendor_id) references public.vendors(id) on delete set null;
  end if;
end $$;

create index if not exists event_stock_req_booking_idx_0197 on public.event_stock_requests(booking_id) where booking_id is not null;
create index if not exists event_stock_req_vendor_idx_0197 on public.event_stock_requests(vendor_id) where vendor_id is not null;

-- cross-studio guard for the two new references (0026 tg_ref_org_match; new / changed values only)
do $$ begin
  if to_regprocedure('public.tg_ref_org_match()') is null then return; end if;
  if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'event_stock_requests' and column_name = 'org_id') then
    if not exists (select 1 from pg_trigger where tgrelid = 'public.event_stock_requests'::regclass and tgname = 'zz_ref_org_match_booking_id' and not tgisinternal) then
      create trigger zz_ref_org_match_booking_id before insert or update of booking_id, org_id on public.event_stock_requests
        for each row execute function public.tg_ref_org_match('booking_id', 'event_resources');
    end if;
    if not exists (select 1 from pg_trigger where tgrelid = 'public.event_stock_requests'::regclass and tgname = 'zz_ref_org_match_vendor_id' and not tgisinternal) then
      create trigger zz_ref_org_match_vendor_id before insert or update of vendor_id, org_id on public.event_stock_requests
        for each row execute function public.tg_ref_org_match('vendor_id', 'vendors');
    end if;
  end if;
end $$;

-- ---- 2) set_quote_capacity_decision -----------------------------------------------------------
-- p_decision = null clears it. Otherwise:
--   { choice: venue|reduce|extend|proceed, note, guests, capacity, venue_id, venue_name,
--     extra_capacity (extend), line: { label, qty, rate, amount, source: inventory|vendor|later, item_id, vendor_id } }
-- The stored object adds decided_at + decided_by. Returns the stored value.
create or replace function public.set_quote_capacity_decision(p_quote uuid, p_decision jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_org uuid := public.current_org_id();
  v_choice text; v_note text; v_guests numeric; v_cap numeric; v_extra numeric;
  v_venue uuid; v_line jsonb := null; v_src text; v_item uuid; v_vendor uuid;
  v_qty numeric; v_rate numeric; v_label text; v_out jsonb;
  uuid_re constant text := '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$';
  num_re constant text := '^[0-9]{1,9}(\.[0-9]{1,2})?$';
begin
  if auth.uid() is null or v_org is null or not coalesce(public.has_area('quotes', 'edit'), false) then
    raise exception 'not authorized' using errcode = '42501';
  end if;
  if p_quote is null or not exists (select 1 from public.quotes where id = p_quote and org_id = v_org) then
    raise exception 'not authorized for this event' using errcode = '42501';
  end if;
  if p_decision is null or p_decision = 'null'::jsonb then
    update public.quotes set capacity_decision = null where id = p_quote and org_id = v_org;
    return null;
  end if;
  if jsonb_typeof(p_decision) <> 'object' or pg_column_size(p_decision) > 6000 then
    raise exception 'capacity decision must be a small object' using errcode = '22023';
  end if;
  v_choice := p_decision ->> 'choice';
  if v_choice is null or v_choice not in ('venue', 'reduce', 'extend', 'proceed') then
    raise exception 'choose: change venue, reduce guests, extend the space or proceed anyway' using errcode = '22023';
  end if;
  v_note := nullif(btrim(coalesce(p_decision ->> 'note', '')), '');
  if v_note is not null and length(v_note) > 1000 then raise exception 'note is too long (1000 characters at most)' using errcode = '22023'; end if;
  if v_choice = 'proceed' and (v_note is null or length(v_note) < 5) then
    raise exception 'add a note (at least 5 characters) to proceed anyway' using errcode = '22023';
  end if;
  if coalesce(p_decision ->> 'guests', '') !~ '^[0-9]{1,7}$' or (p_decision ->> 'guests')::numeric < 1 then
    raise exception 'guests must be a whole number' using errcode = '22023';
  end if;
  v_guests := (p_decision ->> 'guests')::numeric;
  if coalesce(p_decision ->> 'capacity', '0') !~ '^[0-9]{1,7}$' then raise exception 'capacity must be a whole number' using errcode = '22023'; end if;
  v_cap := coalesce((p_decision ->> 'capacity')::numeric, 0);
  if coalesce(p_decision ->> 'extra_capacity', '0') !~ '^[0-9]{1,7}$' then raise exception 'extra capacity must be a whole number' using errcode = '22023'; end if;
  v_extra := coalesce((p_decision ->> 'extra_capacity')::numeric, 0);
  if v_choice = 'extend' and v_extra < 1 then raise exception 'say how many more guests the extra space holds' using errcode = '22023'; end if;
  if nullif(p_decision ->> 'venue_id', '') is not null then
    if (p_decision ->> 'venue_id') !~ uuid_re then raise exception 'venue is not valid' using errcode = '22023'; end if;
    v_venue := (p_decision ->> 'venue_id')::uuid;
    if to_regclass('public.venues') is null
       or not exists (select 1 from public.venues where id = v_venue and org_id = v_org) then
      raise exception 'venue belongs to another studio' using errcode = '42501';
    end if;
  end if;
  if p_decision ? 'line' and jsonb_typeof(p_decision -> 'line') = 'object' then
    v_label := nullif(btrim(coalesce(p_decision -> 'line' ->> 'label', '')), '');
    if v_label is null or length(v_label) > 200 then raise exception 'name the extra space (200 characters at most)' using errcode = '22023'; end if;
    v_src := coalesce(p_decision -> 'line' ->> 'source', 'later');
    if v_src not in ('inventory', 'vendor', 'later') then raise exception 'source must be inventory, vendor or later' using errcode = '22023'; end if;
    if coalesce(p_decision -> 'line' ->> 'qty', '1') !~ '^[0-9]{1,6}$' then raise exception 'quantity must be a whole number' using errcode = '22023'; end if;
    v_qty := coalesce((p_decision -> 'line' ->> 'qty')::numeric, 1);
    if coalesce(p_decision -> 'line' ->> 'rate', '0') !~ num_re then raise exception 'rate must be an amount' using errcode = '22023'; end if;
    v_rate := coalesce((p_decision -> 'line' ->> 'rate')::numeric, 0);
    if nullif(p_decision -> 'line' ->> 'item_id', '') is not null then
      if (p_decision -> 'line' ->> 'item_id') !~ uuid_re then raise exception 'item is not valid' using errcode = '22023'; end if;
      v_item := (p_decision -> 'line' ->> 'item_id')::uuid;
      if not exists (select 1 from public.inventory_items where id = v_item and org_id = v_org) then
        raise exception 'item belongs to another studio' using errcode = '42501'; end if;
    end if;
    if nullif(p_decision -> 'line' ->> 'vendor_id', '') is not null then
      if (p_decision -> 'line' ->> 'vendor_id') !~ uuid_re then raise exception 'vendor is not valid' using errcode = '22023'; end if;
      v_vendor := (p_decision -> 'line' ->> 'vendor_id')::uuid;
      if not exists (select 1 from public.vendors where id = v_vendor and org_id = v_org) then
        raise exception 'vendor belongs to another studio' using errcode = '42501'; end if;
    end if;
    v_line := jsonb_strip_nulls(jsonb_build_object('label', v_label, 'source', v_src, 'qty', v_qty, 'rate', v_rate,
      'amount', round(v_qty * v_rate, 2), 'item_id', v_item, 'vendor_id', v_vendor));
  elsif v_choice = 'extend' then
    raise exception 'describe the extra space (what, quantity and rate)' using errcode = '22023';
  end if;

  v_out := jsonb_strip_nulls(jsonb_build_object(
    'choice', v_choice, 'note', v_note, 'guests', v_guests, 'capacity', v_cap,
    'extra_capacity', case when v_choice = 'extend' then v_extra end,
    'venue_id', v_venue, 'venue_name', left(nullif(btrim(coalesce(p_decision ->> 'venue_name', '')), ''), 200),
    'line', v_line, 'decided_at', now(), 'decided_by', auth.uid()));
  update public.quotes set capacity_decision = v_out where id = p_quote and org_id = v_org;
  return v_out;
end $$;
revoke all on function public.set_quote_capacity_decision(uuid, jsonb) from public, anon;
grant execute on function public.set_quote_capacity_decision(uuid, jsonb) to authenticated;

-- ---- 3) reserve_inventory_with_sourcing ---------------------------------------------------------
-- Returns { reserved, short, available, reservation_id, request_id, booking_id }.
create or replace function public.reserve_inventory_with_sourcing(
  p_item uuid, p_quote uuid, p_qty numeric, p_note text default null,
  p_source text default 'none', p_vendor uuid default null, p_rate numeric default null, p_source_note text default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_org uuid := public.current_org_id();
  v_total numeric; v_name text; v_unit text; v_date date; v_code text;
  v_load numeric; v_undated numeric; v_free numeric; v_take numeric; v_short numeric;
  v_res uuid; v_req uuid; v_bk uuid; v_vname text; v_vkind text; v_src text := coalesce(nullif(btrim(coalesce(p_source, '')), ''), 'none');
  v_snote text := left(nullif(btrim(coalesce(p_source_note, '')), ''), 500);
  v_label text; v_txt text;
begin
  if auth.uid() is null or v_org is null or not coalesce(public.has_area('inventory', 'edit'), false) then
    raise exception 'not authorized' using errcode = '42501';
  end if;
  if p_qty is null or p_qty <= 0 or p_qty <> trunc(p_qty) or p_qty > 1000000 then
    raise exception 'quantity must be a whole number above 0' using errcode = '22023';
  end if;
  if v_src not in ('vendor', 'buy', 'none') then raise exception 'source must be vendor, buy or none' using errcode = '22023'; end if;
  if p_rate is not null and (p_rate < 0 or p_rate >= 1e9 or round(p_rate, 2) <> p_rate) then
    raise exception 'rate must be an amount of 0 or more' using errcode = '22023';
  end if;
  if not exists (select 1 from public.quotes where id = p_quote and org_id = v_org) then
    raise exception 'not authorized for this event' using errcode = '42501';
  end if;
  if v_src = 'vendor' then
    if p_vendor is null then raise exception 'pick the vendor to rent from' using errcode = '22023'; end if;
    if not coalesce(public.has_area('vendors', 'edit'), false) then
      raise exception 'your role cannot add vendor bookings - choose outsource / buy or ask a manager' using errcode = '42501';
    end if;
    select name, kind into v_vname, v_vkind from public.vendors where id = p_vendor and org_id = v_org;
    if not found then raise exception 'vendor belongs to another studio' using errcode = '42501'; end if;
  elsif p_vendor is not null then
    raise exception 'a vendor is only used with source vendor' using errcode = '22023';
  end if;

  -- serialise with reserve_inventory / other sourcing calls on the same item
  select total_qty, name, unit into v_total, v_name, v_unit from public.inventory_items
    where id = p_item and org_id = v_org for update;
  if not found then raise exception 'item not found' using errcode = '42501'; end if;
  select event_date, code into v_date, v_code from public.quotes where id = p_quote;

  -- same demand rule as reserve_inventory (0071)
  with ev as (
    select q.id, q.event_date from public.quotes q
     where q.org_id = v_org and q.deleted_at is null and q.archived_at is null
       and q.status <> 'cancelled' and not (q.lifecycle_stage = 'closed' and q.status = 'confirmed')
  ), per as (
    select e.id as qid, e.event_date,
           greatest(coalesce((select sum(r.qty) from public.inventory_reservations r
                               where r.item_id = p_item and r.quote_id = e.id and r.status in ('reserved','allocated')),0),
                    coalesce((select sum(c.qty_out - coalesce(c.qty_in,0)) from public.inventory_checkouts c
                               where c.item_id = p_item and c.quote_id = e.id and c.status in ('out','partial')),0)) as d
      from ev e
  )
  select coalesce(sum(d) filter (where event_date is not distinct from v_date and v_date is not null),0),
         coalesce(sum(d) filter (where event_date is null),0)
    into v_load, v_undated from per;
  v_undated := v_undated + coalesce((select sum(c.qty_out - coalesce(c.qty_in,0)) from public.inventory_checkouts c
                                      where c.item_id = p_item and c.org_id = v_org and c.quote_id is null and c.status in ('out','partial')),0);
  if v_date is null then v_load := v_undated; v_undated := 0; end if;

  v_free := greatest(coalesce(v_total, 0) - v_load - v_undated, 0);
  v_free := floor(v_free);
  v_take := least(p_qty, v_free);
  v_short := p_qty - v_take;

  if v_take > 0 then
    insert into public.inventory_reservations (item_id, quote_id, qty, note, created_by)
      values (p_item, p_quote, v_take, nullif(btrim(coalesce(p_note, '')), ''), auth.uid())
      returning id into v_res;
  end if;

  if v_short > 0 then
    v_label := left('Short: ' || v_short::text || ' x ' || coalesce(v_name, 'item'), 200);
    if v_src = 'vendor' then
      v_txt := left('Rent ' || v_short::text || ' ' || coalesce(nullif(v_unit, ''), 'x') || ' ' || coalesce(v_name, 'item')
        || ' for ' || coalesce(v_code, 'this event') || coalesce(' on ' || to_char(v_date, 'DD Mon YYYY'), '')
        || ' (stock shortfall)' || coalesce('. ' || v_snote, ''), 2000);
      insert into public.event_resources (quote_id, vendor_id, kind, label, qty, cost, status, note, created_by)
        values (p_quote, p_vendor, v_vkind, left(coalesce(v_name, 'Item') || ' - rent ' || v_short::text || ' (stock shortfall)', 500),
                v_short, case when p_rate is null then null else round(v_short * p_rate, 2) end, 'enquiry', v_txt, auth.uid())
        returning id into v_bk;
    end if;
    insert into public.event_stock_requests (quote_id, item_id, label, qty, status, note, created_by, source, booking_id, vendor_id)
      values (p_quote, p_item, v_label, v_short, 'requested',
              left(case v_src when 'vendor' then 'Sourcing from ' || coalesce(v_vname, 'vendor')
                              when 'buy' then 'Outsource / buy'
                              else 'Unsourced' end
                   || coalesce(' - ' || v_snote, ''), 1000),
              auth.uid(), v_src, v_bk, case when v_src = 'vendor' then p_vendor end)
      returning id into v_req;
  end if;

  return jsonb_strip_nulls(jsonb_build_object('reserved', v_take, 'short', v_short, 'available', v_free,
    'reservation_id', v_res, 'request_id', v_req, 'booking_id', v_bk, 'source', case when v_short > 0 then v_src end));
end $$;
revoke all on function public.reserve_inventory_with_sourcing(uuid, uuid, numeric, text, text, uuid, numeric, text) from public, anon;
grant execute on function public.reserve_inventory_with_sourcing(uuid, uuid, numeric, text, text, uuid, numeric, text) to authenticated;

notify pgrst, 'reload schema';
commit;

-- VERIFY (every row should say ok = true)
select item, ok from (values
  ('01 quotes.capacity_decision present + nullable', exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'quotes' and column_name = 'capacity_decision' and is_nullable = 'YES')),
  ('02 event_stock_requests source / booking_id / vendor_id present + nullable', (select count(*) from information_schema.columns where table_schema = 'public' and table_name = 'event_stock_requests' and column_name in ('source', 'booking_id', 'vendor_id') and is_nullable = 'YES') = 3),
  ('03 shape + source checks present', (select count(*) from pg_constraint where conname in ('quotes_capacity_decision_shape_0197', 'event_stock_requests_source_0197')) = 2),
  ('04 booking / vendor foreign keys present', (select count(*) from pg_constraint where conname in ('event_stock_requests_booking_fk_0197', 'event_stock_requests_vendor_fk_0197')) = 2),
  ('05 cross-studio guards on the new references', (select count(*) from pg_trigger where tgrelid = 'public.event_stock_requests'::regclass and tgname in ('zz_ref_org_match_booking_id', 'zz_ref_org_match_vendor_id') and not tgisinternal) = 2),
  ('06 set_quote_capacity_decision present, SECURITY DEFINER, search_path pinned', coalesce((select prosecdef and proconfig::text like '%search_path=%' from pg_proc where oid = to_regprocedure('public.set_quote_capacity_decision(uuid,jsonb)')), false)),
  ('07 reserve_inventory_with_sourcing present, SECURITY DEFINER, search_path pinned', coalesce((select prosecdef and proconfig::text like '%search_path=%' from pg_proc where oid = to_regprocedure('public.reserve_inventory_with_sourcing(uuid,uuid,numeric,text,text,uuid,numeric,text)')), false)),
  ('08 signed-in users can call both, anon cannot', has_function_privilege('authenticated', 'public.set_quote_capacity_decision(uuid,jsonb)', 'execute') and has_function_privilege('authenticated', 'public.reserve_inventory_with_sourcing(uuid,uuid,numeric,text,text,uuid,numeric,text)', 'execute') and not has_function_privilege('anon', 'public.set_quote_capacity_decision(uuid,jsonb)', 'execute') and not has_function_privilege('anon', 'public.reserve_inventory_with_sourcing(uuid,uuid,numeric,text,text,uuid,numeric,text)', 'execute')),
  ('09 the app cannot write quotes.capacity_decision directly', not has_column_privilege('authenticated', 'public.quotes', 'capacity_decision', 'UPDATE')),
  ('10 no decision / shortage rows yet on a fresh apply (informational)', (select count(*) from public.quotes where capacity_decision is not null) >= 0)
) v(item, ok) order by item;

-- ##########################################################################################
-- RELEASE SECTION 23/28: APPLY-0198.sql
-- In plain words: Event stages: no closing before the event day, Cancel event, calendar conflict acknowledgements.
-- ##########################################################################################
-- APPLY-0198.sql - paste into the Supabase SQL editor (staging first, then production), AFTER the trial bundle (0179-0186).
-- Additive + idempotent: no closing before the event day (studio time zone), clearer stage moves, Cancel event, conflict acknowledgements. No row is changed. Safe to run twice.
begin;
-- 0198_event_stages_closure.sql - CANONICAL forward-only.
-- REQUIRES 0049 + 0148 + 0152 (close gate), 0052 + 0084 (lifecycle stages), 0042 (OTP expiry helper);
-- after 0184 when installed (trial retention purge list gets the two new tables).
--
-- In plain words - owner test on a trial studio, 18 Oct 2026 (event on 7 Nov 2026):
--   1. CLOSING. The event could be closed weeks before it happened. Closing now needs the event day
--      to be over in the STUDIO's own time zone (organizations.timezone, default Asia/Kolkata):
--      "You can close this event after 7 Nov 2026 (event day)." (error HL425). Nobody can override
--      that - an event that will not happen is CANCELLED instead (3). An event with no date is a
--      new close blocker (an admin can still override it with a reason, like a balance owed).
--      The existing balance / equipment / never-confirmed gate (0049/0110/0152) is unchanged and
--      still runs on the server: money still owed blocks closing unless an admin gives a reason.
--      close_event_blockers() now also reports event_date / studio_today / too_early /
--      no_event_date / close_after so the Closure page can say it before anyone clicks.
--   2. STAGES. set_lifecycle_stage keeps every 0052 rule and adds:
--        - a CONFIRMED event can not be moved back before Confirmed (that flip-flopped the stage
--          strip: the page showed "Confirmed" while the stored stage said Lead/Quote);
--        - a cancelled or closed event's stage can not change (reopen / it is cancelled);
--        - moving to the stage it is already on is a no-op (no write, no audit noise);
--        - forward gates, each one listed in plain words (HL409, an admin can still override):
--            Planning   needs: menu locked, layout v1 (a saved floor layout with objects)
--            Event Day  opens on the event date (studio time zone)
--            Settlement once the event date has arrived (studio time zone, was server UTC)
--      lifecycle_stage_blockers() returns the same list for the stage strip.
--   3. CANCEL EVENT. cancel_event(quote, reason): admin or manager with quotes edit, reason
--      5..1000 chars. Status becomes 'cancelled' (lifecycle stage and every payment / reservation
--      row are kept as they are), the client approval link is revoked and open OTPs expire. Every
--      cancellation is recorded in public.event_cancellations + audit_log. A closed event is
--      reopened first. A cancelled event can still be closed later to settle it (0152 rule).
--   4. CONFLICT ACKNOWLEDGEMENTS. public.calendar_conflict_acks: "mark acknowledged" on a calendar
--      clash (same date / venue / crew / vendor / stock). Rows are written only through
--      ack_calendar_conflict / unack_calendar_conflict (un-acknowledge stamps revoked_at, nothing
--      is deleted). Readable by the studio's members with quotes view.
--
-- ZERO DATA LOSS: 2 new tables, new functions, CREATE OR REPLACE of _a49_close_blockers,
-- _a49_blocker_text, _a49_close_gate, set_lifecycle_stage(uuid,text,text) and
-- lifecycle_stage_blockers (same signatures + grants). No table, column, row, trigger or policy
-- is dropped or deleted; no existing row is updated. Sample-data clones that insert closed
-- sample events directly are not affected (no trigger is added on quotes / event_closure).
-- Additive + idempotent: safe to run twice. ASCII only.

do $$ begin
  if to_regprocedure('public._a49_close_blockers(uuid)') is null
     or to_regprocedure('public._a49_blocker_text(jsonb)') is null
     or to_regprocedure('public._a49_close_gate(uuid,text)') is null
     or to_regprocedure('public.helm_invoice_total(uuid)') is null then
    raise exception 'STOP: apply 0049 + 0110 + 0148 + 0152 (close gate) first'; end if;
  if to_regprocedure('public.set_lifecycle_stage__pre0052(uuid,text)') is null
     or to_regprocedure('public._a52_stage_idx(text)') is null
     or to_regprocedure('public._a52_has_consent(uuid)') is null
     or to_regclass('public.lifecycle_stage_overrides') is null then
    raise exception 'STOP: apply 0052 + 0084 (lifecycle stages) first'; end if;
end $$;

-- ---- 0) helpers --------------------------------------------------------------------------
-- the studio's own calendar day (organizations.timezone; a missing / unknown zone -> Asia/Kolkata)
create or replace function public._a198_org_today(p_org uuid)
returns date language plpgsql stable security definer set search_path = '' as $$
-- helm-0198-stages
declare v_tz text;
begin
  select nullif(btrim(o.timezone), '') into v_tz from public.organizations o where o.id = p_org;
  begin
    return (now() at time zone coalesce(v_tz, 'Asia/Kolkata'))::date;
  exception when others then
    return (now() at time zone 'Asia/Kolkata')::date;
  end;
end $$;

create or replace function public._a198_stage_label(p text)
returns text language sql immutable set search_path = '' as $$
  select case p when 'lead' then 'Lead' when 'discovery' then 'Discovery' when 'proposal' then 'Proposal'
                when 'quote' then 'Quote' when 'confirmed' then 'Confirmed' when 'planning' then 'Planning'
                when 'resources' then 'Resources' when 'ready' then 'Ready' when 'event_day' then 'Event Day'
                when 'settlement' then 'Settlement' when 'closed' then 'Closure' else coalesce(p, '') end;
$$;

create or replace function public._a198_day(p date)
returns text language sql immutable set search_path = '' as $$
  select to_char(p, 'FMDD Mon YYYY');
$$;

-- ---- 1) close gate: the event day must be over (studio time zone) ------------------------
create or replace function public._a49_close_blockers(p_quote uuid)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
-- 0110 body + manager-1019-0152: not_booked blocker + helm-0198-stages: event day over
declare v_total numeric; v_paid numeric; v_owed numeric; v_items jsonb; v_n int; v_status text; v_nb text;
        v_date date; v_org uuid; v_today date; v_early boolean := false; v_nodate boolean := false;
begin
  select coalesce(nullif(q.pricing ->> 'total', '')::numeric, 0), q.status, q.event_date, q.org_id
    into v_total, v_status, v_date, v_org
    from public.quotes q where q.id = p_quote;
  if coalesce(v_total, 0) > 0 then v_total := public.helm_invoice_total(p_quote); end if;
  v_paid := coalesce(public.helm_total_paid(p_quote, null, null), 0);
  v_owed := greatest(coalesce(v_total, 0) - v_paid, 0);
  if v_owed <= 0.5 then v_owed := 0; end if;
  select count(*), coalesce(jsonb_agg(jsonb_build_object(
           'id', c.id, 'item', coalesce(i.name, 'item'), 'qty', c.qty_out, 'issued_to', c.issued_to)
           order by c.checked_out_at), '[]'::jsonb)
    into v_n, v_items
    from public.inventory_checkouts c left join public.inventory_items i on i.id = c.item_id
   where c.quote_id = p_quote and c.status = 'out';
  -- 0152: a cancelled event may still be closed; anything else must be confirmed AND priced
  if coalesce(v_status, '') <> 'cancelled' then
    if coalesce(v_status, '') <> 'confirmed' then v_nb := 'unconfirmed';
    elsif coalesce(v_total, 0) <= 0 then v_nb := 'unpriced'; end if;
  end if;
  -- 0198: the event day must be over (a cancelled event is closed whenever it is settled)
  v_today := public._a198_org_today(v_org);
  if coalesce(v_status, '') <> 'cancelled' then
    if v_date is null then v_nodate := true;
    elsif v_date >= v_today then v_early := true; end if;
  end if;
  return jsonb_build_object('total', coalesce(v_total, 0), 'paid', v_paid, 'balance_owed', v_owed,
                            'open_checkouts', v_n, 'checkouts', v_items, 'not_booked', v_nb,
                            'event_date', v_date, 'studio_today', v_today,
                            'too_early', v_early, 'no_event_date', v_nodate,
                            'close_after', case when v_date is not null then public._a198_day(v_date) end,
                            'blocked', (v_owed > 0 or v_n > 0 or v_nb is not null or v_early or v_nodate));
end $$;

create or replace function public._a49_blocker_text(b jsonb)
returns text language sql immutable set search_path = '' as $$
  -- manager-1019-0152: + not_booked; helm-0198-stages: + event day / no date
  select concat_ws('; ',
    case when coalesce((b ->> 'too_early')::boolean, false)
         then 'the event day (' || coalesce(b ->> 'close_after', '') || ') is not over yet' end,
    case when coalesce((b ->> 'no_event_date')::boolean, false) then 'the event has no date yet' end,
    case when b ->> 'not_booked' = 'unconfirmed' then 'the quote was never confirmed by the client'
         when b ->> 'not_booked' = 'unpriced' then 'the quote has no price yet' end,
    case when (b ->> 'balance_owed')::numeric > 0
         then 'client balance still owed: ' || to_char((b ->> 'balance_owed')::numeric, 'FM999999999990.00') end,
    case when (b ->> 'open_checkouts')::int > 0
         then (b ->> 'open_checkouts') || ' equipment checkout(s) still out: '
              || (select string_agg(x ->> 'item' || ' x' || (x ->> 'qty'), ', ')
                    from (select x from jsonb_array_elements(b -> 'checkouts') x limit 8) s) end);
$$;

create or replace function public._a49_close_gate(p_quote uuid, p_reason text)
returns void language plpgsql volatile security definer set search_path = '' as $$
-- close-gate-0148: ASCII-only messages; helm-0198-stages: no closing before the event day is over
declare b jsonb; v_org uuid := public.current_org_id(); v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
        v_status text; v_date date; v_today date;
begin
  if not exists (select 1 from public.quotes q where q.id = p_quote and q.org_id = v_org) then
    raise exception 'not authorized for this event' using errcode = '42501';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('helm:pay:quote:' || p_quote::text, 0));
  select q.status, q.event_date into v_status, v_date from public.quotes q where q.id = p_quote for update;
  -- 0198: hard rule, no override - an event that will not happen is cancelled instead
  v_today := public._a198_org_today(v_org);
  if coalesce(v_status, '') <> 'cancelled' and v_date is not null and v_date >= v_today then
    raise exception 'You can close this event after % (event day).', public._a198_day(v_date)
      using errcode = 'HL425', hint = 'event_not_over',
            detail = jsonb_build_object('event_date', v_date, 'studio_today', v_today)::text;
  end if;
  b := public._a49_close_blockers(p_quote);
  if not (b ->> 'blocked')::boolean then return; end if;
  if v_reason is null then
    raise exception 'Can''t close this event yet: %.', public._a49_blocker_text(b)
      using errcode = 'P0001', detail = b::text,
            hint = 'Collect the balance or return the equipment first, or an admin can close with an override reason.';
  end if;
  if coalesce(public.user_role(), '') <> 'admin' then
    raise exception 'Only an admin can close an event with something outstanding (%).', public._a49_blocker_text(b)
      using errcode = '42501';
  end if;
  if length(v_reason) < 5 or length(v_reason) > 1000 then
    raise exception 'override reason must be 5 to 1000 characters' using errcode = '22023';
  end if;
  insert into public.event_close_overrides(org_id, quote_id, actor, actor_email, reason, balance_owed, open_checkouts, blockers)
    values (v_org, p_quote, auth.uid(), (select u.email from auth.users u where u.id = auth.uid()), v_reason,
            (b ->> 'balance_owed')::numeric, (b ->> 'open_checkouts')::int, b);
  insert into public.audit_log(actor, actor_email, action, entity, entity_id, quote_id, changed, org_id)
    values (auth.uid(), (select u.email from auth.users u where u.id = auth.uid()), 'close_override', 'event_closure',
            p_quote::text, p_quote, jsonb_build_object('reason', v_reason, 'blockers', b), v_org);
end $$;

-- ---- 2) lifecycle stages ----------------------------------------------------------------------
-- what blocks moving p_quote forward to p_stage: [] = allowed; {stale:true} entries can't be overridden
create or replace function public._a198_stage_blockers(p_quote uuid, p_stage text)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
-- helm-0198-stages: 0052/0084 gates + planning readiness + event day, dates in the studio time zone
declare q record; v_from int; v_to int; b jsonb := '[]'::jsonb; v_today date; v_need text[] := array[]::text[];
begin
  select q2.lifecycle_stage, q2.event_date, q2.consent_stale, q2.org_id into q from public.quotes q2 where q2.id = p_quote;
  if not found then return b; end if;
  v_from := coalesce(public._a52_stage_idx(coalesce(q.lifecycle_stage, 'quote')), 4);
  v_to := public._a52_stage_idx(p_stage);
  if v_to is null or v_to <= v_from then return b; end if;            -- same / backward: no forward gate
  v_today := public._a198_org_today(q.org_id);
  if v_from < 5 and v_to >= 5 then                                    -- crosses 'confirmed'
    if coalesce(q.consent_stale, false) then
      b := b || jsonb_build_object('gate', 'confirmed', 'stale', true,
             'message', 'the price changed after the client approved - the client must approve again');
    elsif not public._a52_has_consent(p_quote) then
      b := b || jsonb_build_object('gate', 'confirmed',
             'message', 'the client has not approved the quote yet (OTP consent)');
    end if;
  elsif v_from < 6 and v_to >= 6 and coalesce(q.consent_stale, false) then   -- planning while stale
    b := b || jsonb_build_object('gate', 'planning', 'stale', true,
           'message', 'the price changed after the client approved - the client must approve again');
  end if;
  if v_from < 6 and v_to >= 6 then                                    -- crosses 'planning'
    if not exists (select 1 from public.event_plan p where p.quote_id = p_quote and p.menu_locked) then
      v_need := v_need || 'menu locked'::text;
    end if;
    if not exists (select 1 from public.quote_versions v where v.quote_id = p_quote and coalesce(v.object_count, 0) > 0) then
      v_need := v_need || 'layout v1'::text;
    end if;
    if cardinality(v_need) > 0 then
      b := b || jsonb_build_object('gate', 'planning', 'needs', to_jsonb(v_need),
             'message', 'Planning needs: ' || array_to_string(v_need, ', '));
    end if;
  end if;
  if v_from < 10 and v_to >= 10 and (q.event_date is null or q.event_date > v_today) then
    b := b || jsonb_build_object('gate', 'settlement',
           'message', case when q.event_date is null then 'the event has no date yet'
                           else 'the event date (' || to_char(q.event_date, 'DD Mon YYYY') || ') has not arrived' end);
  elsif v_from < 9 and v_to >= 9 and (q.event_date is null or q.event_date > v_today) then
    b := b || jsonb_build_object('gate', 'event_day',
           'message', case when q.event_date is null then 'the event has no date yet'
                           else 'Event Day opens on ' || public._a198_day(q.event_date) || ' (the event date)' end);
  end if;
  return b;
end $$;

create or replace function public.set_lifecycle_stage(p_quote_id uuid, p_stage text, p_override_reason text)
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
-- helm-0198-stages: 0084 body + confirmed floor, cancelled / closed lock, no-op, _a198 gates
declare v_org uuid := public.current_org_id(); v_cur text; v_status text; v_closed boolean; b jsonb;
        v_reason text := nullif(btrim(coalesce(p_override_reason, '')), ''); v_msg text;
begin
  if not public.has_area('quotes', 'edit') then raise exception 'not authorized' using errcode = '42501'; end if;
  if p_stage = 'closed' then raise exception 'Close the event from its Closure page.' using errcode = '22023'; end if;
  if public._a52_stage_idx(p_stage) is null then raise exception 'invalid stage: %', p_stage using errcode = '22023'; end if;
  select coalesce(q.lifecycle_stage, 'quote'), q.status into v_cur, v_status from public.quotes q
   where q.id = p_quote_id and q.org_id = v_org for update;
  if not found then raise exception 'no such event' using errcode = '42501'; end if;
  v_closed := v_cur = 'closed' or exists (select 1 from public.event_closure c where c.quote_id = p_quote_id and c.closed_at is not null);
  if v_closed then
    raise exception 'This event is closed - reopen it from its Closure page.' using errcode = '22023';
  end if;
  if p_stage = v_cur then return jsonb_build_object('stage', v_cur, 'unchanged', true); end if;   -- no write
  if coalesce(v_status, '') = 'cancelled' then
    raise exception 'This event is cancelled, so its stage can no longer change.' using errcode = '22023', hint = 'event_cancelled';
  end if;
  if coalesce(v_status, '') = 'confirmed' and public._a52_stage_idx(p_stage) < 5 then
    raise exception 'This event is confirmed, so it can''t go back to %. Use Cancel event if it will not happen.',
      public._a198_stage_label(p_stage) using errcode = '22023', hint = 'stage_confirmed_floor';
  end if;
  b := public._a198_stage_blockers(p_quote_id, p_stage);
  if jsonb_array_length(b) > 0 then
    select string_agg(x ->> 'message', '; ') into v_msg from jsonb_array_elements(b) x;
    if exists (select 1 from jsonb_array_elements(b) x where (x ->> 'stale')::boolean) then
      raise exception 'Can''t move to % - %.', public._a198_stage_label(p_stage), v_msg
        using errcode = 'HL428', detail = b::text, hint = 'Send the client a new approval link.';
    end if;
    if v_reason is null then
      raise exception 'Can''t move to % yet - %.', public._a198_stage_label(p_stage), v_msg
        using errcode = 'HL409', detail = b::text, hint = 'An admin can move it anyway with a reason.';
    end if;
    if coalesce(public.user_role(), '') <> 'admin' then
      raise exception 'Only an admin can skip a stage check (%).', v_msg using errcode = '42501';
    end if;
    if length(v_reason) < 5 or length(v_reason) > 1000 then
      raise exception 'override reason must be 5 to 1000 characters' using errcode = '22023';
    end if;
    insert into public.lifecycle_stage_overrides(org_id, quote_id, actor, actor_email, from_stage, to_stage, reason, blockers)
      values (v_org, p_quote_id, auth.uid(), (select u.email from auth.users u where u.id = auth.uid()),
              v_cur, p_stage, v_reason, b);
    insert into public.audit_log(actor, actor_email, action, entity, entity_id, quote_id, changed, org_id)
      values (auth.uid(), (select u.email from auth.users u where u.id = auth.uid()), 'stage_override', 'quotes',
              p_quote_id::text, p_quote_id,
              jsonb_build_object('from', v_cur, 'to', p_stage, 'reason', v_reason, 'blockers', b), v_org);
  end if;
  return public.set_lifecycle_stage__pre0052(p_quote_id, p_stage);
end $$;

-- read-only: what blocks a move (for the stage strip). Backward / hard rules come back as
-- {"hard": true} entries so the page can explain them without trying the move.
create or replace function public.lifecycle_stage_blockers(p_quote_id uuid, p_stage text)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
-- helm-0198-stages
declare q record;
begin
  if not public.has_area('quotes', 'view') then raise exception 'not authorized' using errcode = '42501'; end if;
  select q2.status, coalesce(q2.lifecycle_stage, 'quote') as stage into q
    from public.quotes q2 where q2.id = p_quote_id and q2.org_id = public.current_org_id();
  if not found then
    raise exception 'not authorized for this event' using errcode = '42501';
  end if;
  if public._a52_stage_idx(p_stage) is null then return '[]'::jsonb; end if;
  if q.stage = 'closed' or exists (select 1 from public.event_closure c where c.quote_id = p_quote_id and c.closed_at is not null) then
    return jsonb_build_array(jsonb_build_object('gate', 'closed', 'hard', true,
             'message', 'This event is closed - reopen it from its Closure page.'));
  end if;
  if coalesce(q.status, '') = 'cancelled' then
    return jsonb_build_array(jsonb_build_object('gate', 'cancelled', 'hard', true,
             'message', 'This event is cancelled, so its stage can no longer change.'));
  end if;
  if coalesce(q.status, '') = 'confirmed' and public._a52_stage_idx(p_stage) < 5 then
    return jsonb_build_array(jsonb_build_object('gate', 'confirmed_floor', 'hard', true,
             'message', 'This event is confirmed, so it can''t go back to ' || public._a198_stage_label(p_stage) || '.'));
  end if;
  return public._a198_stage_blockers(p_quote_id, p_stage);
end $$;

-- ---- 3) cancel event -------------------------------------------------------------------------
create table if not exists public.event_cancellations (
  id                   uuid primary key default gen_random_uuid(),
  org_id               uuid not null references public.organizations(id) on delete restrict,
  quote_id             uuid not null,
  actor                uuid,
  actor_email          text,
  reason               text not null check (length(btrim(reason)) between 5 and 1000),
  prev_status          text,
  prev_stage           text,
  prev_approval_status text,
  paid_at_cancel       numeric not null default 0,
  created_at           timestamptz not null default now()
);
create index if not exists event_cancellations_quote_idx on public.event_cancellations(org_id, quote_id);
alter table public.event_cancellations enable row level security;
revoke all on public.event_cancellations from public, anon, authenticated;
grant select on public.event_cancellations to authenticated;
grant all on public.event_cancellations to service_role;
drop policy if exists "a198 cancellations read" on public.event_cancellations;
create policy "a198 cancellations read" on public.event_cancellations for select to authenticated
  using (org_id = (select public.current_org_id()) and public.has_area('quotes', 'view'));

create or replace function public.cancel_event(p_quote_id uuid, p_reason text)
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
-- helm-0198-stages: an event that will not happen (status cancelled, everything else kept)
declare v_org uuid := public.current_org_id(); v_reason text := btrim(coalesce(p_reason, ''));
        q record; v_paid numeric; v_email text;
begin
  if not public.has_area('quotes', 'edit') then raise exception 'not authorized' using errcode = '42501'; end if;
  if coalesce(public.user_role(), '') not in ('admin', 'manager') then
    raise exception 'Only an admin or a manager can cancel an event.' using errcode = '42501';
  end if;
  if length(v_reason) < 5 or length(v_reason) > 1000 then
    raise exception 'Give a reason of 5 to 1000 characters for cancelling.' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('helm:pay:quote:' || coalesce(p_quote_id::text, ''), 0));
  select q2.id, q2.status, coalesce(q2.lifecycle_stage, 'quote') as stage, q2.approval_status, q2.deleted_at
    into q from public.quotes q2 where q2.id = p_quote_id and q2.org_id = v_org for update;
  if not found then raise exception 'not authorized for this event' using errcode = '42501'; end if;
  if q.status = 'cancelled' then return jsonb_build_object('status', 'cancelled', 'unchanged', true); end if;
  if q.deleted_at is not null then
    raise exception 'This event is in Deleted - restore it first.' using errcode = '22023';
  end if;
  if q.stage = 'closed' or exists (select 1 from public.event_closure c where c.quote_id = p_quote_id and c.closed_at is not null) then
    raise exception 'This event is closed - an admin can reopen it first if it has to be cancelled.' using errcode = '22023';
  end if;
  v_paid := coalesce(public.helm_total_paid(p_quote_id, null, null), 0);
  select u.email into v_email from auth.users u where u.id = auth.uid();
  insert into public.event_cancellations(org_id, quote_id, actor, actor_email, reason, prev_status, prev_stage,
                                         prev_approval_status, paid_at_cancel)
    values (v_org, p_quote_id, auth.uid(), v_email, v_reason, q.status, q.stage, q.approval_status, v_paid);
  update public.quotes qq
     set status = 'cancelled',
         approval_token_revoked_at = case when qq.approval_token is not null then coalesce(qq.approval_token_revoked_at, now())
                                          else qq.approval_token_revoked_at end,
         updated_at = now()
   where qq.id = p_quote_id;
  perform public._a42_expire_open_otps(p_quote_id);
  insert into public.audit_log(actor, actor_email, action, entity, entity_id, quote_id, changed, org_id)
    values (auth.uid(), v_email, 'event_cancelled', 'quotes', p_quote_id::text, p_quote_id,
            jsonb_build_object('reason', v_reason, 'from_status', q.status, 'stage', q.stage, 'paid', v_paid), v_org);
  return jsonb_build_object('status', 'cancelled', 'paid', v_paid, 'refund_to_review', v_paid > 0);
end $$;

-- ---- 4) calendar conflict acknowledgements ----------------------------------------------------
create table if not exists public.calendar_conflict_acks (
  id           uuid primary key default gen_random_uuid(),
  org_id       uuid not null references public.organizations(id) on delete restrict,
  quote_id     uuid not null,
  conflict_key text not null check (length(conflict_key) between 3 and 500),
  note         text check (note is null or length(note) <= 500),
  acked_by     uuid,
  acked_email  text,
  acked_at     timestamptz not null default now(),
  revoked_at   timestamptz,
  revoked_by   uuid
);
create unique index if not exists calendar_conflict_acks_open_uq
  on public.calendar_conflict_acks(org_id, conflict_key) where revoked_at is null;
create index if not exists calendar_conflict_acks_quote_idx on public.calendar_conflict_acks(org_id, quote_id);
alter table public.calendar_conflict_acks enable row level security;
revoke all on public.calendar_conflict_acks from public, anon, authenticated;
grant select on public.calendar_conflict_acks to authenticated;
grant all on public.calendar_conflict_acks to service_role;
drop policy if exists "a198 conflict acks read" on public.calendar_conflict_acks;
create policy "a198 conflict acks read" on public.calendar_conflict_acks for select to authenticated
  using (org_id = (select public.current_org_id()) and public.has_area('quotes', 'view'));

create or replace function public.ack_calendar_conflict(p_quote_id uuid, p_key text, p_note text)
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
-- helm-0198-stages
declare v_org uuid := public.current_org_id(); v_key text := btrim(coalesce(p_key, ''));
        v_note text := nullif(btrim(coalesce(p_note, '')), ''); v_id uuid;
begin
  if not public.has_area('quotes', 'edit') then raise exception 'not authorized' using errcode = '42501'; end if;
  if not exists (select 1 from public.quotes q where q.id = p_quote_id and q.org_id = v_org) then
    raise exception 'not authorized for this event' using errcode = '42501';
  end if;
  if length(v_key) < 3 or length(v_key) > 500 then raise exception 'invalid conflict key' using errcode = '22023'; end if;
  if v_note is not null and length(v_note) > 500 then raise exception 'Keep the note under 500 characters.' using errcode = '22023'; end if;
  select a.id into v_id from public.calendar_conflict_acks a
   where a.org_id = v_org and a.conflict_key = v_key and a.revoked_at is null;
  if v_id is null then
    insert into public.calendar_conflict_acks(org_id, quote_id, conflict_key, note, acked_by, acked_email)
      values (v_org, p_quote_id, v_key, v_note, auth.uid(), (select u.email from auth.users u where u.id = auth.uid()))
      on conflict do nothing
      returning id into v_id;
  end if;
  return jsonb_build_object('acknowledged', true, 'id', v_id, 'key', v_key);
end $$;

create or replace function public.unack_calendar_conflict(p_quote_id uuid, p_key text)
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
-- helm-0198-stages: nothing is deleted - the open acknowledgement is stamped revoked
declare v_org uuid := public.current_org_id(); n int;
begin
  if not public.has_area('quotes', 'edit') then raise exception 'not authorized' using errcode = '42501'; end if;
  if not exists (select 1 from public.quotes q where q.id = p_quote_id and q.org_id = v_org) then
    raise exception 'not authorized for this event' using errcode = '42501';
  end if;
  update public.calendar_conflict_acks a set revoked_at = now(), revoked_by = auth.uid()
   where a.org_id = v_org and a.conflict_key = btrim(coalesce(p_key, '')) and a.revoked_at is null;
  get diagnostics n = row_count;
  return jsonb_build_object('acknowledged', false, 'revoked', n);
end $$;

-- ---- 5) studio guards on the new tables (when this database has them) -----------------------
do $$ declare t text; begin
  foreach t in array array['event_cancellations', 'calendar_conflict_acks'] loop
    if to_regprocedure('public.tg_quote_org_match()') is not null then
      execute format('drop trigger if exists zz_quote_org_match on public.%I', t);
      execute format('create trigger zz_quote_org_match before insert or update on public.%I for each row execute function public.tg_quote_org_match()', t);
    end if;
    if to_regprocedure('public.tg_studio_read_only()') is not null then
      execute format('drop trigger if exists zzz_studio_read_only on public.%I', t);
      execute format('create trigger zzz_studio_read_only before insert or update or delete on public.%I for each row execute function public.tg_studio_read_only(%L)', t, 'org_id');
    end if;
  end loop;
end $$;

-- ---- 5b) trial retention (0184): the two new tables are this studio's event records -------------
-- An expired, never-paid trial's purge (0184, owner switch, off by default) empties them with the
-- rest of the events; without this they would only be reported as "unclassified" and kept.
-- Patched in place (text replace on the list, once); skipped when 0184 is not installed.
do $$ declare v_def text; begin
  if to_regprocedure('public._tr184_purge_tables()') is null then return; end if;
  v_def := pg_get_functiondef('public._tr184_purge_tables()'::regprocedure);
  if position('''event_cancellations''' in v_def) > 0 then return; end if;
  if position('''event_close_overrides'', ''lifecycle_stage_overrides'',' in v_def) = 0 then
    raise notice '0198: _tr184_purge_tables has an unexpected body - left unchanged'; return;
  end if;
  execute replace(v_def, '''event_close_overrides'', ''lifecycle_stage_overrides'',',
                  '''event_close_overrides'', ''lifecycle_stage_overrides'', ''event_cancellations'', ''calendar_conflict_acks'',');
end $$;

-- ---- 6) grants ---------------------------------------------------------------------------------
do $$ declare f text; begin
  foreach f in array array['_a198_org_today(uuid)', '_a198_stage_label(text)', '_a198_day(date)',
                           '_a198_stage_blockers(uuid, text)', '_a49_close_blockers(uuid)',
                           '_a49_blocker_text(jsonb)', '_a49_close_gate(uuid, text)'] loop
    execute 'revoke all on function public.' || f || ' from public';
    if exists (select 1 from pg_roles where rolname = 'anon') then execute 'revoke all on function public.' || f || ' from anon'; end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then execute 'revoke all on function public.' || f || ' from authenticated'; end if;
    if exists (select 1 from pg_roles where rolname = 'service_role') then execute 'grant execute on function public.' || f || ' to service_role'; end if;
  end loop;
  foreach f in array array['set_lifecycle_stage(uuid, text, text)', 'lifecycle_stage_blockers(uuid, text)',
                           'cancel_event(uuid, text)', 'ack_calendar_conflict(uuid, text, text)',
                           'unack_calendar_conflict(uuid, text)'] loop
    execute 'revoke all on function public.' || f || ' from public';
    if exists (select 1 from pg_roles where rolname = 'anon') then execute 'revoke all on function public.' || f || ' from anon'; end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then execute 'grant execute on function public.' || f || ' to authenticated'; end if;
    if exists (select 1 from pg_roles where rolname = 'service_role') then execute 'grant execute on function public.' || f || ' to service_role'; end if;
  end loop;
end $$;
commit;

