select item, ok from (values
  ('01 the sample copy includes event_requirements (after quotes)', array_position(public._sample_clone_tables(), 'event_requirements')
       > array_position(public._sample_clone_tables(), 'quotes') and array_length(public._sample_clone_tables(), 1) = 25),
  ('02 sample master: all 7 sample events have requirements (41)', (select count(*) from public.event_requirements
       where org_id = 'a5a5a5a5-0166-4000-8000-000000000001') >= 41
       and not exists (select 1 from public.quotes q where q.org_id = 'a5a5a5a5-0166-4000-8000-000000000001' and q.deleted_at is null
                         and not exists (select 1 from public.event_requirements r where r.quote_id = q.id))),
  ('03 the 0202 sample version was published once and is current (or a later one), with the requirements',
       (select count(*) from public.helm_trial_seed_manifest where notes = public._a202_manifest_note()) = 1
       and exists (select 1 from public.helm_trial_seed_manifest c where c.is_current
                     and c.version >= (select m.version from public.helm_trial_seed_manifest m where m.notes = public._a202_manifest_note())
                     and jsonb_array_length(coalesce(c.payload #> '{tables,event_requirements}', '[]'::jsonb)) >= 41)),
  ('05 sample master: every event with a budget / guests on its CRM lead has them on the quote too (0199 rule)',
       not exists (select 1 from public.quotes q join public.leads l on l.quote_id = q.id and l.org_id = q.org_id
                    where q.org_id = 'a5a5a5a5-0166-4000-8000-000000000001' and q.deleted_at is null
                      and ((l.budget is not null and nullif(btrim(coalesce(q.client ->> 'budget', '')), '') is null)
                        or (l.guest_count is not null and nullif(btrim(coalesce(q.client ->> 'guests', '')), '') is null)))),
  ('04 app roles cannot run the 0202 helpers', not has_function_privilege('authenticated', 'public._a202_sample_requirements()', 'execute')
       and not has_function_privilege('anon', 'public._a202_sample_requirements()', 'execute')
       and not has_function_privilege('authenticated', 'public._a202_manifest_note()', 'execute'))
) v(item, ok) order by item;

-- ##########################################################################################
-- RELEASE SECTION 28/28: APPLY-0178-refresh-trials.sql
-- In plain words: LAST: every existing FREE-TRIAL studio is refreshed to the newest sample (its sample rows re-cloned, its own rows kept).
-- ##########################################################################################
-- APPLY-0178-refresh-trials.sql -- paste into the Supabase SQL editor (runs as postgres; no auth.uid()).
-- Refreshes EVERY existing trial studio (studio_subscriptions.status = 'trial', never the sample master)
-- to the CURRENT published sample manifest (v5 or later; e.g. v6 after 0175):
--   1 _demo_clear(org)       removes ONLY that studio's is_demo rows (studio-created rows are never touched)
--   2 sample_cloned_at/batch/version reset, then _demo_seed(org) re-clones via the 0166-0171 path
--   3 trial studios set to INR / Asia/Kolkata / IN / tax_region 'IN' (GST)
-- Idempotent: a studio already on the current manifest is skipped (set v_force := true to redo it).
-- Venues are never deleted (0085 rule): _demo_clear DEACTIVATES old sample venues, so a forced redo
-- leaves one more inactive copy per sample venue; the skip keeps a plain re-run from piling them up.
-- Sample venues are named 'Demo \u00b7 ...' (E-string in VERIFY) (0167 master); VERIFY counts the 4 ACTIVE ones. Outbound stays quiet (helm.maintenance on + trial outbox skip).
-- The sample switch is turned on for the clone only and restored to its previous value afterwards.

-- ---- 1) BEFORE: diagnostics --------------------------------------------------------------------
select o.id, o.name, o.currency, o.timezone, o.country, o.tax_region, o.sample_cloned_at, o.sample_version,
       (select string_agg(v.name, ' | ' order by v.name) from public.venues v where v.org_id = o.id) as venues,
       (select count(*) from public.venues v where v.org_id = o.id and not v.is_demo) as own_venues
  from public.organizations o
  join public.studio_subscriptions s on s.org_id = o.id and s.status = 'trial'
 where o.id <> 'a5a5a5a5-0166-4000-8000-000000000001' and not coalesce(o.is_sample_master, false)
 order by o.created_at;

-- ---- 2) REFRESH ----------------------------------------------------------------------------------
do $$
declare
  M constant uuid := 'a5a5a5a5-0166-4000-8000-000000000001';
  v_force constant boolean := false; v_cur integer; v_was boolean; o record; r jsonb; n integer := 0;
begin
  perform set_config('helm.maintenance', 'on', true);
  select m.version into v_cur from public.helm_trial_seed_manifest m where m.is_current;
  if v_cur is null or v_cur < 5 then raise exception 'current sample manifest is %, expected 5 or later - stopping', v_cur; end if;
  select t.active into v_was from public.helm_sample_template t where t.id;
  update public.helm_sample_template set active = true where id and not active;

  for o in select x.id from public.organizations x
             join public.studio_subscriptions s on s.org_id = x.id and s.status = 'trial'
            where x.id <> M and not coalesce(x.is_sample_master, false)
              and (v_force or x.sample_version is distinct from v_cur or x.sample_cloned_at is null
                   or (x.currency, x.timezone, x.country, coalesce(x.tax_region, '')) is distinct from ('INR', 'Asia/Kolkata', 'IN', 'IN'))
            order by x.id for update of x loop
    perform public._demo_clear(o.id);
    update public.organizations
       set sample_cloned_at = null, sample_batch_id = null, sample_version = null,
           currency = 'INR', timezone = 'Asia/Kolkata', country = 'IN', tax_region = 'IN'
     where id = o.id;
    r := public._demo_seed(o.id);
    if coalesce((r ->> 'cloned')::boolean, false) is not true then
      raise exception 'clone failed for %: %', o.id, r; end if;
    -- the clone copies the master's studio settings; keep India regardless
    update public.organizations set currency = 'INR', timezone = 'Asia/Kolkata', country = 'IN', tax_region = 'IN'
     where id = o.id and (currency, timezone, country, coalesce(tax_region, '')) is distinct from ('INR', 'Asia/Kolkata', 'IN', 'IN');
    n := n + 1;
  end loop;

  update public.helm_sample_template set active = v_was where id and active is distinct from v_was;
  raise notice 'refreshed % trial studio(s) to manifest v%', n, v_cur;
end $$;

-- ---- 3) VERIFY: every row should say ok = true ---------------------------------------------------
select o.id, o.name, o.sample_version, o.currency, o.timezone, o.country, o.tax_region,
       (select count(*) from public.venues v where v.org_id = o.id and v.is_demo and v.active and v.name like E'Demo \u00b7 %') as active_sample_venues,
       (select count(*) - count(distinct v.name) from public.venues v where v.org_id = o.id and v.is_demo and v.active) as dup_venues,
       (select count(*) from public.comms_outbox c where c.org_id = o.id and c.status = 'pending') as pending_outbox,
       ( o.sample_version = (select m.version from public.helm_trial_seed_manifest m where m.is_current) and o.currency = 'INR' and o.timezone = 'Asia/Kolkata' and o.country = 'IN'
         and (select count(*) from public.venues v where v.org_id = o.id and v.is_demo and v.active and v.name like E'Demo \u00b7 %') = 4
         and (select count(*) - count(distinct v.name) from public.venues v where v.org_id = o.id and v.is_demo and v.active) = 0
         and not exists (select 1 from public.comms_outbox c where c.org_id = o.id and c.status = 'pending') ) as ok
  from public.organizations o
  join public.studio_subscriptions s on s.org_id = o.id and s.status = 'trial'
 where o.id <> 'a5a5a5a5-0166-4000-8000-000000000001' and not coalesce(o.is_sample_master, false)
 order by ok, o.created_at;

-- ##########################################################################################
-- RELEASE COMBINED VERIFY (read-only): every row must say ok = true
-- ##########################################################################################
select '0173 ' || item as item, ok from (values
  ('01 cap trigger on 6 tables', (select count(*) from pg_trigger where tgname = 'zzzz_tl173_cap') = 6),
  ('02 no-add trigger on 4 catalog tables', (select count(*) from pg_trigger where tgname = 'zzzz_tl173_no_add') = 4),
  ('03 studio-settings trigger on organizations', exists (select 1 from pg_trigger where tgrelid = 'public.organizations'::regclass and tgname = 'zzzz_tl173_org_lock')),
  ('04 11 RPCs wrapped (original kept)', (select count(*) from pg_proc where pronamespace = 'public'::regnamespace and proname like '%\_\_pre0173') = 11),
  ('05 wrappers carry the trial check', (select count(*) from pg_proc p where p.pronamespace = 'public'::regnamespace and position('trial-lockdown-0173' in p.prosrc) > 0
       and to_regprocedure('public.' || p.proname || '__pre0173(' || oidvectortypes(p.proargtypes) || ')') is not null) = 11),
  ('06 kept originals not callable by the app', not exists (select 1 from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname like '%\_\_pre0173'
       and (has_function_privilege('anon', p.oid, 'execute') or has_function_privilege('authenticated', p.oid, 'execute')))),
  ('07 export_org_data still callable by signed-in users', has_function_privilege('authenticated', 'public.export_org_data()', 'execute')),
  ('08 my_trial_limits callable by signed-in users', has_function_privilege('authenticated', 'public.my_trial_limits()', 'execute')),
  ('09 trigger functions not callable by the app', not has_function_privilege('authenticated', 'public._tl173_tg_create_cap()', 'execute')
       and not has_function_privilege('authenticated', 'public._tl173_tg_no_add()', 'execute') and not has_function_privilege('authenticated', 'public._tl173_tg_org_lock()', 'execute')),
  ('11 trial studios affected: ' || (select count(*) from public.studio_subscriptions where status = 'trial')::text, true)
) v(item, ok)
union all
select '0174 ' || item as item, ok from (values
  ('01 _demo_seed is the 0174 version', position('trial-seed-0174' in (select prosrc from pg_proc where oid = 'public._demo_seed(uuid)'::regprocedure)) > 0),
  ('02 _demo_seed_for is the 0174 version', position('trial-seed-0174' in (select prosrc from pg_proc where oid = 'public._demo_seed_for(uuid)'::regprocedure)) > 0),
  ('03 app roles cannot call the seeders', not has_function_privilege('authenticated', 'public._demo_seed(uuid)', 'execute')
       and not has_function_privilege('authenticated', 'public._demo_seed_for(uuid)', 'execute')),
  ('05 trial check uses _is_trial_org, not trial_ends_at', position('_is_trial_org' in (select prosrc from pg_proc where oid = 'public._demo_seed(uuid)'::regprocedure)) > 0
       and position('trial_ends_at' in (select prosrc from pg_proc where oid = 'public._demo_seed(uuid)'::regprocedure)) = 0
       and position('_is_trial_org' in (select prosrc from pg_proc where oid = 'public._demo_seed_for(uuid)'::regprocedure)) > 0
       and position('trial_ends_at' in (select prosrc from pg_proc where oid = 'public._demo_seed_for(uuid)'::regprocedure)) = 0),
  ('04 switch on + manifest current (false = sample switch still off)', public._sample_template_ready())
) v(item, ok)
union all
